# Tema: se elige con el interruptor de la barra lateral (clave "light_theme")
# v2 · diseño «Prodigio»: carbono + amarillo La Sportiva + blanco espuma, con textura de malla. El tema va en la URL
# (?tema=claro|oscuro) para que se conserve al recargar.
# El tema en uso vive en «theme_val» (no es clave de widget), igual que el color: no se pierde si el control se reinicia.
if st.session_state.get("theme_val") not in ("☀️", "🌙"):          # por defecto, tema claro
    st.session_state["theme_val"] = "🌙" if str(st.query_params.get("tema", "")).lower() == "oscuro" else "☀️"
if st.session_state.get("nav_val") not in ("lateral", "superior"):
    st.session_state["nav_val"] = "superior" if str(st.query_params.get("menu", "")).lower() == "superior" else "lateral"
if st.session_state.get("nav_mode_w") != st.session_state["nav_val"]:
    st.session_state["nav_mode_w"] = st.session_state["nav_val"]
NAV_MODE = st.session_state["nav_val"]
if st.session_state.get("theme_icon") != st.session_state["theme_val"]:
    st.session_state["theme_icon"] = st.session_state["theme_val"]
LIGHT = st.session_state["theme_val"] == "☀️"
# En la dirección solo queda ?tema=oscuro: el claro es el de siempre, así un acceso directo guardado no fija ningún tema.
if not LIGHT and str(st.query_params.get("tema", "")).lower() != "oscuro":
    st.query_params["tema"] = "oscuro"
elif LIGHT and "tema" in st.query_params:
    del st.query_params["tema"]
PALETTES_V1 = {
    "dark": dict(GOLD="#f5c400", GLACIER="#4cc0e6", RED="#e8402f", GREEN="#3cb46a", VIOLET="#a58bd6", ORANGE="#f08a3c",
                 TEAL="#3fb8a6", INK="#f3f2ec", MUTED="#8e989f", PREV="#5d676e", LINE="#262d33", GRID="#1d2328",
                 SURFACE="#13171b", BG="#0a0c0e", SURFACE2="#1a1f24", ZEBRA="#1b2126", HOVER="#252d34", ZERO="#3a444c"),
    "light": dict(GOLD="#c99700", GLACIER="#1d86ad", RED="#cf3427", GREEN="#2b8f52", VIOLET="#7a5fc0", ORANGE="#d26a17",
                  TEAL="#1f8f81", INK="#1c2420", MUTED="#5f6b66", PREV="#9aa59f", LINE="#d3dad6", GRID="#e7ece9",
                  SURFACE="#ffffff", BG="#f3f5f2", SURFACE2="#eef1ee", ZEBRA="#f5f7f5", HOVER="#e6ece8", ZERO="#bcc6c1"),
}
# Color principal (por defecto el amarillo de la zapatilla); se elige en Ajustes y va en la URL (?color=ffe100)
ACC_DEF = "#ffe100"
# El color en uso vive en «acc_val» (no es la clave de ningún widget): si Streamlit reinicia el selector de color al
# volver a ejecutar la página por otro control (p. ej. un interruptor de Ajustes), el color no se pierde ni pasa a negro.
_HEX = re.compile(r"#[0-9a-fA-F]{6}")


def _acc_ok(v) -> bool:
    """Color principal válido: hex de 6 cifras y no casi negro. El selector de color de algunos navegadores (sobre todo en
    el móvil) devuelve #000000 al abrirlo y cerrarlo sin elegir; un principal negro no se vería en el tema oscuro."""
    v = str(v or "")
    if not _HEX.fullmatch(v):
        return False
    r_, g_, b_ = (int(v[i:i + 2], 16) for i in (1, 3, 5))
    return (0.2126 * r_ + 0.7152 * g_ + 0.0722 * b_) > 28


if not _acc_ok(st.session_state.get("acc_val")):
    _qc = "#" + str(st.query_params.get("color", "")).strip().lstrip("#").lower()
    st.session_state["acc_val"] = _qc if _acc_ok(_qc) else ACC_DEF
ACC = st.session_state["acc_val"].lower()
if st.query_params.get("color") and not _acc_ok("#" + str(st.query_params.get("color")).strip().lstrip("#").lower()):
    del st.query_params["color"]                # p. ej. un marcador antiguo con ?color=000000
if ACC != ACC_DEF and str(st.query_params.get("color", "")).lower() != ACC[1:]:
    st.query_params["color"] = ACC[1:]          # siempre en la URL: una sesión nueva (reconexión) lo recupera


def _acc_pick():
    v = str(st.session_state.get("sb_accent_w") or "")
    if _acc_ok(v):
        st.session_state["acc_val"] = v.lower()
        st.query_params["color"] = v.lstrip("#").lower()


def _acc_reset():
    st.session_state["acc_val"] = ACC_DEF
    st.session_state.pop("sb_accent_w", None)
    st.query_params["color"] = ACC_DEF[1:]


def _mix(c1: str, c2: str, w: float) -> str:
    """Mezcla dos colores hex (w = peso de c2)."""
    a_, b_ = [int(c1[i:i + 2], 16) for i in (1, 3, 5)], [int(c2[i:i + 2], 16) for i in (1, 3, 5)]
    return "#" + "".join(f"{round(x * (1 - w) + y * w):02x}" for x, y in zip(a_, b_))


def _lum(c: str) -> float:
    r_, g_, b_ = [int(c[i:i + 2], 16) / 255 for i in (1, 3, 5)]
    f_ = lambda v: v / 12.92 if v <= 0.03928 else ((v + 0.055) / 1.055) ** 2.4  # noqa: E731
    return 0.2126 * f_(r_) + 0.7152 * f_(g_) + 0.0722 * f_(b_)


# En claro, el acento se oscurece hasta leerse sobre blanco (contraste ≥ 3:1)
_ACC_L = ACC
for _i in range(12):
    if (1.05) / (_lum(_ACC_L) + 0.05) >= 3.0:
        break
    _ACC_L = _mix(_ACC_L, "#000000", 0.12)
PALETTES = {
    # Oscuro «Carbono»: empeine negro de malla técnica con detalles amarillos
    "dark": dict(GOLD=ACC, GLACIER="#6cc4ea", RED="#ff5a3d", GREEN="#9bd62f", VIOLET="#b9a2e6", ORANGE="#ff9b2f",
                 TEAL="#44c9b4", INK="#f4f4ef", MUTED="#9b9d9f", PREV="#5f6265", LINE="#2b2d2f", GRID="#1f2022",
                 SURFACE="#141516", BG="#0b0b0c", SURFACE2="#1b1c1e", ZEBRA="#18191a", HOVER="#26282a", ZERO="#3e4043"),
    # Claro «Espuma»: mediasuela blanca roto con el amarillo como acento (algo más oscuro para leerse sobre blanco)
    "light": dict(GOLD=_ACC_L if ACC != ACC_DEF else "#c4a400", GLACIER="#1f7fae", RED="#d63b22", GREEN="#5c9a12", VIOLET="#7656c4", ORANGE="#d9700f",
                  TEAL="#16907e", INK="#121314", MUTED="#5d5e5b", PREV="#a3a49e", LINE="#d9d7cd", GRID="#ebe9e0",
                  SURFACE="#ffffff", BG="#f3f2ec", SURFACE2="#ecebe3", ZEBRA="#f8f7f2", HOVER="#e8e6da", ZERO="#c3c1b6"),
}
YEL, CARBON = ACC, "#0b0b0c"
ACC_ON = CARBON if _lum(ACC) > 0.3 else "#ffffff"      # texto sobre el color principal      # amarillo y negro de la zapatilla: la barra superior es igual en los dos temas
_P = PALETTES["light" if LIGHT else "dark"]
GOLD, GLACIER, RED, GREEN = _P["GOLD"], _P["GLACIER"], _P["RED"], _P["GREEN"]
VIOLET, ORANGE, TEAL, INK = _P["VIOLET"], _P["ORANGE"], _P["TEAL"], _P["INK"]
MUTED, PREV, LINE, GRID, SURFACE, BG = _P["MUTED"], _P["PREV"], _P["LINE"], _P["GRID"], _P["SURFACE"], _P["BG"]
SURFACE2, ZEBRA, HOVER, ZERO = _P["SURFACE2"], _P["ZEBRA"], _P["HOVER"], _P["ZERO"]


def rgb(hex_color: str) -> str:
    return ",".join(str(int(hex_color[i:i + 2], 16)) for i in (1, 3, 5))


def rgba(hex_color: str, a: float) -> str:
    return f"rgba({rgb(hex_color)},{a})"


def on(hex_color: str) -> str:
    """Color de texto legible sobre un fondo dado."""
    r, g, b = (int(hex_color[i:i + 2], 16) / 255 for i in (1, 3, 5))
    return "#0a0c0e" if (0.2126 * r + 0.7152 * g + 0.0722 * b) > 0.45 else "#ffffff"




