# Widgets nativos con los colores del tema (en v2 en los dos temas, sea cual sea el tema base de Streamlit)
# Las tablas editables (st.data_editor) se pintan en un <canvas> con los colores del tema base de Streamlit (config.toml), que el
# CSS no alcanza. Si el tema elegido en Ajustes es el contrario al tema base, se invierten sus colores (y se rota el tono para
# que el color principal y los de las celdas no cambien): fondo claro con texto oscuro en el tema claro, y al revés.
# Color principal recordado en este navegador (localStorage). Una sesión nueva abierta sin ?color en la dirección (p. ej. desde la
# pantalla de inicio del móvil) recupera el último elegido; en otro caso se guarda el actual. El tema NO se recuerda: la app
# siempre arranca en claro (salvo un enlace con ?tema=oscuro). Se borra el tema que guardaba la versión anterior.
st.html(f"""<script>
(function () {{
  try {{
    var LS = window.localStorage, url = new URL(window.location.href), cur = "{ACC[1:]}";
    var had = {str(bool(st.query_params.get("color"))).lower()}, saved = LS.getItem("llibreta_color");
    LS.removeItem("llibreta_tema");
    if (!had && !sessionStorage.getItem("llibreta_prefs_done") && /^[0-9a-f]{{6}}$/.test(saved || "") && saved !== cur) {{
      sessionStorage.setItem("llibreta_prefs_done", "1");
      url.searchParams.set("color", saved);
      window.location.replace(url.toString());
      return;
    }}
    sessionStorage.setItem("llibreta_prefs_done", "1");
    LS.setItem("llibreta_color", cur);
  }} catch (e) {{}}
}})();
</script>""", unsafe_allow_javascript=True)
# Primero el tema que el navegador tiene activo de verdad (puede haberlo cambiado en el menú de Streamlit); si aún no se
# conoce (primera ejecución), el de .streamlit/config.toml (claro).
try:
    _base = str(getattr(getattr(st.context, "theme", None), "type", "") or "").lower()
except Exception:  # noqa: BLE001
    _base = ""
if _base not in ("dark", "light"):
    try:
        _base = str(st.get_option("theme.base") or "light").lower()
    except Exception:  # noqa: BLE001
        _base = "light"
_BASE_LIGHT = _base == "light"
_GRID_FIX = ("" if LIGHT == _BASE_LIGHT else
             '[data-testid="stDataFrameResizable"] canvas {{ '
             'filter: invert(1) hue-rotate(180deg); }}').replace("{{", "{").replace("}}", "}")
