def _bg_raw(z: str) -> str:
    import zlib as _zl
    return _zl.decompress(base64.b64decode(z)).decode("utf-8")


@st.cache_data(show_spinner=False)
def _bg_svg(kind: str, ink: str, gold: str, light: bool) -> str:
    """SVG del fondo con el color del tema y transparencia muy baja, como data URI."""
    k_ = {"dark": 1.0, "light": 1.0}["light" if light else "dark"]
    svg = ""
    try:
        if kind == "curvas":
            svg = _bg_raw(_BG_TOPO_Z)
            svg = svg.replace('stroke="#000"', f'stroke="{ink}" stroke-opacity="{(0.12 if light else 0.13):.3f}"')
        elif kind == "crestas":
            svg = _bg_raw(_BG_CRESTAS_Z)
            svg = svg.replace("<svg ", f'<svg fill="{ink}" fill-opacity="{(0.09 if light else 0.10):.3f}" ', 1)
        elif kind == "perfil":
            # Perfil real de Cavalls del Vent (races/cavalls.gpx): silueta muy suave y la línea en amarillo
            _root = os.path.dirname(_ASSETS)
            _cands = [os.path.join(d_, f_) for d_ in (os.path.join(_root, "races"), _root) if os.path.isdir(d_)
                      for f_ in sorted(os.listdir(d_))
                      if f_.lower() in ("cavalls.gpx", "festival-cavalls-de-vent-2026-reducido.gpx")]
            if not _cands:
                return ""
            txt = open(_cands[0], encoding="utf-8", errors="replace").read()
            pts = np.array(re.findall(r'<trkpt lat="([\d.\-]+)" lon="([\d.\-]+)"[^>]*>\s*<ele>([\d.\-]+)</ele>', txt), dtype=float)
            la, lo, el = pts[:, 0], pts[:, 1], pts[:, 2]
            d = np.concatenate([[0], np.cumsum(np.hypot(np.diff(la) * 110.5, np.diff(lo) * 111.3 * np.cos(np.radians(la[1:]))))])
            g = np.linspace(0, d[-1], 400)
            e = pd.Series(np.interp(g, d, el)).rolling(5, center=True, min_periods=1).mean().to_numpy()
            W, H = 1600, 1000
            xs = g / d[-1] * W
            ys = H - 30 - (e - e.min()) / (e.max() - e.min()) * 260
            line = " L".join(f"{x_:.0f},{y_:.0f}" for x_, y_ in zip(xs, ys))
            svg = (f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {W} {H}" preserveAspectRatio="xMidYMax slice">'
                   f'<path d="M0,{H} L{line} L{W},{H} Z" fill="{ink}" fill-opacity="{(0.07 if light else 0.08):.3f}"/>'
                   f'<path d="M{line}" fill="none" stroke="{gold}" stroke-opacity="{(0.28 if light else 0.24):.2f}" stroke-width="1.8"/></svg>')
    except Exception:  # noqa: BLE001
        return ""
    return "data:image/svg+xml;base64," + base64.b64encode(svg.encode("utf-8")).decode("ascii") if svg else ""


