def plan_fig(S, metric="load", h=280, mini=False):
    W, A, ci = S["W"], S["A"], S["ci"]
    x = [f"S{w['i'] + 1}" for w in W]
    tgt = [w[metric] for w in W]
    col = [RED if w["k"] == "R" else GLACIER if w["k"] == "r" else PREV for w in W]
    f = go.Figure()
    f.add_bar(x=x, y=tgt, marker_color=col, opacity=.55, name="Objetivo", width=.85,
              customdata=[[f"{w['frm']:%d/%m}", w["ph"]] for w in W],
              hovertemplate="%{x} · %{customdata[0]} · %{customdata[1]}<br>objetivo %{y:,.0f}<extra></extra>")
    real = [A[i][metric] if W[i]["frm"] <= today else None for i in range(len(W))]
    f.add_bar(x=x, y=real, marker_color=GOLD, name="Real", width=.45,
              hovertemplate="%{x} · real %{y:,.0f}<extra></extra>")
    f.update_layout(barmode="overlay", bargap=.1)
    if ci >= 0:
        f.add_vrect(x0=ci - .5, x1=ci + .5, line=dict(color=GOLD, width=1, dash="dot"), fillcolor=rgba(GOLD, .06))
    if not mini:
        for r in S["races"]:
            i = next((w["i"] for w in W if w["frm"] <= r["d"] <= w["to"]), None)
            if i is not None:
                f.add_annotation(x=x[i], y=max(tgt) * 1.12, text=_html.escape(r["name"].split()[0] if r["name"].split() else r["name"]),
                                 showarrow=False, font=dict(color=r["c"], size=11))
        tick = [x[w["i"]] for w in W if w["frm"].day <= 7]
        f.update_xaxes(tickvals=tick, ticktext=[MES[w["frm"].month - 1] for w in W if w["frm"].day <= 7])
        f.update_yaxes(range=[0, max(tgt + [v or 0 for v in real] + [1]) * 1.2], ticksuffix=" m" if metric == "dp" else "")
    return f


def _plan_event(t: dict, evs: list[dict]) -> dict | None:
    """Evento del calendario de intervals.icu de una sesión: la calidad lo lleva en su id; fuerza y cinta, por día y tipo."""
    if str(t["sid"]).startswith("CAL-"):
        eid = str(t["sid"])[4:]
        return next((e for e in evs if str(e.get("id")) == eid), {"id": eid})
    typ = {"fuerza": ("WeightTraining", "Workout"), "cinta": ("VirtualRun",)}.get(t["s"]["kind"], ())
    c_ = [e for e in evs if e.get("category") == "WORKOUT" and e.get("type") in typ and _d(e.get("start_date_local")) == t["orig"]]
    return c_[0] if c_ else None


def plan_adjust_ui(S, wi: int, todo: list):
    """Ajustar las sesiones de la semana: hecha otro día (con qué actividad), no hecha o cambiada de día."""
    w = S["W"][wi]
    msg = st.session_state.pop("padj_msg", None)
    if msg:
        st.success(tr("Ajustes guardados") + (f' · {tr("emparejadas en intervals.icu")}: ' + ", ".join(msg[0]) if msg[0] else ""))
        for e_ in msg[1]:
            st.warning(e_)
    with st.expander("Ajustar las sesiones de la semana · cambios de día y sesiones no hechas", key="padj_exp"):
        st.markdown('<div class="note">El emparejamiento automático busca, para cada sesión, una actividad del mismo tipo (fuerza, '
                    'cinta o carrera por fuera) el mismo día y, si no la hay, otro día de la semana (la calidad, solo en los 2 días '
                    'siguientes); cada actividad cuenta una sola vez. '
                    'Si no acierta, o si una sesión pasa a otro día o no se va a hacer, indícalo aquí. ↷ = hecha otro día.</div>',
                    unsafe_allow_html=True)
        adj_all = plan_adj()
        lo, hi = w["frm"], min(w["to"] + dt.timedelta(days=7), today)
        acts = all_df[(all_df["date"] >= lo) & (all_df["date"] <= hi) & all_df["sport"].isin(GIM | CINTA | OUT)].sort_values("ts") \
            if len(all_df) else all_df
        alab = {str(r_["id"]): f'{tr("Hecha con")}: {DIAS_L[r_["date"].weekday()][:3]} {r_["date"]:%d/%m} · '
                               f'{str(r_["name"] or r_["sport"])[:34]} · {int(round(r_["secs"] / 60))} min'
                for _, r_ in acts.iterrows()} if len(acts) else {}
        new_adj = {}
        for t in todo:
            k_ = t["key"]
            cur = t["adj"]
            auto_txt = (f'{tr("Automático")}: ' + (tr("hecha") if t["st"] == "hecha" else
                        f'{tr("hecha el")} {t["act"]["date"]:%d/%m}' if t["act"] is not None else tr("sin actividad")))
            opts = ["auto"] + list(alab) + ["skip", "move"]
            lab = {"auto": auto_txt, "skip": tr("No hecha"), "move": tr("Pasa a otro día…"), **alab}
            dflt = ("skip" if cur.get("skip") else "move" if cur.get("move") else
                    str(cur.get("act")) if str(cur.get("act") or "") in alab else "auto")
            c1, c2, c3 = st.columns([2.2, 3, 1.4], vertical_alignment="center")
            c1.markdown(f'<b>{DIAS_L[t["orig"].weekday()][:3]} {t["orig"]:%d/%m}</b> · {KIND_L[t["s"]["kind"]]}: '
                        f'{_html.escape(t["s"]["name"][:38])}', unsafe_allow_html=True)
            v = c2.selectbox("Estado", opts, index=opts.index(dflt), format_func=lambda o, lab=lab: lab.get(o, o),
                             key=f"padj_{k_}", label_visibility="collapsed")
            if v == "move":
                d0 = _d(cur.get("move")) or (t["orig"] + dt.timedelta(days=1))
                nd = c3.date_input("Nuevo día", d0, key=f"padjd_{k_}", format="DD/MM/YYYY", label_visibility="collapsed")
                if nd != t["orig"]:
                    new_adj[k_] = {"move": nd.isoformat()}
            elif v == "skip":
                new_adj[k_] = {"skip": 1}
            elif v != "auto":
                new_adj[k_] = {"act": v}
        week_keys = {t["key"] for t in todo}
        old_w = {k2: v2 for k2, v2 in adj_all.items() if k2 in week_keys}
        changed = new_adj != old_w
        sync = st.checkbox("Emparejar también en intervals.icu (el plan no se modifica)", value=not demo, key="padj_sync", disabled=demo,
                           help="Para las sesiones «Hecha con»: enlaza la actividad con el entrenamiento planificado de su día original, "
                                "que queda como hecho en intervals.icu. El entrenamiento no se mueve ni se cambia.")
        b1, b2 = st.columns([1, 3], vertical_alignment="center")
        if b1.button("Guardar los ajustes", type="primary", key="padj_save", width="stretch", disabled=not changed):
            keep = {k2: v2 for k2, v2 in adj_all.items() if k2 not in week_keys}
            keep.update(new_adj)
            done_, errs_ = [], []
            if sync and not demo:
                try:
                    evs = fetch_events(athlete, key, (w["frm"] - dt.timedelta(days=1)).isoformat(),
                                       (w["to"] + dt.timedelta(days=8)).isoformat())
                except Exception as e:  # noqa: BLE001
                    evs, errs_ = [], [str(e)]
                for t in todo:
                    a_ = new_adj.get(t["key"])
                    if not a_ or a_ == old_w.get(t["key"]) or not a_.get("act"):
                        continue
                    ev = _plan_event(t, evs)
                    if not ev or not ev.get("id"):
                        errs_.append(f'{t["s"]["name"]}: {tr("no se encontró en el calendario")}')
                        continue
                    try:   # solo el enlace actividad → entrenamiento planificado; el evento del plan no se toca
                        icu_write("PUT", f"/activity/{a_['act']}", {"paired_event_id": int(ev["id"])})
                        done_.append(t["s"]["name"])
                    except Exception as e:  # noqa: BLE001
                        errs_.append(f'{t["s"]["name"]}: {e}')
                fetch_events.clear()
            try:
                app_note_save(PLANADJ_NAME, "demo_planadj", {"v": 1, "s": keep})
                for k2 in list(st.session_state):
                    if str(k2).startswith(("padj_", "padjd_")) and k2 not in ("padj_exp", "padj_sync"):
                        st.session_state.pop(k2, None)
                st.session_state["padj_msg"] = (done_, errs_)
                st.rerun()
            except Exception as e:  # noqa: BLE001
                st.error(f"{tr('No se pudo guardar')}: {e}")
        b2.markdown('<span class="note">' + ("Se guarda en la sesión (DEMO)." if demo else
                    "Los ajustes se guardan en intervals.icu en una nota del calendario del 01/01/2000 («Llibreta D+ · ajustes del plan»). "
                    "Con la casilla marcada, la actividad elegida en «Hecha con» se enlaza en intervals.icu con el entrenamiento "
                    "planificado de su día original; el plan no se mueve ni se modifica. «Pasa a otro día» y «No hecha» solo "
                    "cambian lo que muestra la app.") + "</span>",
                    unsafe_allow_html=True)


def plan_phases_ui(S):
    """Fases en un solo bloque: línea de tiempo de las semanas (fase, descargas, carreras y semana en curso) y la ficha de la
    fase o semana tipo elegida, con sus claves, los objetivos semanales y los ejercicios de cada sesión."""
    W, ci = S["W"], S["ci"]
    ph = S["phases"]
    col_of = {}
    for p in ph:
        for i in range(p["frm"], p["to"] + 1):
            col_of[i] = p["c"]
    seg = "".join(f'<div class="{"now" if p["frm"] <= ci <= p["to"] else ""}" style="--c:{p["c"]};flex:{p["to"] - p["frm"] + 1}">'
                  f'<b>{_html.escape(p["t"])}</b><span>{p["a"]:%d/%m} – {p["b"]:%d/%m}</span></div>' for p in ph)
    wk = "".join(f'<i class="{w["k"] if w["k"] in ("r", "t", "R") else ""}{" cur" if w["i"] == ci else " past" if 0 <= w["i"] < ci or w["to"] < today else ""}" '
                 f'style="--c:{col_of.get(w["i"], PREV)}" title="S{w["i"] + 1} · {w["frm"]:%d/%m} · {_html.escape(w["ph"])}'
                 f'{" · " + {"r": "descarga", "t": "taper", "R": "carrera"}[w["k"]] if w["k"] in ("r", "t", "R") else ""}"></i>' for w in W)
    leg = (f'<i style="background:{MUTED};opacity:.3"></i>{tr("descarga o taper")}<i style="background:{RED}"></i>{tr("carrera")}'
           f'<i style="background:transparent;box-shadow:0 0 0 2px {INK}"></i>{tr("semana en curso")}')
    st.markdown(f'<div class="ptl"><div class="seg">{seg}</div><div class="wk">{wk}</div><div class="leg">{len(W)} '
                f'{tr("semanas")}:{leg}</div></div>', unsafe_allow_html=True)

    cur_key = "base 1"
    if ci >= 0:
        cw_ = W[ci]
        cur_key = cw_["k"] if cw_["k"] in ("r", "t", "R") else (phase_key(cw_["ph"]) or "base 1")
    labs = [lab_ for lab_, _k in PHASE_ROWS]
    lab_cur = next((lab_ for lab_, k_ in PHASE_ROWS if k_ == cur_key), labs[0])
    sel = st.segmented_control("Fase", labs, default=lab_cur, key="plan_ses_fase", label_visibility="collapsed",
                               format_func=lambda l_: tr(l_) + (" ●" if l_ == lab_cur else "")) or lab_cur
    key_sel = dict(PHASE_ROWS)[sel]
    p_ = next((p for p in ph if phase_key(p["t"]) == key_sel and key_sel not in ("r", "R")), None)
    wks = [w for w in W if (w["k"] == key_sel if key_sel in ("r", "t", "R") else
                            (w["k"] not in ("r", "t", "R") and phase_key(w["ph"]) == key_sel))]
    wtxt = ", ".join(f"S{w['i'] + 1}" for w in wks)
    if p_ is not None:
        dt_ = f'{p_["a"]:%d/%m} – {p_["b"]:%d/%m} · {p_["to"] - p_["frm"] + 1} {tr("semanas")}'
        c_ = p_["c"]
        pts = p_["s"]
    else:
        dt_ = f'{tr("semana tipo")} · {wtxt or "—"}'
        c_ = {"r": GLACIER, "t": VIOLET, "R": RED}.get(key_sel, PREV)
        pts = {"r": ["Volumen y carga bajos para asimilar el bloque anterior", "Sin calidad: activación y cinta suave"],
               "t": ["Bajar el volumen manteniendo toques cortos de intensidad", "Llegar fresco a la carrera"],
               "R": ["Solo activación los días previos", "La carrera es la sesión de la semana"]}.get(key_sel, [])
    if p_ is not None and wtxt and key_sel != "t":
        dt_ += f' · {tr("semana tipo en")} {wtxt}'
    tg = "".join(f'<div style="--k:{k_}"><b>{tr(l_)}</b>{_html.escape(v_)}</div>' for l_, k_, v_ in (
        ("Fuerza", GREEN, tpl_summary(key_sel, "fuerza")), ("Calidad (carrera)", ORANGE, tpl_summary(key_sel, "calidad")),
        ("Cinta (inclinada)", GLACIER, tpl_summary(key_sel, "cinta")),
        ("Carrera por fuera · semana", GOLD, phase_global(S, key_sel))))
    st.markdown(f'<div class="pdet" style="--c:{c_}"><div><span class="dt">{_html.escape(dt_)}</span>'
                f'<h4>{_html.escape(p_["t"] if p_ is not None else tr(sel))}</h4><ul>'
                + "".join(f"<li>{_html.escape(tr(x))}</li>" for x in pts) + f'</ul></div><div class="tg">{tg}</div></div>',
                unsafe_allow_html=True)
    ids_ = list(dict.fromkeys([sid for _d, sid in WEEK_TPL[key_sel]] + ([QALT[key_sel]] if key_sel in QALT else [])))
    if ids_:
        with st.expander(f'{tr("Ejercicios de cada sesión")} · {len(ids_)}', expanded=False, key="plan_ses_x"):
            st.markdown('<div class="phases">' + "".join(sess_html(sid) for sid in ids_) + "</div>", unsafe_allow_html=True)
    red_ = [f"S{w['i'] + 1}" for w in W if w["k"] in ("r", "t")]
    st.markdown(f'<span class="note">{tr("Objetivos de la semana tipo de cada fase; las semanas de descarga o taper")} ({", ".join(red_)}) {tr("usan la suya sea cual sea su fase. La calidad del miércoles se hace fuera; si llueve, en cinta (cada sesión trae su variante). Las tiradas largas van en fin de semana; en el Pico ultra la fuerza va el martes para no hacerla en las 48 h antes de una larga. Zonas de FC de carrera: Z2 134–142, Z3 142–150, Z4 150–158.")} '
                + tr("Las sesiones de calidad se leen del calendario de intervals.icu." if S["P"].get("qual")
                     else "Sesiones de calidad del plan guardado en la app.") + '</span>', unsafe_allow_html=True)


def plan_tab():
    st.markdown(PLAN_CSS, unsafe_allow_html=True)
    S = summary_plan()
    st.subheader(S.get("title", "Plan de entrenamiento"))
    if not S["ok"]:
        st.info("No hay objetivos semanales en el calendario de intervals.icu.")
        return
    st.markdown(f'<div class="eyebrow">{_html.escape(S["week_txt"])}</div><div class="note">{_html.escape(S["src_txt"])}. '
                'Carga = training load de todas las actividades; D+ y km = Run y TrailRun (más Hike si lo sumas), sin la cinta.</div>',
                unsafe_allow_html=True)
    cards(plan_cards(S, ("races", "week", "compl")))
    if S["ci"] >= 0:
        cards(plan_cards(S, ("fzci",)))
    st.markdown(f'<div class="reading" style="--c:{S["text_c"]}">{S["text"]}</div>', unsafe_allow_html=True)
    met = st.segmented_control("Métrica plan", ["Carga", "D+", "Horas", "Fuerza (min)", "Cinta (km)"], default="Carga",
                               key="plan_met", label_visibility="collapsed") or "Carga"
    mk = {"Carga": "load", "D+": "dp", "Horas": "h", "Fuerza (min)": "fz_min", "Cinta (km)": "ci_km"}[met]
    st.subheader(f"{met} semanal · objetivo vs real")
    st.plotly_chart(plot_layout(plan_fig(S, mk), 300), width="stretch", theme=None)
    st.markdown(f'<span class="note">Barras anchas = objetivo (<span style="color:{GLACIER}">descarga</span>, '
                f'<span style="color:{RED}">carrera</span>); estrechas en <span style="color:{GOLD}">dorado</span> = real. '
                'Recuadro punteado = semana en curso.</span>', unsafe_allow_html=True)
    # Fuerza y cinta: esta semana y objetivos por fase con los ejercicios de cada sesión
    wi_ = S["ci"] if S["ci"] >= 0 else (0 if S["before"] else None)
    if wi_ is not None:
        st.subheader("Fuerza, calidad y cinta · " + ("esta semana" if S["ci"] >= 0 else "primera semana"))
        if week_note(S, wi_):
            st.markdown(f'<div class="note">{_html.escape(week_note(S, wi_))}</div>', unsafe_allow_html=True)
        todo_ = week_todo(S, wi_)
        st.markdown(_rows(todo_rows(S, wi_, todo_) + [global_row(S, wi_)]), unsafe_allow_html=True)
        plan_adjust_ui(S, wi_, todo_)
        st.markdown(f'<span class="note">Km orientativos: horas de carrera del objetivo × tu velocidad media en carrera por fuera '
                    f'de los últimos 120 días ({fnum(run_speed(), 1)} km/h). El D+ de la cinta va aparte y no cuenta para el D+ por fuera.</span>',
                    unsafe_allow_html=True)
    st.subheader("Fases")
    plan_phases_ui(S)
    st.subheader("Semana a semana")
    W, A, ci = S["W"], S["A"], S["ci"]
    rows = []
    for w, a in zip(W, A):
        fut = w["frm"] > today
        rows.append({"Semana": f"{w['i'] + 1:02d} · {w['frm']:%d/%m}", "Fase": w["ph"] + (" (+ carrera)" if w["k"] == "R" else ""),
                     "Carga|Obj.": w["load"], "Carga|Real": None if fut else a["load"],
                     "%": None if fut or w["k"] == "R" or not w["load"] else a["load"] / w["load"] * 100,
                     "Horas|Obj.": w["h"], "Horas|Real": None if fut else a["h"],
                     "D+|Obj.": w["dp"], "D+|Real": None if fut else a["dp"],
                     "Km|Obj.": w["km"], "Km|Real": None if fut else a["km"],
                     "D+ cinta|Obj.": w["ci_dp"] if w["ci_n"] else None, "D+ cinta|Real": None if fut else a["ci_dp"],
                     "Pend.|Obj.": cinta_pend_txt(w["ci_km"], w["ci_dp"]) if w["ci_n"] else "—",
                     "Pend.|Real": "" if fut else (cinta_pend_txt(a["ci_km"], a["ci_dp"]) if a["ci_n"] else "—"),
                     "Fuerza|Obj.": f"{w['fz_n']} × {fnum(w['fz_min'] / max(1, w['fz_n']))}′" if w["fz_n"] else "—",
                     "Fuerza|Real": "" if fut else f"{a['fz_n']} · {fnum(a['fz_min'])}′",
                     "Cinta|Obj.": f"{w['ci_n']} · {fnum(w['ci_km'], 1)} km" if w["ci_n"] else "—",
                     "Cinta|Real": "" if fut else (f"{a['ci_n']} · {fnum(a['ci_km'], 1)} km" if a["ci_n"] else "0")})
    rows.append({"Semana": "Total", "Fase": "", "Carga|Obj.": sum(w["load"] for w in W), "Carga|Real": sum(a["load"] for a in A),
                 "%": None, "Horas|Obj.": sum(w["h"] for w in W), "Horas|Real": sum(a["h"] for a in A),
                 "D+|Obj.": sum(w["dp"] for w in W), "D+|Real": sum(a["dp"] for a in A),
                 "Km|Obj.": sum(w["km"] for w in W), "Km|Real": sum(a["km"] for a in A),
                 "D+ cinta|Obj.": sum(w["ci_dp"] for w in W), "D+ cinta|Real": sum(a["ci_dp"] for a in A),
                 "Pend.|Obj.": cinta_pend_txt(sum(w["ci_km"] for w in W), sum(w["ci_dp"] for w in W)),
                 "Pend.|Real": cinta_pend_txt(sum(a["ci_km"] for a in A), sum(a["ci_dp"] for a in A)),
                 "Fuerza|Obj.": f"{sum(w['fz_n'] for w in W)} ses.", "Fuerza|Real": f"{sum(a['fz_n'] for a in A)} ses.",
                 "Cinta|Obj.": f"{fnum(sum(w['ci_km'] for w in W))} km", "Cinta|Real": f"{fnum(sum(a['ci_km'] for a in A), 1)} km"})
    TB = pd.DataFrame(rows)
    nf_ = lambda d: (lambda v: "" if v is None or pd.isna(v) else fnum(v, d))  # noqa: E731
    pc_ = lambda v: "" if v is None or pd.isna(v) else f'<span style="color:{GREEN if v >= 85 else ORANGE if v >= 60 else RED}">{fnum(v)} %</span>'  # noqa: E731
    cls = ["hl" if i == ci else "" for i in range(len(W))] + [""]
    html_table(TB, left={"Semana", "Fase"}, total_last=True, row_classes=cls,
               group_start={"Carga|Obj.", "Horas|Obj.", "D+|Obj.", "Km|Obj.", "D+ cinta|Obj.", "Pend.|Obj.", "Fuerza|Obj.", "Cinta|Obj."},
               groups=[("", 2, ""), ("Carga", 3, "g"), ("Horas", 2, "g"), ("D+ por fuera (m)", 2, "g"), ("Km por fuera", 2, "g"),
                       ("D+ cinta (m)", 2, "g"), ("Pendiente media cinta", 2, "g"), ("Fuerza (ses. × min)", 2, "g"),
                       ("Cinta (ses. · km)", 2, "g")], max_height=560,
               fmt={"Carga|Obj.": nf_(0), "Carga|Real": nf_(0), "%": pc_, "Horas|Obj.": nf_(1), "Horas|Real": nf_(1),
                    "D+|Obj.": nf_(0), "D+|Real": nf_(0), "Km|Obj.": lambda v: "" if v is None or pd.isna(v) else "≈ " + fnum(v),
                    "Km|Real": nf_(1), "D+ cinta|Obj.": nf_(0), "D+ cinta|Real": nf_(0)})
    st.markdown('<span class="note">En dorado, la semana en curso. Las semanas futuras solo muestran el objetivo. D+ y km por fuera = '
                'Run y TrailRun (más Hike si lo sumas), sin la cinta; los km objetivo son orientativos (horas de carrera × tu velocidad '
                'media). D+ cinta = VirtualRun, con la pendiente apuntada en la sección Cinta; va aparte y no cuenta para el D+ por fuera. '
                'Pendiente media cinta = D+ ÷ km de la cinta, en nivel de la máquina y % real: el objetivo es el nivel que se '
                'propone en la sección Cinta para las sesiones sin nivel. '
                'Fuerza real = WeightTraining y Workout.</span>', unsafe_allow_html=True)


def mobile_view():
    st.markdown(f"""<style>
.block-container {{ max-width: 560px !important; padding: 1.2rem 16px 3rem !important; }}
[data-testid="stExpander"] summary {{ min-height: 48px; display: flex; align-items: center; background: {SURFACE} !important; }}
[data-testid="stExpander"] summary:hover {{ background: {HOVER} !important; }}
[data-testid="stExpander"] summary, [data-testid="stExpander"] summary p {{ color: {INK} !important; }}
[data-testid="stExpander"] summary p {{ font-size: 15px; }}
[data-testid="stExpander"] details > div {{ padding-left: 10px; padding-right: 10px; }}
.cards {{ grid-template-columns: repeat(2, minmax(0, 1fr)) !important; }}
.cards > .card:last-child:nth-child(odd) {{ grid-column: 1 / -1; }}
.card {{ padding: 10px 12px; }}
.card .v {{ font-size: 28px; }}
.mlist {{ border-top: 1px solid {LINE}; margin: 4px 0 8px; }}
.mrow {{ padding: 7px 2px; border-bottom: 1px solid {GRID}; min-height: 44px; display: grid; gap: 1px; align-content: center; }}
.mrow .t {{ font-size: 14px; color: {INK}; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }}
.mrow .s {{ font-size: 12.5px; color: {MUTED}; font-variant-numeric: tabular-nums; }}
.mrow .bar {{ margin-top: 4px; }}
.stButton button {{ min-height: 44px; }}
</style>""", unsafe_allow_html=True)

    # Cabecera: fecha de los datos y actualizar
    try:
        from zoneinfo import ZoneInfo
        tz_ = ZoneInfo(st.context.timezone) if getattr(st.context, "timezone", None) else None
    except Exception:  # noqa: BLE001
        tz_ = None
    ts_ = DATA_TS.astimezone(tz_) if tz_ else DATA_TS.astimezone()
    st.markdown(f'<div class="eyebrow">Resumen · temporada {year}</div>', unsafe_allow_html=True)
    h1_, h2_ = st.columns([3, 2], vertical_alignment="center")
    with h1_:
        st.markdown(f'<div class="note">Datos de intervals.icu · actualizados el {ts_:%d/%m/%y} a las {ts_:%H:%M}</div>',
                    unsafe_allow_html=True)
    with h2_:
        if st.button("↻ Actualizar datos", key="mob_refresh", width="stretch"):
            st.cache_data.clear()
            st.rerun()

    # 1 · Temporada
    p_dp, lab_p = prev_to_date("out_dp")
    p_km, _ = prev_to_date("out_km")
    no_prev = not len(df_p)
    with st.expander(f"**Temporada {year}** · {fnum(T['dp'])} m D+", key="mob_x_temp"):
        cards([("D+", GOLD, fnum(T["dp"]), "m", [f"sin datos de {year - 1}" if no_prev else delta_html(T["dp"], p_dp, lab_p)]),
               ("Km", INK, fnum(T["km"], 1), "km", [f"sin datos de {year - 1}" if no_prev else delta_html(T["km"], p_km, lab_p)])])
        if len(df_y) or len(df_p):
            f_s = go.Figure()
            for d_, y_, col_, dash_, w_ in ((df_p, year - 1, PREV, "dash", 1.4), (df_y, year, GOLD, "solid", 2.4)):
                if len(d_):
                    end_ = today if y_ == now_y else dt.date(y_, 12, 31)
                    days_ = pd.date_range(f"{y_}-01-01", end_, freq="D")
                    c_ = d_.groupby(d_["ts"].dt.normalize())["out_dp"].sum().reindex(days_, fill_value=0).cumsum()
                    f_s.add_scatter(x=days_.dayofyear, y=c_.values, mode="lines", line=dict(color=col_, width=w_, dash=dash_))
            f_s.update_layout(height=110, margin=dict(l=0, r=0, t=4, b=0), showlegend=False,
                              paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(0,0,0,0)")
            f_s.update_xaxes(visible=False, range=[1, 366])
            f_s.update_yaxes(visible=False)
            st.plotly_chart(f_s, width="stretch", theme=None, config={"staticPlot": True})
            st.markdown(f'<div class="note">D+ acumulado: <span style="color:{GOLD}">━ {year}</span> · '
                        f'<span style="color:{PREV}">┅ {year - 1}</span></div>', unsafe_allow_html=True)

    # 2 · Semana en curso
    CW, GOAL, PROJ = summary_week()
    pct_dp = CW["dp"] / GOAL["dp"] * 100 if GOAL["dp"] > 0 else None
    with st.expander(f"**Semana en curso** · {fnum(CW['dp'])} m D+" + (f" · {fnum(pct_dp)} % del objetivo" if pct_dp is not None else ""),
                     expanded=True, key="mob_x_cw"):
        it_ = []
        for k, lab, col, unit, dec in [m for m in TRK if m[0] in ("dp", "km", "h")]:
            g_ = GOAL[k]
            pc = CW[k] / g_ * 100 if g_ > 0 else 0
            it_.append((lab, col, fnum(CW[k], dec), unit, [
                _bar(pc, col),
                f'objetivo {fnum(g_, dec)} · <b style="color:{INK}">{fnum(pc)} %</b>' if g_ > 0 else "sin objetivo",
                f"proyección domingo: <b style='color:{INK}'>{fnum(PROJ[k], dec)}</b>"]))
        cards(it_)
        st.markdown(f'<div class="note">Día {today.weekday() + 1} de 7. El objetivo es tu media de 8 semanas salvo que fijes otro '
                    'en Ajustes.</div>', unsafe_allow_html=True)

    # 3 · Última semana
    with st.expander(f"**Última semana** · {fnum(LW['dp'])} m D+ · {fnum(LW['km'], 1)} km", key="mob_x_lw"):
        cards([(lab, col, fnum(LW[k], d), u, [delta_html(LW[k], PW[k], "sem. anterior"), delta_html(LW[k], AVG[k], "media 8 sem")])
               for k, lab, col, u, d in [m for m in WKM if m[0] in ("dp", "km", "load", "kmE")]])
        st.markdown(f'<div class="note">{last_mon:%d/%m} – {last_mon + dt.timedelta(days=6):%d/%m}</div>', unsafe_allow_html=True)

    # 3b · Plan de entrenamiento (mismo orden que las pestañas: después de Última semana)
    SP = summary_plan()
    if not SP["ok"]:
        lab_p = "**Plan** · sin objetivos"
    elif SP["ci"] >= 0:
        cw_, ca_ = SP["W"][SP["ci"]], SP["A"][SP["ci"]]
        lab_p = (f"**{SP['title'].split(' · ')[0]}** · S{SP['ci'] + 1}/{len(SP['W'])} {cw_['ph']} · "
                 f"{fnum(ca_['load'])}/{fnum(cw_['load'])} carga")
    else:
        lab_p = f"**{SP['title'].split(' · ')[0]}** · " + (f"empieza el {SP['W'][0]['frm']:%d/%m}" if SP["before"] else "terminado")
    with st.expander(lab_p, key="mob_x_plan"):
        if not SP["ok"]:
            st.info("No hay objetivos semanales en el calendario de intervals.icu.")
        else:
            st.markdown(PLAN_CSS, unsafe_allow_html=True)
            st.markdown(f'<div class="note">{_html.escape(SP["week_txt"])} · {_html.escape(SP["src_txt"])}</div>', unsafe_allow_html=True)
            cards(plan_cards(SP, ("races",)))
            cards(plan_cards(SP, ("week", "compl")))
            if SP["ci"] >= 0:
                cards(plan_cards(SP, ("fzci",)))
            st.markdown(f'<div class="reading" style="--c:{SP["text_c"]}">{SP["text"]}</div>', unsafe_allow_html=True)
            st.markdown(plan_phase_html(SP, only_current=True), unsafe_allow_html=True)
            st.markdown('<div class="note">Carga semanal: objetivo (barra ancha) y real (dorado)</div>', unsafe_allow_html=True)
            st.plotly_chart(mini_layout(plan_fig(SP, "load", mini=True), 140), width="stretch", theme=None, config={"staticPlot": True})
            i0 = max(0, SP["ci"] + 1) if SP["ci"] >= 0 else (0 if SP["before"] else len(SP["W"]))
            nxt = SP["W"][i0:i0 + 4]
            if nxt:
                st.markdown('<div class="eyebrow" style="margin-top:6px">Próximas semanas</div>', unsafe_allow_html=True)
                st.markdown(_rows([(f'<b>S{w["i"] + 1}</b> · {w["frm"]:%d/%m} · {_html.escape(w["ph"])}'
                                    + ({"r": " · descarga", "t": " · taper", "R": ' · <span style="color:' + RED + '">carrera</span>'}.get(w["k"], "")
                                       if w["k"] and not re.search(r"descarga|taper", w["ph"], re.I) else ""),
                                    f'carga {fnum(w["load"])} · {fnum(w["h"], 1)} h · {fnum(w["dp"])} m D+'
                                    + (f' · fuerza {w["fz_n"]}×' if w["fz_n"] else "")
                                    + (f' · calidad {w["q_n"]}×' if w.get("q_n") else "")
                                    + (f' · cinta {fnum(w["ci_km"])} km' if w["ci_n"] else "")) for w in nxt]),
                            unsafe_allow_html=True)
            wi_m = SP["ci"] if SP["ci"] >= 0 else (0 if SP["before"] else None)
            if wi_m is not None:
                st.markdown('<div class="eyebrow" style="margin-top:6px">Fuerza, calidad y cinta · '
                            + ("esta semana" if SP["ci"] >= 0 else "primera semana") + "</div>", unsafe_allow_html=True)
                if week_note(SP, wi_m):
                    st.markdown(f'<div class="note">{_html.escape(week_note(SP, wi_m))}</div>', unsafe_allow_html=True)
                st.markdown(_rows(todo_rows(SP, wi_m) + [global_row(SP, wi_m)]), unsafe_allow_html=True)
                if st.toggle("Ver los ejercicios de esta semana", value=False, key="mob_plan_ej"):
                    ids_m = list(dict.fromkeys(sid for _d, sid in SP["W"][wi_m]["ses"]))
                    st.markdown('<div class="phases">' + "".join(sess_html(sid) for sid in ids_m) + "</div>", unsafe_allow_html=True)
            if st.toggle("Ver todas las fases", value=False, key="mob_plan_fases"):
                st.markdown(plan_phase_html(SP), unsafe_allow_html=True)

    # Histórico completo y material (Entrenamientos largos «Todo», Comparar y Material)
    shoes, gear_err = load_gear()
    hist = load_hist(shoes)

    # 5 · Hoja por Sets: métrica y mes elegibles, los 5 Sets del mes y los últimos meses
    ref = today if year == now_y else dt.date(year, 12, 31)
    SET_MET = {"D+": ("out_dp", 0, "m", GOLD), "Km": ("out_km", 1, "km", INK), "Km cinta": ("cinta_km", 1, "km", GLACIER),
               "min Gim": ("gim_min", 0, "min", GREEN)}

    def msum(col_, a_, b_):
        return float(all_df.loc[(all_df["date"] >= a_) & (all_df["date"] <= b_), col_].sum()) if len(all_df) else 0.0

    def month_end(d_):
        return (d_.replace(day=1) + dt.timedelta(days=32)).replace(day=1) - dt.timedelta(days=1)

    with st.expander(f"**Hoja por Sets** · {MES[ref.month - 1]}: {fnum(msum('out_dp', ref.replace(day=1), ref))} m D+", key="mob_x_sets"):
        met_ = st.pills("Métrica", list(SET_MET), default="D+", key="mob_set_met", label_visibility="collapsed") or "D+"
        col_, dec_, unit_, c_met = SET_MET[met_]
        if st.session_state.get("mob_set_mes", ref.month) not in range(1, ref.month + 1):   # p. ej. al cambiar de temporada
            st.session_state["mob_set_mes"] = ref.month
        if "mob_set_mes" not in st.session_state:
            st.session_state["mob_set_mes"] = ref.month
        mes_ = st.select_slider("Mes", options=list(range(1, ref.month + 1)), format_func=lambda m: MES[m - 1], key="mob_set_mes")
        m0 = dt.date(year, mes_, 1)
        m_end = min(month_end(m0), ref)                      # mes en curso: hasta hoy
        cur_m = m_end < month_end(m0)
        pm0 = (m0 - dt.timedelta(days=1)).replace(day=1)
        tot_m = msum(col_, m0, m_end)
        pm_cmp = msum(col_, pm0, min(month_end(pm0), pm0 + dt.timedelta(days=m_end.day - 1))) if cur_m else msum(col_, pm0, month_end(pm0))
        # Sets del mes
        sets_ = []
        for si in range(1, 6):
            a_ = m0 + dt.timedelta(days=7 * (si - 1))
            if a_.month != m0.month:
                continue
            b_ = min(m0 + dt.timedelta(days=7 * si - 1) if si < 5 else month_end(m0), month_end(m0))
            pa_ = pm0 + dt.timedelta(days=7 * (si - 1))
            pv_ = msum(col_, pa_, min(pm0 + dt.timedelta(days=7 * si - 1) if si < 5 else month_end(pm0), month_end(pm0))) \
                if pa_.month == pm0.month else 0.0
            state_ = "futuro" if a_ > ref else ("en curso" if a_ <= ref <= b_ else "")
            sets_.append((si, a_, b_, msum(col_, a_, min(b_, ref)) if state_ != "futuro" else None, pv_, state_))
        best_ = max((s for s in sets_ if s[3] is not None), key=lambda s: s[3], default=None)
        cards([
            (f"{met_} {MES[mes_ - 1].lower()}", c_met, fnum(tot_m, dec_), unit_,
             [delta_html(tot_m, pm_cmp, f"{MES[pm0.month - 1].lower()}{' a esta altura' if cur_m else ''}"),
              "mes en curso" if cur_m else "mes completo"]),
            ("Mejor Set", c_met, fnum(best_[3], dec_) if best_ else "—", unit_,
             [f"Set {best_[0]} · {best_[1].day}–{best_[2].day}" if best_ else "sin datos",
              f"media por Set: {fnum(tot_m / max(1, len([s for s in sets_ if s[3] is not None])), dec_)}"]),
        ])
        mx_ = max([s[3] for s in sets_ if s[3] is not None] + [s[4] for s in sets_] + [1.0])
        rows_s = []
        for si, a_, b_, v_, pv_, state_ in sets_:
            tit = f'<b>Set {si}</b> · {a_.day}–{b_.day} {MES[mes_ - 1].lower()}' + (f' · <span style="color:{GOLD}">en curso</span>' if state_ == "en curso" else "")
            if v_ is None:
                sub = "pendiente"
            else:
                sub = (f'<b style="color:{INK}">{fnum(v_, dec_)} {unit_}</b> · {MES[pm0.month - 1].lower()}: {fnum(pv_, dec_)} {unit_}'
                       + _bar(v_ / mx_ * 100, c_met))
            rows_s.append((tit, sub))
        st.markdown(_rows(rows_s), unsafe_allow_html=True)
        # Últimos 6 meses (hasta el mes elegido), con el incremento frente al mes anterior como en la Hoja por Sets
        st.markdown(f'<div class="eyebrow" style="margin-top:6px">Últimos meses · {met_}</div>', unsafe_allow_html=True)
        rows_m, d_ = [], m0
        months_ = []
        for _ in range(6):
            months_.append(d_)
            d_ = (d_ - dt.timedelta(days=1)).replace(day=1)
        mvals = {mm_: msum(col_, mm_, min(month_end(mm_), ref)) for mm_ in months_}
        mmax = max([1.0] + list(mvals.values()))
        for mm_ in months_:
            v_ = msum(col_, mm_, min(month_end(mm_), ref))
            p0_ = (mm_ - dt.timedelta(days=1)).replace(day=1)
            pv_ = msum(col_, p0_, month_end(p0_))
            inc_ = (v_ - pv_) / v_ * 100 if v_ > 0 else None
            inc_txt = ("" if inc_ is None else
                       f' · <span class="{"up" if inc_ > 0 else "down"}">{"▲" if inc_ > 0 else "▼"} {fnum(abs(inc_))} %</span> vs mes anterior')
            rows_m.append((f'{MES[mm_.month - 1]} {str(mm_.year)[2:]}' + (" · en curso" if month_end(mm_) > ref else ""),
                           f'<b style="color:{INK}">{fnum(v_, dec_)} {unit_}</b>{inc_txt}' + _bar(v_ / mmax * 100, c_met)))
        st.markdown(_rows(rows_m), unsafe_allow_html=True)
        st.markdown('<div class="note">Set = bloque de 7 días del mes (1–7, 8–14, 15–21, 22–28, 29–31). Incremento = '
                    '(mes − mes anterior) / mes, como en la Hoja por Sets.</div>', unsafe_allow_html=True)

    # 6 · Entrenamientos largos: filtros, lista y detalle del elegido
    n500 = int((df_y["sport"].isin(OUT) & (df_y["dp"] >= 500)).sum()) if len(df_y) else 0
    with st.expander(f"**Entrenamientos largos** · {n500} en {year}", key="mob_x_long"):
        LP = ["90 días", "6 meses", f"Temporada {year}", "Todo"]
        per_ = st.segmented_control("Periodo", LP, default=f"Temporada {year}", key="mob_lg_per",
                                    label_visibility="collapsed") or f"Temporada {year}"
        fl1, fl2 = st.columns(2)
        with fl1:
            dpmin = st.select_slider("D+ mínimo", options=[0, 250, 500, 750, 1000, 1500, 2000], value=500,
                                     format_func=lambda v: f"{fnum(v)} m", key="mob_lg_dp")
        with fl2:
            tip_l = st.pills("Tipo", ["Trail", "Asfalto"], selection_mode="multi", default=["Trail", "Asfalto"], key="mob_lg_tipo") or []
        ord_ = st.segmented_control("Ordenar por", ["Fecha", "D+", "Distancia", "Tiempo"], default="Fecha", key="mob_lg_ord") or "Fecha"
        base_ = hist if per_ == "Todo" else all_df
        if per_ == "90 días":
            f_from, f_to = today - dt.timedelta(days=89), today
        elif per_ == "6 meses":
            f_from, f_to = today - dt.timedelta(days=182), today
        elif per_ == "Todo":
            f_from, f_to = (hist["date"].min() if len(hist) else today), today
        else:
            f_from, f_to = dt.date(year, 1, 1), min(dt.date(year, 12, 31), today)
        sp_ = [{"Trail": "TrailRun", "Asfalto": "Run"}[t_] for t_ in tip_l]
        lg_ = base_[base_["sport"].isin(sp_) & (base_["dp"] >= dpmin) & (base_["date"] >= f_from) & (base_["date"] <= f_to)] \
            if len(base_) else base_
        lg_ = lg_.sort_values({"Fecha": "ts", "D+": "dp", "Distancia": "km", "Tiempo": "elapsed"}[ord_], ascending=False) if len(lg_) else lg_
        if not len(lg_):
            st.info("Ningún entrenamiento cumple los filtros.")
        else:
            st.markdown(f'<div class="note">{len(lg_)} entrenamientos · {fnum(lg_["km"].sum(), 1)} km · {fnum(lg_["dp"].sum())} m D+ · '
                        f'{_hm(lg_["elapsed"].sum())} h · {f_from:%d/%m/%y} – {f_to:%d/%m/%y}</div>', unsafe_allow_html=True)
            all_l = st.toggle(f"Mostrar los {len(lg_)}", value=False, key="mob_lg_all") if len(lg_) > 10 else True
            st.markdown(_rows([(f'{r_["ts"]:%d/%m/%y} · {_html.escape(str(r_["name"]))}',
                                f'{fnum(r_["km"], 1)} km · {fnum(r_["dp"])} m D+ · {_hm(r_["elapsed"])} h'
                                + (" · trail" if r_["sport"] == "TrailRun" else " · asfalto"))
                               for _, r_ in (lg_ if all_l else lg_.head(10)).iterrows()]), unsafe_allow_html=True)
            ids_l = list(lg_["id"])
            if st.session_state.get("mob_lg_sel") not in ids_l:
                st.session_state["mob_lg_sel"] = ids_l[0]
            info_l = lg_.set_index("id")
            sel_l = st.selectbox("Ver detalle", ids_l, key="mob_lg_sel",
                                 format_func=lambda i: f"{info_l.loc[i, 'ts']:%d/%m/%y} · {str(info_l.loc[i, 'name'])[:30]} · "
                                                       f"{fnum(info_l.loc[i, 'km'], 1)} km · {fnum(info_l.loc[i, 'dp'])} m")
            r_ = info_l.loc[sel_l]
            pace_ = f"{int(r_['pace'] // 60)}:{int(round(r_['pace'] % 60)) % 60:02d}" if pd.notna(r_["pace"]) and r_["pace"] > 0 else "—"
            cards([
                ("Distancia", INK, fnum(r_["km"], 1), "km", [f"ritmo {pace_} min/km"]),
                ("Desnivel", GOLD, fnum(r_["dp"]), "m", [f"D− {fnum(r_['dm'])} m · {fnum(r_['dp'] / r_['km'] if r_['km'] else 0)} m/km"]),
                ("Tiempo total", TEAL, _hm(r_["elapsed"]), "h", [f"en movimiento {_hm(r_['secs'])} h"]),
                ("Carga", VIOLET, fnum(r_["load"]), "", [f"FC media {fnum(r_['hr_avg'])} · máx. {fnum(r_['hr_max'])} ppm"
                                                          if pd.notna(r_["hr_avg"]) else "sin FC"]),
            ])

            def _to_cmp(aid=sel_l, sp=r_["sport"]):
                st.session_state["mob_cmp_a"] = aid
                t_ = {"TrailRun": "Trail", "Run": "Carrera"}.get(sp, "Trail")
                st.session_state["mob_cmp_tipo"] = sorted(set(st.session_state.get("mob_cmp_tipo") or ["Trail"]) | {t_})
                st.session_state["mob_x_cmp"] = True

            st.button("Comparar este entrenamiento ↓", key="mob_lg_cmp", on_click=_to_cmp, width="stretch")

    # 7 · Comparar: carrera actual y carrera a comparar elegibles (por defecto, la última de trail y su ruta más parecida)
    CMPS = {"Trail": ["TrailRun"], "Carrera": ["Run"], "Caminata": ["Hike", "Walk"]}
    all_c = hist[hist["sport"].isin(sum(CMPS.values(), []))].sort_values("ts", ascending=False) if len(hist) else hist
    tip_c = [t_ for t_ in (st.session_state.get("mob_cmp_tipo") or ["Trail"]) if t_ in CMPS] or ["Trail"]
    pool_c = all_c[all_c["sport"].isin(sum((CMPS[t_] for t_ in tip_c), []))] if len(all_c) else all_c
    info_c = all_c.set_index("id") if len(all_c) else None
    lab_m = lambda i: (f"{info_c.loc[i, 'ts']:%d/%m/%y} · {str(info_c.loc[i, 'name'])[:26]} · {fnum(info_c.loc[i, 'km'], 1)} km · "  # noqa: E731
                       f"{_hm(info_c.loc[i, 'secs'])} · {fnum(info_c.loc[i, 'dp'])} m")
    ra = rb = sim_ = None
    opts_a = list(pool_c["id"]) if len(pool_c) else []
    sim_ids, opts_b = set(), []
    if opts_a:
        if st.session_state.get("mob_cmp_a") not in opts_a:
            st.session_state["mob_cmp_a"] = opts_a[0]
        ra = info_c.loc[st.session_state["mob_cmp_a"]]
        a_id = st.session_state["mob_cmp_a"]
        sim_c = all_c[(all_c["id"] != a_id) & all_c["km"].between(ra["km"] * .95, ra["km"] * 1.05)
                      & all_c["dp"].between(ra["dp"] * .93, ra["dp"] * 1.07)]
        if len(sim_c):
            sim_c = sim_c.assign(_k=(sim_c["km"] / ra["km"] - 1).abs() + (sim_c["dp"] / max(1, ra["dp"]) - 1).abs()).sort_values("_k")
        sim_ids = set(sim_c["id"]) if len(sim_c) else set()
        opts_b = list(sim_c["id"]) if len(sim_c) else []
        opts_b += [i for i in pool_c["id"] if i != a_id and i not in sim_ids]
        if opts_b and (st.session_state.get("mob_cmp_b") not in opts_b or st.session_state.get("mob_cmp_b_for") != a_id):
            st.session_state["mob_cmp_b"] = opts_b[0]
        st.session_state["mob_cmp_b_for"] = a_id
        if opts_b:
            rb = info_c.loc[st.session_state["mob_cmp_b"]]
            with st.spinner("Comprobando el recorrido con el GPS…"):
                da_, _ = act_df(a_id, ra["km"], ra["dp"], ra["secs"])
                db_, _ = act_df(st.session_state["mob_cmp_b"], rb["km"], rb["dp"], rb["secs"])
            sim_ = route_similarity(da_, db_) if len(da_) and len(db_) else None
    if ra is None:
        cmp_lab = "**Comparar** · sin actividades"
    elif rb is None:
        cmp_lab = f"**Comparar** · {ra['ts']:%d/%m}: sin otra actividad"
    else:
        dmv = float(rb["secs"] - ra["secs"])          # > 0: la carrera actual fue más rápida
        cmp_lab = (f"**Comparar** · {ra['ts']:%d/%m} vs {rb['ts']:%d/%m/%y}: "
                   + (f":{'green' if dmv > 0 else 'red'}[{_mmss(dmv)} {'más rápida' if dmv > 0 else 'más lenta'}]" if abs(dmv) >= 30
                      else "mismo tiempo"))

    def _swap_m():
        a_, b_ = st.session_state.get("mob_cmp_a"), st.session_state.get("mob_cmp_b")
        if a_ and b_:
            st.session_state["mob_cmp_a"], st.session_state["mob_cmp_b"], st.session_state["mob_cmp_b_for"] = b_, a_, b_
            t_ = {"TrailRun": "Trail", "Run": "Carrera", "Hike": "Caminata", "Walk": "Caminata"}.get(info_c.loc[b_, "sport"], "Trail")
            st.session_state["mob_cmp_tipo"] = sorted(set(st.session_state.get("mob_cmp_tipo") or ["Trail"]) | {t_})

    with st.expander(cmp_lab, key="mob_x_cmp"):
        if "mob_cmp_tipo" not in st.session_state:
            st.session_state["mob_cmp_tipo"] = ["Trail"]
        st.pills("Tipo", list(CMPS), selection_mode="multi", key="mob_cmp_tipo", label_visibility="collapsed")
        if ra is None:
            st.info("No hay actividades de ese tipo.")
        else:
            st.selectbox("Carrera actual", opts_a, key="mob_cmp_a", format_func=lab_m)
            if not opts_b:
                st.info("No hay otra actividad con la que comparar.")
            else:
                st.selectbox("Carrera a comparar", opts_b, key="mob_cmp_b", format_func=lambda i: ("≈ " if i in sim_ids else "") + lab_m(i))
                st.button("⇅ Intercambiar", key="mob_cmp_swap", on_click=_swap_m, width="stretch")
                st.markdown(f'<div class="note">≈ = ruta parecida (distancia ±5 %, D+ ±7 %), las primeras de la lista. '
                            f'{len(sim_ids)} parecida{"s" if len(sim_ids) != 1 else ""} a la carrera actual.</div>', unsafe_allow_html=True)
                if sim_ and sim_["label"] == "distinta":
                    st.markdown(f'<div class="reading" style="--c:{ORANGE}">Según el GPS, el recorrido es <b>distinto</b>: '
                                'la diferencia de tiempos es solo orientativa.</div>', unsafe_allow_html=True)
                cards([
                    (f"Actual · {ra['ts']:%d/%m/%y}", GOLD, _hm(ra["secs"]), "h", [f"{fnum(ra['km'], 1)} km · {fnum(ra['dp'])} m D+"]),
                    (f"Comparada · {rb['ts']:%d/%m/%y}", GLACIER, _hm(rb["secs"]), "h", [f"{fnum(rb['km'], 1)} km · {fnum(rb['dp'])} m D+"]),
                ])
                txt_ = (f"En movimiento, la carrera actual fue <b>{_mmss(dmv)} min {'más rápida' if dmv > 0 else 'más lenta'}</b> "
                        f"que la del {rb['ts']:%d/%m/%y}" if abs(dmv) >= 30 else
                        f"En movimiento, las dos tardaron prácticamente lo mismo")
                txt_ += (f" (recorrido según GPS: {sim_['label']})." if sim_ else " (sin GPS: comparadas por distancia y D+).")
                st.markdown(f'<div class="reading" style="--c:{GREEN if dmv > 0 else RED if dmv < 0 else MUTED}">{txt_}</div>',
                            unsafe_allow_html=True)

                def drow(lab_, va, vb, fmt_, better_low=None):
                    if pd.isna(va) or pd.isna(vb):
                        return (f"<b>{lab_}</b>", f"actual {fmt_(va)} · comparada {fmt_(vb)}")
                    x_ = va - vb                                          # actual − comparada
                    good = None if better_low is None else (x_ < 0 if better_low else x_ > 0)
                    c_ = MUTED if good is None or abs(x_) < 1e-9 else (GREEN if good else RED)
                    return (f"<b>{lab_}</b>", f'actual <b style="color:{INK}">{fmt_(va)}</b> · comparada {fmt_(vb)} · '
                                              f'<span style="color:{c_}">{"+" if x_ > 0 else "−" if x_ < 0 else "±"}{fmt_(abs(x_))}</span>')

                pace = lambda r__: r__["secs"] / r__["km"] if r__["km"] else np.nan  # noqa: E731
                f_t = lambda v: "—" if pd.isna(v) else (f"{int(v // 3600)}:{int(v % 3600 // 60):02d}:{int(v % 60):02d}" if v >= 3600  # noqa: E731
                                                       else f"{int(v // 60)}:{int(round(v % 60)) % 60:02d}")
                st.markdown(_rows([
                    drow("Distancia", ra["km"], rb["km"], lambda v: f"{fnum(v, 2)} km"),
                    drow("D+", ra["dp"], rb["dp"], lambda v: f"{fnum(v)} m"),
                    drow("Tiempo en movimiento", ra["secs"], rb["secs"], f_t, better_low=True),
                    drow("Tiempo total", ra["elapsed"], rb["elapsed"], f_t, better_low=True),
                    drow("Ritmo (min/km)", pace(ra), pace(rb), f_t, better_low=True),
                    drow("FC media", ra["hr_avg"], rb["hr_avg"], lambda v: "—" if pd.isna(v) else f"{fnum(v)} ppm", better_low=True),
                    drow("Carga", ra["load"], rb["load"], lambda v: fnum(v)),
                ]), unsafe_allow_html=True)
                st.markdown('<div class="note">Diferencia = actual − comparada; en verde, la carrera actual fue mejor. '
                            'El análisis por tramos está en la sección Comparar de la vista completa.</div>', unsafe_allow_html=True)

    # 7b · Esfuerzo y fatiga (mismo orden que las pestañas: después de Comparar)
    SF = summary_fatigue()
    if SF:
        cur_ = SF["cur"]
        tsb_txt = ("+" if cur_["tsb"] > 0 else "") + fnum(cur_["tsb"])
