SP_KEYS = ("kcal", "ch", "glu", "fru", "p", "f", "na", "caf", "bcaa", "ml")
SPORT_ALL: dict = dict(SPORT)


def sport_totals(items: list) -> dict:
    """Totales de lo tomado durante una actividad: [[producto, unidades], …]."""
    out = {k_: 0.0 for k_ in SP_KEYS}
    for name, q in items or []:
        v = SPORT_ALL.get(name) or SPORT.get(name)
        if v and q:
            for i_, k_ in enumerate(SP_KEYS):
                out[k_] += float(v[2 + i_]) * float(q)
    return out

_FOOD_TAG = re.compile(r"⟦llibreta-comida⟧(.*?)⟦/llibreta-comida⟧", re.S)

# Lista propia de alimentos y bebidas: los de la app más los añadidos, menos los quitados. Se guarda en intervals.icu como
# una nota del calendario en una fecha fija y lejana (no aparece en ningún periodo que use la app), con un JSON en la
# descripción: {"add": {"f": {nombre: [kcal, hidratos, proteína, grasa, ración]}, "b": {...}}, "hide": {"f": [...], "b": [...]}}.
# Un alimento de la app con valores cambiados se guarda en «add» con el mismo nombre (sustituye a los de la app).
FOODCAT_DATE = "2000-01-01"
FOODCAT_NAME = "Llibreta D+ · alimentos y bebidas"
FOOD_ALL: dict = dict(FOODS)      # catálogo en uso (se rellena en food_cat())
FOOD_UNIT: dict = {}
DRINK_UNIT: dict = {}
DRINK_ALL: dict = dict(DRINKS)


def food_cat_raw() -> tuple:
    return app_note_get(FOODCAT_NAME, "demo_foodcat")


def food_cat() -> dict:
    """Catálogo en uso: todos (para calcular, incluidos los quitados) y activos (para elegir)."""
    global FOOD_ALL, DRINK_ALL
    _id, d_ = food_cat_raw()
    add, hide, dele = d_.get("add", {}), d_.get("hide", {}), d_.get("del", {}) or {}
    units = d_.get("unit", {}) or {}
    out = {"unit": units}
    for t_, base in (("f", FOODS), ("b", DRINKS)):
        all_ = dict(base)
        for n_, v in (add.get(t_) or {}).items():
            try:
                all_[str(n_)] = tuple(float(x) for x in v[:5])
            except Exception:  # noqa: BLE001
                pass
        hid = set(hide.get(t_) or [])
        dl = {n_ for n_ in (dele.get(t_) or []) if n_ in base}      # de la app eliminados (los propios se borran sin más)
        out[t_] = all_                                               # todos, para calcular días ya registrados
        out[t_ + "_act"] = {n_: v for n_, v in all_.items() if n_ not in hid and n_ not in dl}
        out[t_ + "_hide"] = hid - dl
        out[t_ + "_del"] = dl
        U_ = FOOD_UNITS if t_ == "f" else DRINK_UNITS
        out[t_ + "_unit"] = {n_: str((units.get(t_) or {}).get(n_) or U_.get(n_, UNIT_DEF)) for n_ in all_}
    all_ = dict(SPORT)
    for n_, v in (add.get("s") or {}).items():
        try:
            all_[str(n_)] = [str(v[0]), str(v[1])] + [float(x) for x in v[2:12]]
        except Exception:  # noqa: BLE001
            pass
    hid = set(hide.get("s") or [])
    dl = {n_ for n_ in (dele.get("s") or []) if n_ in SPORT}
    out["s"], out["s_act"], out["s_hide"] = all_, {n_: v for n_, v in all_.items() if n_ not in hid and n_ not in dl}, hid - dl
    out["s_del"] = dl
    out["add"] = add
    ch_ = d_.get("cheat")
    out["cheat_raw"] = ch_ if isinstance(ch_, dict) else None
    out["cheat"] = {t_: (set(ch_.get(t_) or []) if isinstance(ch_, dict) else set(CHEAT_DEF[t_])) for t_ in ("f", "b")}
    out["comb"] = {str(k_): v for k_, v in (d_.get("comb") or {}).items() if isinstance(v, dict)}
    global SPORT_ALL, FOOD_UNIT, DRINK_UNIT
    FOOD_UNIT, DRINK_UNIT = out["f_unit"], out["b_unit"]
    FOOD_ALL, DRINK_ALL, SPORT_ALL = out["f"], out["b"], out["s"]
    return out


_KEEP = object()


def food_cat_save(add=_KEEP, hide=_KEEP, dele=_KEEP, unit=_KEEP, cheat=_KEEP, comb=_KEEP):
    """Guarda la lista propia (solo al pulsar el botón). «del»: elementos de la app eliminados de la lista (no salen ni en la
    tabla ni al registrar; se recuperan debajo de la tabla o con «Volver a la lista de la app»). «cheat»: alimentos y bebidas
    fuera de la dieta habitual; «comb»: combinaciones con nombre (ensalada, bol de fruta…). Lo que no se pasa se conserva."""
    _id, cur = food_cat_raw()
    cur = dict(cur or {})
    new = {"v": 1}
    for k_, v_ in (("add", add), ("hide", hide), ("del", dele), ("unit", unit), ("cheat", cheat), ("comb", comb)):
        val = cur.get(k_) if v_ is _KEEP else v_
        if val is not None:
            new[k_] = val
    new.setdefault("add", {})
    new.setdefault("hide", {})
    app_note_save(FOODCAT_NAME, "demo_foodcat", new)


def cat_restore(dels: set, disp, key: str) -> set:
    """Elementos de la app eliminados que se quieren recuperar (se aplica al guardar)."""
    if not dels:
        return set()
    names = sorted(dels, key=lambda n_: _fold(disp(n_)))
    sel = st.multiselect(f'↩ {tr("Recuperar eliminados")} ({fnum(len(dels))})', names, key=f"{key}_restore", format_func=disp,
                         placeholder=tr("Elige los que quieras volver a tener"))
    return set(sel)


def cat_del_note(names: list):
    if names:
        st.markdown(f'<span class="note" style="color:{RED}">🗑 {tr("Se eliminarán al guardar")}: '
                    + ", ".join(_html.escape(x) for x in names) + "</span>", unsafe_allow_html=True)


DEL_COL = "Eliminar"


def food_day_get(d_: dt.date) -> tuple[dict, str]:
    """Comidas guardadas de un día y el resto del comentario del wellness."""
    if demo:
        return st.session_state.setdefault("demo_food", {}).get(d_.isoformat(), {}), ""
    try:
        rows = fetch_wellness(athlete, key, d_.isoformat(), d_.isoformat())
    except Exception:  # noqa: BLE001
        return {}, ""
    com = str((rows[0].get("comments") if rows else "") or "")
    m_ = _FOOD_TAG.search(com)
    data = {}
    if m_:
        try:
            j_ = json.loads(m_.group(1))
            data = j_.get("m", {})
            for t_, D_ in (("f", FOOD_ALL), ("b", DRINK_ALL), ("s", SPORT_ALL)):  # ya no están en la lista: valores del día
                for n_, v in (j_.get("x", {}).get(t_) or {}).items():
                    D_.setdefault(n_, list(v) if t_ == "s" else tuple(v))
        except Exception:  # noqa: BLE001
            data = {}
    return data, _FOOD_TAG.sub("", com).strip()


def food_totals(meals: dict) -> dict:
    """kcal, hidratos, proteína, grasa y líquido de un día (y por comida)."""
    out = {"kcal": 0.0, "ch": 0.0, "p": 0.0, "f": 0.0, "ml": 0.0, "by": {}}
    for mk, _lab in MEALS:
        t_ = {"kcal": 0.0, "ch": 0.0, "p": 0.0, "f": 0.0, "ml": 0.0}
        for name, q in meals.get(mk, {}).get("f", []):
            v = FOOD_ALL.get(name) or FOODS.get(name)
            if v and q:
                for i_, kk in enumerate(("kcal", "ch", "p", "f")):
                    t_[kk] += v[i_] * float(q) / 100
        for name, q in meals.get(mk, {}).get("b", []):
            v = DRINK_ALL.get(name) or DRINKS.get(name)
            if v and q:
                for i_, kk in enumerate(("kcal", "ch", "p", "f")):
                    t_[kk] += v[i_] * float(q) / 100
                t_["ml"] += float(q)
        out["by"][mk] = t_
        for kk in ("kcal", "ch", "p", "f", "ml"):
            out[kk] += t_[kk]
    t_ = {"kcal": 0.0, "ch": 0.0, "p": 0.0, "f": 0.0, "ml": 0.0}
    for items in (meals.get("a") or {}).values():
        st_ = sport_totals(items)
        for kk in t_:
            t_[kk] += st_[kk]
    out["by"]["a"] = t_
    for kk in t_:
        out[kk] += t_[kk]
    return out


def food_day_save(d_: dt.date, meals: dict, rest: str):
    tot = food_totals(meals)
    # Con el día se guardan los valores de los alimentos propios o cambiados: el día se lee igual aunque luego se quiten
    x_ = {"f": {}, "b": {}, "s": {}}
    for items in (meals.get("a") or {}).values():
        for n_, _q in items:
            if n_ in SPORT_ALL and list(SPORT_ALL[n_]) != list(SPORT.get(n_, [])):
                x_["s"][n_] = list(SPORT_ALL[n_])
    for mk in [m_ for m_, _l in MEALS if m_ in meals]:
        for t_, D_, B_ in (("f", FOOD_ALL, FOODS), ("b", DRINK_ALL, DRINKS)):
            for n_, _q in meals[mk].get(t_, []):
                if n_ in D_ and tuple(D_[n_]) != tuple(B_.get(n_, ())):
                    x_[t_][n_] = list(D_[n_])
    blob = json.dumps({"v": 1, "m": meals, "x": {t_: v for t_, v in x_.items() if v}}, ensure_ascii=False, separators=(",", ":"))
    com = ((rest + "\n") if rest else "") + f"⟦llibreta-comida⟧{blob}⟦/llibreta-comida⟧"
    if demo:
        st.session_state.setdefault("demo_food", {})[d_.isoformat()] = meals
        return
    icu_write("PUT", f"/athlete/{athlete}/wellness/{d_.isoformat()}",
              {"id": d_.isoformat(), "kcalConsumed": round(tot["kcal"]), "carbohydrates": round(tot["ch"]),
               "protein": round(tot["p"]), "fatTotal": round(tot["f"]), "comments": com})
    for aid, items in (meals.get("a") or {}).items():   # hidratos tomados durante la actividad, en su campo de intervals
        if str(aid).startswith("i") or str(aid).isdigit():
            icu_write("PUT", f"/activity/{aid}", {"carbs_ingested": int(round(sport_totals(items)["ch"]))})
    fetch_wellness.clear()
    if meals.get("a"):
        fetch_year.clear()


def food_week_intake(frm: dt.date, to: dt.date) -> dict:
    """Ingesta registrada por día (kcal, hidratos, proteína, grasa) entre dos fechas."""
    out = {}
    if demo:
        for ds, meals in st.session_state.get("demo_food", {}).items():
            d_ = dt.date.fromisoformat(ds)
            if frm <= d_ <= to:
                t_ = food_totals(meals)
                out[d_] = dict(kcal=t_["kcal"], ch=t_["ch"], p=t_["p"], f=t_["f"])
        return out
    try:
        rows = fetch_wellness(athlete, key, frm.isoformat(), to.isoformat())
    except Exception:  # noqa: BLE001
        return out
    for r_ in rows:
        if r_.get("kcalConsumed"):
            out[dt.date.fromisoformat(str(r_["id"])[:10])] = dict(
                kcal=float(r_.get("kcalConsumed") or 0), ch=float(r_.get("carbohydrates") or 0),
                p=float(r_.get("protein") or 0), f=float(r_.get("fatTotal") or 0))
    return out


def food_day_target(d_: dt.date, P: dict, base: float, k: float, W: list) -> tuple[float, float, str]:
    """Gasto del día (basal y día + ejercicio) y horas de entreno: real si ya pasó, el mayor de real y plan si es hoy,
    el del plan si es futuro."""
    dd_ = all_df[all_df["date"] == d_] if len(all_df) else all_df
    real = nut_ex_real(dd_, P, k) if len(dd_) and d_ <= today else 0.0
    h_real = float(dd_["hours"].sum()) if len(dd_) else 0.0
    plan, h_plan = 0.0, 0.0
    w_ = next((w for w in W if w["frm"] <= d_ <= w["to"]), None)
    if w_ is not None:
        pd_ = nut_week_plan(w_, P, k)["days"][(d_ - w_["frm"]).days]
        plan, h_plan = pd_["kcal"], pd_["min"] / 60
    if d_ < today:
        return base + real, h_real, "real"
    if d_ == today:
        return base + max(real, plan), max(h_real, h_plan), "real" if real >= plan else "plan"
    return base + plan, h_plan, "plan"


def sport_guide(minutes: float) -> tuple[float, float]:
    """Hidratos por hora recomendados según la duración (misma guía que el plan)."""
    if minutes < 60:
        return 0, 30
    if minutes < 90:
        return 0, 30
    if minutes < 150:
        return 30, 60
    return 60, 90


def _band_col(v, lo, hi):
    return GREEN if lo <= v <= hi else (ORANGE if v < lo else GLACIER)


def sport_log(d_: dt.date, saved_a: dict, C_: dict, P: dict, compact: bool = False) -> dict:
    """Lo tomado durante cada actividad del día: geles, sales, cafeína, BCAA, sólidos y líquidos, con su análisis por hora."""
    da = all_df[all_df["date"] == d_].sort_values("ts") if len(all_df) else all_df
    if not len(da):
        st.info(tr("No hay actividades este día."))
        return {}
    used = {n_ for v in saved_a.values() for n_, _q in v}
    opts = [tr(n_) for n_ in SPORT_ALL if n_ in C_["s_act"] or n_ in used]
    back = {tr(n_): n_ for n_ in SPORT_ALL}
    out = {}
    st.markdown('<span class="note">Cantidad en unidades (gel, cápsula, bidón…); se admiten medias (0,5). Para añadir tus geles, '
                'sales o bebidas con sus valores, ve a <b>Plan 2027 › Alimentos y bebidas › Deporte</b>.</span>', unsafe_allow_html=True)
    for _, a in da.iterrows():
        aid = str(a["id"])
        h_ = float(a["hours"] or 0)
        mins = h_ * 60
        hh, mm = divmod(int(round(mins)), 60)
        st.markdown(f'<div style="margin:14px 0 4px;font-weight:600;color:{INK}">{a["ts"]:%H:%M} · {a["name"] or a["sport"]} · '
                    f'{fnum(a["km"], 1)} km · {fnum(a["dp"])} m D+ · {hh}:{mm:02d} h'
                    + (f' <span style="color:{GOLD}">✎ {tr("corregida")}</span>' if a.get("corr") else "") + '</div>',
                    unsafe_allow_html=True)
        cur = saved_a.get(aid, [])
        df0 = pd.DataFrame([{"Producto": tr(n_), "Unidades": q} for n_, q in cur] or
                           pd.DataFrame({"Producto": [], "Unidades": []})).astype({"Producto": object, "Unidades": float})
        ed = st.data_editor(df0, key=f"nlog_a_{aid}_{d_}", num_rows="dynamic", hide_index=True, width="stretch",
                            column_config={"Producto": st.column_config.SelectboxColumn(tr("Producto"), options=opts, width="large"),
                                           "Unidades": st.column_config.NumberColumn(tr("Unidades"), min_value=0, max_value=100,
                                                                                     step=0.5, format="%.1f",
                                                                                     help=tr("Vacío = 1"))})
        items = []
        for _, r_ in ed.iterrows():
            n_ = back.get(r_["Producto"]) if isinstance(r_["Producto"], str) else None
            if n_:
                q = r_["Unidades"]
                items.append([n_, float(q) if pd.notna(q) and q else 1.0])
        if not items:
            continue
        out[aid] = items
        T_ = sport_totals(items)
        ph = (lambda v: v / h_) if h_ > 0 else (lambda v: 0.0)  # noqa: E731
        lo, hi = sport_guide(mins)
        chh, glh, frh = ph(T_["ch"]), ph(T_["glu"]), ph(T_["fru"])
        ratio = f'1:{fnum(T_["fru"] / T_["glu"], 2)}' if T_["glu"] > 0 else ("—" if not T_["fru"] else tr("solo fructosa"))
        warn = []
        if glh > 60:
            warn.append(tr("más de 60 g/h de glucosa: el exceso no se absorbe sin fructosa"))
        if chh > 60 and T_["glu"] > 0 and T_["fru"] / T_["glu"] < 0.5:
            warn.append(tr("por encima de 60 g/h conviene una proporción glucosa:fructosa de 2:1 a 1:0,8"))
        caf_kg = T_["caf"] / P["w"]
        c_caf = GREEN if 3 <= caf_kg <= 6 else (MUTED if caf_kg < 3 else (ORANGE if caf_kg <= 9 else RED))
        kc_a = float(a["kcal"]) if pd.notna(a["kcal"]) and a["kcal"] else 0.0
        na_l = T_["na"] / (T_["ml"] / 1000) if T_["ml"] > 0 else 0
        cards([(tr("Hidratos"), ORANGE, fnum(T_["ch"]), " g",
                [f'<span style="color:{_band_col(chh, lo, hi)}">{fnum(chh)} g/h</span> · {tr("guía")} {fnum(lo)}–{fnum(hi)} g/h',
                 (f'{tr("tomadas")} {fnum(T_["kcal"])} kcal · {fnum(100 * T_["kcal"] / kc_a)} % {tr("del gasto")}' if kc_a
                  else f'{tr("tomadas")} {fnum(T_["kcal"])} kcal')]),
               (tr("Glucosa : fructosa"), GOLD, ratio, "",
                [f'{tr("glucosa")} <span style="color:{GREEN if glh <= 60 else ORANGE}">{fnum(glh)} g/h</span> · '
                 f'{tr("fructosa")} {fnum(frh)} g/h', f'{fnum(T_["glu"])} g + {fnum(T_["fru"])} g']),
               (tr("Sodio"), TEAL, fnum(T_["na"]), " mg",
                [f'<span style="color:{_band_col(ph(T_["na"]), 300, 600)}">{fnum(ph(T_["na"]))} mg/h</span> · {tr("guía")} 300–600',
                 (f'{fnum(na_l)} mg/l {tr("de líquido")}' if T_["ml"] else tr("sin líquido registrado"))]),
               (tr("Líquido"), GLACIER, fnum(T_["ml"]), " ml",
                [f'<span style="color:{_band_col(ph(T_["ml"]), 400, 800)}">{fnum(ph(T_["ml"]))} ml/h</span> · {tr("guía")} 400–800',
                 tr("según sed y calor")]),
               (tr("Cafeína"), VIOLET, fnum(T_["caf"]), " mg",
                [f'<span style="color:{c_caf}">{fnum(caf_kg, 1)} mg/kg</span> · {tr("efecto")} 3–6 mg/kg',
                 f'BCAA {fnum(T_["bcaa"], 1)} g' if T_["bcaa"] else tr("sin BCAA")])])
        for w_ in warn:
            st.markdown(f'<span class="note" style="color:{ORANGE}">⚠ {w_}</span>', unsafe_allow_html=True)
    st.markdown('<span class="note">Guías orientativas para resistencia: hidratos según la duración (hasta 90 g/h en ultras, '
                'más solo con el intestino entrenado), glucosa hasta ~60 g/h y el resto como fructosa, sodio 300–600 mg/h (más con '
                'calor o mucha sudoración), líquido 400–800 ml/h según sed, cafeína 3–6 mg/kg. Los BCAA no aportan si la proteína '
                'del día es suficiente. Lo tomado suma a la ingesta del día, y los hidratos se guardan también en la actividad de '
                'intervals.icu (hidratos ingeridos).</span>', unsafe_allow_html=True)
    return out


def food_log(P: dict, base: float, k: float, W: list, compact: bool = False):
    """Entrada del registro diario: desayuno, comida, merienda y cena, con alimentos, cantidades y bebida."""
    st.subheader("Registro diario de alimentación")
    st.markdown('<span class="note">Para añadir o quitar alimentos y bebidas de la lista, ve a '
                '<b>Plan 2027 › Alimentos y bebidas</b>.</span>', unsafe_allow_html=True)
    d_ = st.date_input("Día", today, max_value=today + dt.timedelta(days=1), key="nlog_day", format="DD/MM/YYYY")
    C_ = food_cat()
    saved, rest = food_day_get(d_)
    used = {t_: {n_ for mk_, _l in MEALS for n_, _q in saved.get(mk_, {}).get(t_, [])} for t_ in ("f", "b")}
    f_opts = [tr(n_) for n_ in FOOD_ALL if n_ in C_["f_act"] or n_ in used["f"]]
    b_opts = [tr(n_) for n_ in DRINK_ALL if n_ in C_["b_act"] or n_ in used["b"]]
    f_back = {tr(n_): n_ for n_ in FOOD_ALL}
    b_back = {tr(n_): n_ for n_ in DRINK_ALL}
    meals = {}
    combs = C_["comb"]
    CH = C_["cheat"]
    tabs = st.tabs([("🍫 " + tr(lab)) if _k == "x" else lab for _k, lab in MEALS] + ["Durante la actividad"])
    for (mk, lab), tb in zip(MEALS, tabs):
        with tb:
            if mk == "x":
                st.markdown('<span class="note">Caprichos fuera de la dieta habitual (dulces, bollería, fritos, alcohol…): se apuntan '
                            'aquí para verlos aparte. Cuentan en el total del día. Los marcados «🍫 Cheat» en <b>Plan 2027 › Alimentos '
                            'y bebidas</b> salen primero.</span>', unsafe_allow_html=True)
            cur = saved.get(mk, {})
            ovk = f"nlog_ov_{mk}_{d_}"                  # lista con lo añadido con «Añadir» (sin guardar todavía)
            if isinstance(st.session_state.get(ovk), dict):
                cur = st.session_state[ovk]
            ver = st.session_state.get(f"{ovk}_v", 0)
            with st.form(f"nlog_add_{mk}_{d_}", clear_on_submit=True, border=False):
                q1, q2, q3 = st.columns([4, 1.3, 1.3], vertical_alignment="bottom")
                add_opts = [("k", k_) for k_ in sorted(combs)] + [("f", o_) for o_ in f_opts] + [("b", o_) for o_ in b_opts]
                if mk == "x":                     # en «Cheat», primero los caprichos
                    is_ch = lambda x: (x[0] == "f" and f_back.get(x[1]) in CH["f"]) or (x[0] == "b" and b_back.get(x[1]) in CH["b"])  # noqa: E731
                    add_opts = [x for x in add_opts if is_ch(x)] + [x for x in add_opts if not is_ch(x)]
                ico = lambda x: ("🍱 " if x[0] == "k" else "🍫 " if ((x[0] == "f" and f_back.get(x[1]) in CH["f"]) or  # noqa: E731
                                                                     (x[0] == "b" and b_back.get(x[1]) in CH["b"]))
                                 else "🍽 " if x[0] == "f" else "🥤 ") + x[1]
                add_sel = q1.selectbox(tr("Añadir"), add_opts, index=None, key=f"nlog_add_s_{mk}_{d_}", format_func=ico,
                                       placeholder=tr("Busca un alimento, bebida o combinación…"))
                add_n = q2.number_input(tr("Raciones"), 0.5, 20.0, 1.0, 0.5, format="%g", key=f"nlog_add_n_{mk}_{d_}")
                add_go = q3.form_submit_button(f'➕ {tr("Añadir")}', width="stretch")
            # Se registra en raciones (la unidad de cada alimento: pieza, vaso, plato…); los gramos solo si no es una ración
            # entera. Lo guardado son gramos: al volver a abrir el día, lo que sea un número de medias raciones se ve en raciones.
            def _rows(items, DB, kind):
                out_ = []
                for n_, q in items:
                    po = float(DB[n_][4]) if n_ in DB and DB[n_][4] else 0.0
                    r_ = q / po if po else 0
                    whole = po and 0 < r_ <= 20 and abs(r_ * 2 - round(r_ * 2)) < 0.01
                    out_.append({kind: tr(n_), "Raciones": round(r_ * 2) / 2 if whole else np.nan,
                                 "Cantidad": np.nan if whole else float(q)})
                return out_
            df_f = pd.DataFrame(_rows(cur.get("f", []), FOOD_ALL, "Alimento"), columns=["Alimento", "Raciones", "Cantidad"]).astype(
                {"Alimento": object, "Raciones": float, "Cantidad": float})
            df_b = pd.DataFrame(_rows(cur.get("b", []), DRINK_ALL, "Bebida"), columns=["Bebida", "Raciones", "Cantidad"]).astype(
                {"Bebida": object, "Raciones": float, "Cantidad": float})
            rac_col = st.column_config.NumberColumn(tr("Raciones"), min_value=0, max_value=20, step=0.5, format="%g",
                                                    help=tr("Número de raciones (piezas, vasos, platos…). Vacío = 1. La ración de "
                                                            "cada alimento se define en Plan 2027 › Alimentos y bebidas."))
            c1, c2 = (st.container(), st.container()) if compact else st.columns([3, 2])
            with c1:
                ef = st.data_editor(df_f, key=f"nlog_f_{mk}_{d_}_{ver}", num_rows="dynamic", hide_index=True, width="stretch",
                                    column_config={
                                        "Alimento": st.column_config.SelectboxColumn(tr("Alimento"), options=f_opts, width="large"),
                                        "Raciones": rac_col,
                                        "Cantidad": st.column_config.NumberColumn(tr("o gramos"), min_value=0, max_value=3000,
                                                                                  step=5, format="%g",
                                                                                  help=tr("Solo si no son raciones enteras: sustituye a las raciones"))})
            with c2:
                eb = st.data_editor(df_b, key=f"nlog_b_{mk}_{d_}_{ver}", num_rows="dynamic", hide_index=True, width="stretch",
                                    column_config={
                                        "Bebida": st.column_config.SelectboxColumn(tr("Bebida"), options=b_opts, width="medium"),
                                        "Raciones": rac_col,
                                        "Cantidad": st.column_config.NumberColumn(tr("o ml"), min_value=0, max_value=3000,
                                                                                  step=50, format="%g",
                                                                                  help=tr("Solo si no son raciones enteras: sustituye a las raciones"))})

            def _read(ed_, kind, back_, DB, UN, u_):
                lst, txt_ = [], []
                for _, r_ in ed_.iterrows():
                    n_ = back_.get(r_[kind]) if isinstance(r_[kind], str) else None
                    if not n_:
                        continue
                    po = float(DB[n_][4])
                    q, rc = r_["Cantidad"], r_["Raciones"]
                    if pd.notna(q) and q:
                        g = float(q)
                        txt_.append(f'{tr(n_)} {fnum(g)} {u_}')
                    else:
                        n_r = float(rc) if pd.notna(rc) and rc else 1.0
                        g = n_r * po
                        txt_.append(f'{tr(n_)} {fnum(n_r, 1).replace(",0", "").replace(".0", "")} × {tr(UN.get(n_, UNIT_DEF))} '
                                    f'({fnum(g)} {u_})')
                    lst.append([n_, round(g, 1)])
                return lst, txt_
            fl, tf = _read(ef, "Alimento", f_back, FOOD_ALL, FOOD_UNIT, "g")
            bl, tb_ = _read(eb, "Bebida", b_back, DRINK_ALL, DRINK_UNIT, "ml")
            if add_go and add_sel and add_sel[0] == "k" and add_sel[1] in combs:     # combinación: todos sus elementos
                cb_ = combs[add_sel[1]]
                mul = float(add_n)
                st.session_state[ovk] = {"f": fl + [[n_, round(q * mul, 1)] for n_, q in cb_.get("f", []) if n_ in FOOD_ALL],
                                         "b": bl + [[n_, round(q * mul, 1)] for n_, q in cb_.get("b", []) if n_ in DRINK_ALL]}
                st.session_state[f"{ovk}_v"] = ver + 1
                st.rerun()
            if add_go and add_sel and add_sel[0] != "k":
                t_a, lab_a = add_sel
                n_a = (f_back if t_a == "f" else b_back).get(lab_a)
                if n_a:
                    DB_ = FOOD_ALL if t_a == "f" else DRINK_ALL
                    item = [n_a, round(float(add_n) * float(DB_[n_a][4]), 1)]
                    st.session_state[ovk] = {"f": fl + ([item] if t_a == "f" else []), "b": bl + ([item] if t_a == "b" else [])}
                    st.session_state[f"{ovk}_v"] = ver + 1
                    st.rerun()
            if tf or tb_:
                st.markdown('<span class="note">' + " · ".join(_html.escape(x) for x in tf + tb_) + "</span>", unsafe_allow_html=True)
            if fl or bl:
                meals[mk] = {"f": fl, "b": bl}
            t_ = food_totals({mk: {"f": fl, "b": bl}})["by"][mk]
            st.markdown(f'<span class="note"><b style="color:{INK}">{tr(lab)}</b>: {fnum(t_["kcal"])} kcal · '
                        f'{tr("Hidratos")} {fnum(t_["ch"])} g · {tr("Proteína")} {fnum(t_["p"])} g · {tr("Grasa")} {fnum(t_["f"])} g · '
                        f'{tr("Líquido")} {fnum(t_["ml"])} ml</span>', unsafe_allow_html=True)
            if fl or bl:                           # lo apuntado en esta comida, como combinación con nombre
                with st.expander(f'🍱 {tr("Guardar esta comida como combinación")}', expanded=False, key=f"nlog_cbx_{mk}_{d_}"):
                    with st.form(f"nlog_cbf_{mk}_{d_}", border=False):
                        a1, a2 = st.columns([3, 1.4], vertical_alignment="bottom")
                        al_ = a1.text_input(tr("Nombre"), max_chars=40, key=f"nlog_cbn_{mk}_{d_}",
                                            placeholder=tr("p. ej. Ensalada, Bol de fruta del desayuno"))
                        go_cb = a2.form_submit_button(tr("Guardar combinación"), width="stretch")
                    if go_cb:
                        al_ = (al_ or "").strip()
                        if not al_:
                            st.error(tr("Escribe un nombre."))
                        elif al_ in combs:
                            st.error(tr("Ya hay una combinación con ese nombre: cámbialo o edítala en Plan 2027 › Alimentos y bebidas."))
                        else:
                            try:
                                food_cat_save(comb={**combs, al_: {k_: v for k_, v in {"f": fl, "b": bl}.items() if v}})
                                st.toast(f'{tr("Combinación guardada")}: {al_}')
                                st.rerun()
                            except Exception as e:  # noqa: BLE001
                                st.error(f"{tr('No se pudo guardar')}: {e}")
    # Caprichos del día: la pestaña «Cheat» y los marcados «🍫 Cheat» apuntados en otras comidas
    ch_k = 0.0
    for mk_, m_ in meals.items():
        if mk_ == "a":
            continue
        for t_, DB in (("f", FOOD_ALL), ("b", DRINK_ALL)):
            for n_, q in m_.get(t_, []):
                if mk_ == "x" or n_ in CH[t_]:
                    ch_k += (DB.get(n_) or (0,))[0] * float(q) / 100
    if ch_k > 0:
        tot_k = food_totals(meals)["kcal"]
        st.markdown(f'<div class="note" style="color:{ORANGE}">🍫 {tr("Cheat del día")}: <b>{fnum(ch_k)} kcal</b>'
                    + (f' ({fnum(100 * ch_k / tot_k)} % {tr("de lo comido")})' if tot_k else "") + "</div>", unsafe_allow_html=True)
    with tabs[-1]:
        acts = sport_log(d_, saved.get("a", {}), C_, P, compact)
        if acts:
            meals["a"] = acts
    tot = food_totals(meals)
    gasto, h_, src_ = food_day_target(d_, P, base, k, W)
    M_ = nut_macros(gasto, P)
    lo, hi, lab_ = nut_ch_band(h_)
    bal = tot["kcal"] - gasto
    pct = tot["kcal"] / gasto * 100 if gasto else 0
    c_bal = GREEN if abs(bal) <= 0.1 * gasto else (ORANGE if bal < 0 else GLACIER)

    def _vs(v, tgt):
        c_ = GREEN if 0.9 * tgt <= v <= 1.15 * tgt else (ORANGE if v < 0.9 * tgt else GLACIER)
        return f'<span style="color:{c_}">{fnum(100 * v / tgt) if tgt else "—"} %</span>'

    cards([(tr("Ingesta"), GOLD, fnum(tot["kcal"]), " kcal",
            [f'{tr("gasto del día")} {fnum(gasto)} kcal ({tr("con el plan") if src_ == "plan" else tr("Real").lower()})',
             f'<span style="color:{c_bal}">{tr("Balance")} {"+" if bal >= 0 else "−"}{fnum(abs(bal))} kcal · {fnum(pct)} %</span>']),
           (tr("Hidratos"), ORANGE, fnum(tot["ch"]), " g",
            [f'{tr("objetivo")} {fnum(M_["ch"])} g · {_vs(tot["ch"], M_["ch"])}',
             f'{fnum(tot["ch"] / P["w"], 1)} g/kg · {tr("guía")} {fnum(lo)}–{fnum(hi)}']),
           (tr("Proteína"), TEAL, fnum(tot["p"]), " g", [f'{tr("objetivo")} {fnum(M_["p"])} g · {_vs(tot["p"], M_["p"])}',
                                                          f'{fnum(tot["p"] / P["w"], 1)} g/kg']),
           (tr("Grasa"), VIOLET, fnum(tot["f"]), " g", [f'{tr("objetivo")} {fnum(M_["f"])} g · {_vs(tot["f"], M_["f"])}']),
           (tr("Líquido"), GLACIER, fnum(tot["ml"] / 1000, 1), " l", [tr("bebidas registradas")])])
    b1, b2 = st.columns([1, 3], vertical_alignment="center")
    if b1.button("Guardar el día" + ("" if demo else " en intervals.icu"), type="primary", key=f"nlog_save_{d_}", width="stretch"):
        try:
            food_day_save(d_, meals, rest)
            for k_ov in [k2 for k2 in st.session_state if str(k2).startswith(f"nlog_ov_") and str(k2).endswith(str(d_))]:
                st.session_state.pop(k_ov, None)
            st.toast(tr("Día guardado"))
        except Exception as e:  # noqa: BLE001
            st.error(f"{tr('No se pudo guardar')}: {e}")
    b2.markdown('<span class="note">Se guarda en el bienestar del día de intervals.icu: los totales en sus campos de nutrición '
                '(calorías, hidratos, proteína y grasa) y el detalle de las comidas en el comentario del día, sin borrar lo que '
                'ya hubiera escrito. Raciones vacías = 1 ración. Valores medios de tablas de composición: orientativos.</span>',
                unsafe_allow_html=True)

    # Semana: ingesta registrada frente al gasto y al objetivo del plan
    if compact:
        return
    w_ = next((w for w in W if w["frm"] <= d_ <= w["to"]), None)
    frm = w_["frm"] if w_ else d_ - dt.timedelta(days=d_.weekday())
    got = food_week_intake(frm, frm + dt.timedelta(days=6))
    if d_ in got or meals:
        got[d_] = dict(kcal=tot["kcal"], ch=tot["ch"], p=tot["p"], f=tot["f"])
    rows = []
    for i in range(7):
        di = frm + dt.timedelta(days=i)
        g_, h_i, s_i = food_day_target(di, P, base, k, W)
        Mi = nut_macros(g_, P)
        it = got.get(di)
        rows.append({"Día": f'{DIAS_L[i][:3]} {di:%d/%m}', "Origen": tr("plan") if s_i == "plan" else tr("Real").lower(), "Gasto": g_,
                     "Ingesta": it["kcal"] if it else np.nan, "Balance": (it["kcal"] - g_) if it else np.nan,
                     "CH|Obj.": Mi["ch"], "CH|Real": it["ch"] if it else np.nan,
                     "Prot.|Obj.": Mi["p"], "Prot.|Real": it["p"] if it else np.nan,
                     "Grasa|Obj.": Mi["f"], "Grasa|Real": it["f"] if it else np.nan})
    FT = pd.DataFrame(rows)
    f0 = lambda v: fnum(v) if pd.notna(v) else "—"  # noqa: E731

    def _bal(v):
        if pd.isna(v):
            return "—"
        c_ = GREEN if abs(v) <= 250 else (ORANGE if v < 0 else GLACIER)
        return f'<span style="color:{c_}">{"+" if v >= 0 else "−"}{fnum(abs(v))}</span>'

    st.markdown("**" + tr("Semana · ingesta frente a gasto y objetivo") + "**")
    html_table(FT, left={"Día", "Origen"}, fmt={"Gasto": f0, "Ingesta": f0, "Balance": _bal, "CH|Obj.": f0, "CH|Real": f0,
                                                "Prot.|Obj.": f0, "Prot.|Real": f0, "Grasa|Obj.": f0, "Grasa|Real": f0},
               groups=[("", 2, ""), ("kcal", 3, "g"), ("Hidratos g", 2, "g"), ("Proteína g", 2, "g"), ("Grasa g", 2, "g")],
               group_start={"Gasto", "CH|Obj.", "Prot.|Obj.", "Grasa|Obj."},
               sub={"Obj.": "Objetivo", "Real": "Real"},
               row_classes=["cur" if frm + dt.timedelta(days=i) == d_ else "" for i in range(7)])
    st.markdown('<span class="note">Gasto = basal y actividad diaria + ejercicio: real en los días pasados, el mayor entre real y plan '
                'hoy y el del plan en los días que vienen. Objetivo de macros según ese gasto. Balance en verde dentro de ±250 kcal, '
                'naranja si falta energía y azul si sobra.</span>', unsafe_allow_html=True)


def _fold(s_: str) -> str:
    """Texto sin acentos y en minúsculas, para buscar."""
    import unicodedata
    return "".join(c for c in unicodedata.normalize("NFD", str(s_)) if unicodedata.category(c) != "Mn").casefold()


def cat_view(df0: pd.DataFrame, key: str, sort_cols: list, types: list | None = None, compact: bool = False) -> pd.DataFrame:
    """Buscar, filtrar y ordenar una tabla de la lista de alimentos. Devuelve las filas visibles (el resto se guarda tal cual)."""
    cs = st.columns([3, 2, 2, 2, 1] if types else [3, 2, 2, 1]) if not compact else None
    box = (lambda i_: cs[i_]) if cs else (lambda i_: st)
    q = box(0).text_input("Buscar", key=f"{key}_q", placeholder=tr("Nombre…"), label_visibility="collapsed" if not compact else "visible")
    show = box(1).selectbox("Mostrar", ["Todos", "En la lista", "Quitados", "Propios", "Cambiados"], key=f"{key}_show",
                            label_visibility="collapsed" if not compact else "visible", format_func=tr)
    i0 = 2
    tsel = None
    if types:
        tsel = box(2).selectbox("Tipo", ["Todos los tipos"] + types, key=f"{key}_type",
                                label_visibility="collapsed" if not compact else "visible", format_func=tr)
        i0 = 3
    scol = box(i0).selectbox("Ordenar por", sort_cols, key=f"{key}_sort", label_visibility="collapsed" if not compact else "visible",
                             format_func=lambda c: f'{tr("Ordenar por")}: {tr(c)}')
    desc = box(i0 + 1).toggle("↓", key=f"{key}_desc", help=tr("Orden descendente"))
    v = df0
    if q.strip():
        qq = _fold(q.strip())
        v = v[v["Nombre"].map(lambda x: qq in _fold(x))]
    if show == "En la lista":
        v = v[v["En la lista"]]
    elif show == "Quitados":
        v = v[~v["En la lista"]]
    elif show == "Propios":
        v = v[v["Origen"] == tr("Propio")]
    elif show == "Cambiados":
        v = v[v["Origen"] == tr("App · cambiado")]
    if types and tsel and tsel != "Todos los tipos":
        v = v[v["Tipo"] == tr(tsel)]
    if scol in v.columns:
        if v[scol].dtype == object:
            v = v.sort_values(scol, key=lambda c: c.map(lambda x: _fold(x) if isinstance(x, str) else ""), ascending=not desc, kind="stable")
        else:
            v = v.sort_values(scol, ascending=not desc, kind="stable", na_position="last")
    if len(v) < len(df0):
        st.markdown(f'<span class="note">{fnum(len(v))} {tr("de")} {fnum(len(df0))} · '
                    f'{tr("las filas ocultas por el filtro no cambian al guardar")}</span>', unsafe_allow_html=True)
    return v.reset_index(drop=True)


# ─────────────── Búsqueda en línea (Open Food Facts) para añadir a la lista ───────────────
# Base de datos abierta de productos envasados (sin clave). Solo lectura; lo elegido se guarda en la lista con el botón.
OFF_SEARCH = "https://search.openfoodfacts.org/search"           # buscador nuevo (Search-a-licious): rápido
OFF_URL = "https://world.openfoodfacts.org/cgi/search.pl"         # el clásico, de reserva (a menudo saturado: 503)
OFF_FIELDS = ("code,product_name,product_name_es,product_name_ca,product_name_en,abbreviated_product_name,generic_name,"
              "generic_name_es,brands,nutriments,serving_size,serving_quantity,quantity")
OFF_UA = {"User-Agent": "LlibretaD+/2 (app personal de entrenamiento)"}
_UNIT_WORDS = {"g", "gr", "gramos", "grams", "ml", "cl", "l", "kg", "oz", "mg", "dl"}


def _off_get(url: str, prm: dict) -> dict:
    """GET con un reintento si el servidor está saturado (429/502/503/504)."""
    import time
    for i in range(2):
        r = requests.get(url, params=prm, timeout=15, headers=OFF_UA)
        if r.status_code in (429, 502, 503, 504) and i == 0:
            time.sleep(1.5)
            continue
        r.raise_for_status()
        return r.json()
    return {}


_OFF_STOP = {"de", "del", "la", "el", "los", "las", "y", "con", "en", "a", "al", "sin", "i", "amb", "d", "l", "per", "the", "of",
             "and", "with"}


def off_words(q: str) -> str:
    """Palabras útiles para buscar: sin signos (guiones largos «–», comillas, paréntesis…) ni palabras vacías («de», «con»…).
    Con «AND» entre palabras, un signo suelto o un «de» que el buscador descarta dejaba la búsqueda sin resultados."""
    ws = [w for w in re.sub(r"[^\w]+", " ", q.lower()).split() if w not in _OFF_STOP and len(w) > 1]
    return " ".join(ws)


def off_code(q: str) -> str | None:
    """Código de barras escrito o dentro de un enlace de Open Food Facts (…/producto/3458384009855/…)."""
    m = re.search(r"(?:^|/|\s)(\d{8,14})(?:/|\s|$)", q.strip())
    return m.group(1) if m else None


@st.cache_data(ttl=86400, show_spinner=False)
def off_product(code: str) -> list[dict]:
    """Un producto por su código de barras: la base de datos en vivo (incluye los productos nuevos)."""
    d = _off_get(f"https://world.openfoodfacts.org/api/v2/product/{code}.json", {"fields": OFF_FIELDS})
    return [d["product"]] if d.get("status") == 1 and d.get("product") else []


@st.cache_data(ttl=86400, show_spinner=False)
def off_search(q: str) -> list[dict]:
    """Productos de Open Food Facts que coinciden con el texto: primero el buscador nuevo (los que se venden en España y, si
    no hay, todos); si falla, el clásico. Los errores no se guardan en la caché, así que se puede volver a intentar."""
    q_ = off_words(q)
    errs = []
    # todas las palabras tienen que estar (sin AND, el buscador devuelve cualquier producto con alguna de ellas)
    q_and = " AND ".join(q_.split())
    for qq in (f'({q_and}) AND countries_tags:"en:spain"', q_and):
        try:
            d = _off_get(OFF_SEARCH, {"q": qq, "langs": "es,ca,en", "page_size": 20, "fields": OFF_FIELDS})
            hits = list(d.get("hits") or [])
            if hits:
                return hits
        except Exception as e:  # noqa: BLE001
            errs.append(e)
            break
    try:
        d = _off_get(OFF_URL, {"search_terms": q_, "search_simple": 1, "action": "process", "json": 1, "page_size": 20,
                               "fields": OFF_FIELDS})
        return list(d.get("products") or [])
    except Exception as e:  # noqa: BLE001
        if errs:
            raise RuntimeError(tr("Open Food Facts no responde ahora mismo (servidor saturado). Prueba de nuevo en unos minutos.")) from e
        raise


def _off_str(v) -> str:
    """Texto de un campo de Open Food Facts: el buscador nuevo devuelve algunos como lista (marcas) o por idioma (dict)."""
    if isinstance(v, dict):
        v = next((v[k] for k in ("es", "ca", "main", "en") if v.get(k)), next((x for x in v.values() if x), ""))
    if isinstance(v, (list, tuple)):
        v = next((x for x in v if x), "")
        return _off_str(v)
    return str(v or "").strip()


def _off_num(n: dict, k: str):
    v = n.get(k)
    try:
        return float(v) if v not in (None, "") else None
    except (TypeError, ValueError):
        return None


def off_parse(p: dict, kind: str) -> dict | None:
    """Producto de Open Food Facts → valores de la lista: por 100 g/ml y ración (alimentos y bebidas) o por unidad (deporte)."""
    n = p.get("nutriments") or {}
    br_ = _off_str(p.get("brands")).split(",")[0].strip().lower()
    cands = [_off_str(p.get(k)) for k in ("product_name_es", "product_name", "product_name_ca", "product_name_en",
                                          "abbreviated_product_name", "generic_name_es", "generic_name")]
    cands = [c for c in cands if c]
    nm = next((c for c in cands if c.lower() != br_), cands[0] if cands else "")   # el nombre, no solo la marca
    qn = _off_str(p.get("quantity"))
    if nm and nm.lower() == br_ and qn:
        nm = f"{nm} {qn}"
    if not nm:
        return None
    kc = _off_num(n, "energy-kcal_100g")
    if kc is None and _off_num(n, "energy_100g") is not None:
        kc = _off_num(n, "energy_100g") / 4.184
    ch, pr, ft = (_off_num(n, k) for k in ("carbohydrates_100g", "proteins_100g", "fat_100g"))
    if all(v is None for v in (kc, ch, pr, ft)):
        return None
    ch, pr, ft = ch or 0.0, pr or 0.0, ft or 0.0
    kc = kc if kc is not None else 4 * ch + 4 * pr + 9 * ft
    brand = _off_str(p.get("brands")).split(",")[0].strip()
    sq = _off_num(p, "serving_quantity")
    ss = _off_str(p.get("serving_size"))
    unit = ""
    m = re.match(r"^\s*(\d+(?:[.,]\d+)?)?\s*([^\d(]+?)\s*(?:\(|\d|$)", ss.lower())
    if m and m.group(2).strip(" .") and m.group(2).strip(" .") not in _UNIT_WORDS:
        w = m.group(2).strip(" .")
        w = "ración" if w in ("portion", "porción", "porcion", "serving", "ración", "racion") else w
        cnt = float(m.group(1).replace(",", ".")) if m.group(1) else 1
        unit = (f"{fnum(cnt, 1)} {w}" if cnt != 1 else w)[:20]
    out = dict(code=_off_str(p.get("code")), name=nm[:60], brand=brand[:30], kcal=round(kc), ch=round(ch, 1), pr=round(pr, 1),
               ft=round(ft, 1), serv=round(sq) if sq and 0 < sq <= 3000 else None, unit=unit, ss=ss[:40])
    if kind == "s":
        q_ = out["serv"] or 100
        k_ = q_ / 100
        fr = _off_num(n, "fructose_100g")
        gl = _off_num(n, "glucose_100g")
        sod = _off_num(n, "sodium_100g")
        if sod is None and _off_num(n, "salt_100g") is not None:
            sod = _off_num(n, "salt_100g") / 2.5
        caf = _off_num(n, "caffeine_100g")
        low = (nm + " " + ss).lower()
        tipo = ("Gel" if "gel" in low else "Cafeína" if "cafe" in low and ch < 5 else "BCAA" if "bcaa" in low
                else "Sales" if any(x in low for x in ("sal", "electrol", "tablet")) and ch < 10
                else "Líquido" if any(x in low for x in ("bebida", "drink", "isot", "ml")) else "Sólido")
        chu = round(ch * k_, 1)
        if fr is not None:
            fru = round(fr * k_, 1)
            glu = round(max(0.0, chu - fru), 1)
        elif gl is not None:
            glu = round(gl * k_, 1)
            fru = round(max(0.0, chu - glu), 1)
        else:
            glu = fru = 0.0          # reparto desconocido: se escribe la proporción en Glu:Fru
        out.update(tipo=tipo, s_unit=(unit or {"Gel": "gel", "Sólido": "barrita", "Líquido": "bidón", "Sales": "cápsula",
                                               "Cafeína": "cápsula", "BCAA": "dosis"}[tipo]),
                   s_vals=[tipo, None, round(kc * k_), chu, glu, fru, round(pr * k_, 1), round(ft * k_, 1),
                           round((sod or 0) * 1000 * k_), round((caf or 0) * 1000 * k_), 0,
                           round(q_) if tipo == "Líquido" else 0])
    return out


def off_lookup_ui(t_: str, C_: dict):
    """Buscar un producto en línea y añadirlo a la lista con sus valores (se guarda al pulsar el botón)."""
    unit = "ml" if t_ == "b" else "g"
    with st.expander(f'🔎 {tr("Buscar en línea y añadir")} · Open Food Facts', key=f"off_{t_}_x"):
        with st.form(f"off_{t_}_f", border=False):
            c1, c2 = st.columns([4, 1], vertical_alignment="bottom")
            q = c1.text_input(tr("Producto, marca, código de barras o enlace de Open Food Facts"), key=f"off_{t_}_q", max_chars=200,
                              placeholder=tr({"f": "p. ej. yogur griego, pan de molde, Hacendado avena",
                                              "b": "p. ej. bebida de avena, Aquarius, cerveza sin alcohol",
                                              "s": "p. ej. gel Maurten, barrita 226ers, sales Precision"}[t_]))
            go_ = c2.form_submit_button(tr("Buscar"), width="stretch")
        if go_ and q.strip():
            try:
                code_ = off_code(q)
                hits = off_product(code_) if code_ else off_search(q.strip())
                hs = [h for h in (off_parse(p, t_) for p in hits) if h]
                # primero los que tienen todas las palabras buscadas en el nombre o la marca
                ws = [] if code_ else [_fold(w) for w in off_words(q).split()]
                sc = lambda h: sum(w in _fold(h["name"] + " " + h["brand"]) for w in ws)  # noqa: E731
                hs = sorted(hs, key=lambda h: -sc(h))
                if hs and sc(hs[0]) == len(ws):
                    hs = [h for h in hs if sc(h) == len(ws)]
                st.session_state[f"off_{t_}_hits"] = hs
            except Exception as e:  # noqa: BLE001
                st.session_state[f"off_{t_}_hits"] = []
                msg_ = str(e)
                if any(c in msg_ for c in ("503", "502", "504", "429", "Timeout", "timed out")):
                    msg_ = tr("Open Food Facts no responde ahora mismo (servidor saturado). Prueba de nuevo en unos minutos.")
                st.warning(f'{tr("No se pudo buscar en Open Food Facts")}: {msg_}')
        hits = st.session_state.get(f"off_{t_}_hits")
        if hits is None:
            st.markdown(f'<span class="note">{tr("Busca por nombre o marca. Salen los valores de la etiqueta del producto (por 100 g o 100 ml) y su ración; eliges uno, lo revisas y se añade a la lista. Va mejor con productos envasados; para alimentos frescos usa los de la app o escríbelos en la tabla.")}</span>',
                        unsafe_allow_html=True)
            return
        if not hits:
            st.info(tr("Sin resultados con valores nutricionales. Prueba con otro nombre o con la marca."))
            return
        if t_ == "s":
            tb_ = pd.DataFrame([{"Producto": h["name"], "Marca": h["brand"], "Tipo": tr(h["tipo"]),
                                 "Ficha": f'https://world.openfoodfacts.org/product/{h["code"]}' if h["code"] else None,
                                 "Ración": h["ss"] or (f'{h["serv"]} g' if h["serv"] else "—"), "kcal": h["s_vals"][2],
                                 "Hidratos g": h["s_vals"][3], "Sodio mg": h["s_vals"][8]} for h in hits])
        else:
            tb_ = pd.DataFrame([{"Producto": h["name"], "Marca": h["brand"], f"kcal/100 {unit}": h["kcal"], "Hidratos": h["ch"],
                                 "Proteína": h["pr"], "Grasa": h["ft"], "Ración": h["ss"] or "—",
                                 "Ficha": f'https://world.openfoodfacts.org/product/{h["code"]}' if h["code"] else None} for h in hits])
        ev = st.dataframe(tb_, hide_index=True, width="stretch", on_select="rerun", selection_mode="single-row",
                          key=f"off_{t_}_tbl", height=min(36 + 35 * len(tb_), 300),
                          column_config={"Ficha": st.column_config.LinkColumn(tr("Ficha"), display_text="↗",
                                                                              help=tr("Abre el producto en Open Food Facts"))})
        rows_ = (getattr(getattr(ev, "selection", None), "rows", None) or []) if ev is not None else []
        if not rows_:
            st.markdown(f'<span class="note">{tr("Marca una fila para añadirla.")} {tr("Valores por unidad: la ración de la etiqueta.") if t_ == "s" else ""}</span>',
                        unsafe_allow_html=True)
            return
        h = hits[rows_[0]]
        nm0 = (f'{h["name"]} · {h["brand"]}' if h["brand"] and h["brand"].lower() not in h["name"].lower() else h["name"])[:60]
        exist = set(C_[t_]) | set(C_[t_ + "_del"])
        with st.form(f"off_{t_}_add", border=True):
            if t_ == "s":
                a1, a2, a3 = st.columns([3, 1.2, 1.2])
                nm = a1.text_input(tr("Nombre en la lista"), nm0, max_chars=60)
                tipo = a2.selectbox(tr("Tipo"), SPORT_TYPES, index=SPORT_TYPES.index(h["tipo"]), format_func=tr)
                un = a3.text_input(tr("Unidad"), h["s_unit"], max_chars=20)
                v_ = h["s_vals"]
                st.markdown(f'<span class="note">{tr("Por unidad")}: {fnum(v_[2])} kcal · {tr("hidratos")} {fnum(v_[3], 1)} g'
                            + (f' (glu:fru {glu_fru_txt(v_[4], v_[5])})' if v_[4] or v_[5] else f' · {tr("proporción glucosa:fructosa desconocida: escríbela en la columna Glu:Fru")}')
                            + f' · {tr("sodio")} {fnum(v_[8])} mg' + (f' · {tr("cafeína")} {fnum(v_[9])} mg' if v_[9] else "")
                            + f' · {tr("ración de la etiqueta")}: {_html.escape(h["ss"] or "—")}</span>', unsafe_allow_html=True)
            else:
                a1, a2, a3 = st.columns([3, 1.2, 1.2])
                nm = a1.text_input(tr("Nombre en la lista"), nm0, max_chars=60)
                serv = a2.number_input(f'{tr("Ración")} ({unit})', 1.0, 3000.0, float(h["serv"] or 100), 5.0, format="%g")
                un = a3.text_input(tr("Nombre de la ración"), h["unit"] or ("vaso" if t_ == "b" else UNIT_DEF), max_chars=20)
                st.markdown(f'<span class="note">{tr("Por 100")} {unit}: {fnum(h["kcal"])} kcal · {tr("hidratos")} {fnum(h["ch"], 1)} g · '
                            f'{tr("proteína")} {fnum(h["pr"], 1)} g · {tr("grasa")} {fnum(h["ft"], 1)} g · '
                            f'{tr("ración de la etiqueta")}: {_html.escape(h["ss"] or "—")}</span>', unsafe_allow_html=True)
            pend = any(isinstance(v2, dict) and (v2.get("edited_rows") or v2.get("added_rows") or v2.get("deleted_rows"))
                       for k2, v2 in st.session_state.items() if str(k2).startswith(f"fcat_{t_}__"))
            ok = st.form_submit_button(f'➕ {tr("Añadir a la lista")}' + ("" if demo else f' {tr("y guardar en intervals.icu")}'),
                                       type="primary")
        if ok:
            nm = (nm or "").strip()
            if not nm:
                st.error(tr("Escribe un nombre."))
            elif nm in exist or nm in {tr(x) for x in exist}:
                st.error(tr("Ya hay uno con ese nombre en la lista: cámbialo."))
            elif pend:
                st.error(tr("Tienes cambios sin guardar en la tabla de abajo: guárdalos o deshazlos antes de añadir."))
            else:
                add = {k_: dict(C_["add"].get(k_) or {}) for k_ in ("f", "b", "s")}
                units = {k_: dict((C_["unit"] or {}).get(k_) or {}) for k_ in ("f", "b")}
                if t_ == "s":
                    v_ = list(h["s_vals"])
                    v_[0], v_[1] = tipo, (un or h["s_unit"]).strip()[:20]
                    add["s"][nm] = v_
                else:
                    add[t_][nm] = [float(h["kcal"]), float(h["ch"]), float(h["pr"]), float(h["ft"]), float(serv)]
                    if (un or "").strip() and un.strip() != UNIT_DEF:
                        units[t_][nm] = un.strip()[:20]
                try:
                    food_cat_save(add, {k_: sorted(C_[k_ + "_hide"]) for k_ in ("f", "b", "s")},
                                  {k_: sorted(C_[k_ + "_del"]) for k_ in ("f", "b", "s")}, units)
                    for k2 in [k2 for k2 in st.session_state if str(k2).startswith((f"off_{t_}_hits", f"off_{t_}_tbl"))]:
                        st.session_state.pop(k2, None)
                    st.toast(f'{tr("Añadido a la lista")}: {nm}')
                    st.rerun()
                except Exception as e:  # noqa: BLE001
                    st.error(f"{tr('No se pudo guardar')}: {e}")


def cat_key(key: str) -> str:
    """Clave del editor que cambia con el filtro y el orden (las ediciones se guardan por fila)."""
    ss = st.session_state
    return f"{key}__" + "|".join(str(ss.get(f"{key}_{x}", "")) for x in ("q", "show", "type", "sort", "desc"))


def parse_ratio(txt) -> tuple[float, float] | None:
    """«2:1», «1:0,8», «1:0.8», «1» → (glucosa, fructosa) en proporción; None si no se entiende."""
    if not isinstance(txt, str) or not txt.strip():
        return None
    m_ = re.match(r"^\s*(\d+(?:[.,]\d+)?)\s*(?:[:/]\s*(\d+(?:[.,]\d+)?))?\s*$", txt)
    if not m_:
        return None
    a = float(m_.group(1).replace(",", "."))
    b = float(m_.group(2).replace(",", ".")) if m_.group(2) else 0.0
    return (a, b) if a + b > 0 else None


def glu_fru_txt(gl: float, fr: float) -> str:
    return f'1:{fnum(fr / gl, 2)}' if gl > 0 else ("—" if not fr else "0:1")


def sport_admin(C_: dict, errs: list, compact: bool) -> tuple[dict, list]:
    """Lista de nutrición deportiva: valores por unidad."""
    all_ = C_["s"]
    disp = {n_: (tr(n_) if n_ in SPORT else n_) for n_ in all_}
    back = {v: k_ for k_, v in disp.items()}
    COLS = ["Hidratos g", "Glucosa g", "Fructosa g", "Sodio mg", "Cafeína mg", "BCAA g", "Líquido ml", "kcal", "Proteína g", "Grasa g"]
    IDX = [3, 4, 5, 8, 9, 10, 11, 2, 6, 7]
    rows = []
    for n_, v in sorted(all_.items(), key=lambda kv: (kv[0] not in SPORT, SPORT_TYPES.index(kv[1][0]) if kv[1][0] in SPORT_TYPES else 9,
                                                      disp[kv[0]].lower())):
        r_ = {"En la lista": n_ not in C_["s_hide"], "Nombre": disp[n_], "Tipo": tr(v[0]), "Unidad": tr(v[1])}
        r_.update({c: float(v[i]) for c, i in zip(COLS, IDX)})
        r_["Glu:Fru"] = glu_fru_txt(float(v[4]), float(v[5]))
        r_["Origen"] = (tr("App · cambiado") if list(v) != list(SPORT[n_]) else tr("App")) if n_ in SPORT else tr("Propio")
        r_[DEL_COL] = False
        if n_ not in C_["s_del"]:
            rows.append(r_)
    df0 = pd.DataFrame(rows).astype({**{c: float for c in COLS}, "En la lista": bool, "Nombre": object, "Tipo": object,
                                     "Unidad": object, "Glu:Fru": object, "Origen": object, DEL_COL: bool})
    n_act, n_own = len(C_["s_act"]), sum(1 for n_ in all_ if n_ not in SPORT)
    n_del = len(C_["s_del"])
    st.markdown(f'<span class="note">{fnum(n_act)} {tr("en la lista")} · {fnum(len(all_) - n_act - n_del)} {tr("quitados")} · '
                f'{fnum(n_own)} {tr("propios")} · ' + (f'{fnum(n_del)} {tr("eliminados")} · ' if n_del else '') +
                f'{tr("valores por unidad (gel, cápsula, bidón…)")}. '
                f'{tr("Glucosa incluye maltodextrina y almidón; fructosa, la fructosa libre y la mitad de la sacarosa.")}</span>',
                unsafe_allow_html=True)
    t_opts = [tr(t_) for t_ in SPORT_TYPES]
    t_back = {tr(t_): t_ for t_ in SPORT_TYPES}
    num = lambda lab, mx, stp: st.column_config.NumberColumn(tr(lab), min_value=0, max_value=mx, step=stp, format="%.1f")  # noqa: E731
    off_lookup_ui("s", C_)
    view = cat_view(df0, "fcat_s", ["Nombre", "Tipo", "Hidratos g", "Glucosa g", "Fructosa g", "Sodio mg", "Cafeína mg", "kcal", "Origen"],
                    types=SPORT_TYPES, compact=compact)
    hidden = set(df0["Nombre"]) - set(view["Nombre"])
    ed = st.data_editor(view, key=cat_key("fcat_s"), num_rows="dynamic", hide_index=True, width="stretch",
                        height=min(36 * (len(view) + 2), 640) if not compact else 420,
                        column_config={"En la lista": st.column_config.CheckboxColumn(tr("En la lista"), default=True, width="medium"),
                                       "Nombre": st.column_config.TextColumn(tr("Nombre"), width="large", required=True, max_chars=60),
                                       "Tipo": st.column_config.SelectboxColumn(tr("Tipo"), options=t_opts, required=True, width="small"),
                                       "Unidad": st.column_config.TextColumn(tr("Unidad"), width="small", max_chars=20),
                                       "Hidratos g": num("Hidratos g", 200, 0.5), "Glucosa g": num("Glucosa g", 200, 0.5),
                                       "Fructosa g": num("Fructosa g", 200, 0.5), "Sodio mg": num("Sodio mg", 5000, 10.0),
                                       "Cafeína mg": num("Cafeína mg", 500, 5.0), "BCAA g": num("BCAA g", 50, 0.5),
                                       "Líquido ml": num("Líquido ml", 2000, 50.0), "kcal": num("kcal", 2000, 1.0),
                                       "Proteína g": num("Proteína g", 100, 0.5), "Grasa g": num("Grasa g", 100, 0.5),
                                       "Glu:Fru": st.column_config.TextColumn(
                                           "Glu:Fru", width="small", max_chars=12,
                                           help=tr("Proporción glucosa:fructosa (p. ej. 2:1 o 1:0,8). Al cambiarla se reparten los "
                                                   "hidratos entre glucosa y fructosa.")),
                                       "Origen": st.column_config.TextColumn(tr("Origen"), disabled=True, width="small"),
                                       DEL_COL: st.column_config.CheckboxColumn(
                                           f'🗑 {tr("Eliminar")}', default=False, width="medium",
                                           help=tr("Marca las filas que quieras eliminar y pulsa «Guardar la lista». Los propios se "
                                                   "borran; los de la app dejan de salir y se pueden recuperar debajo de la tabla."))},
                        column_order=[DEL_COL, "En la lista", "Nombre", "Tipo", "Unidad", "Hidratos g", "Glu:Fru", "Glucosa g", "Fructosa g",
                                      "Sodio mg", "Cafeína mg", "BCAA g", "Líquido ml", "kcal", "Proteína g", "Grasa g", "Origen"])
    rest_ = cat_restore(C_["s_del"], lambda n_: tr(n_), "fcat_s")
    del_, del_names = set(C_["s_del"]) - rest_, []
    orig = {str(r0["Nombre"]): r0 for _, r0 in df0.iterrows()}
    preview = []
    add_, hide_, seen = {}, set(), set(C_["s_del"])
    for nm in hidden:                     # filas ocultas por el filtro: se quedan como estaban
        n_ = back.get(nm, nm)
        seen.add(n_)
        if n_ in (C_["add"].get("s") or {}):
            v0 = C_["add"]["s"][n_]
            add_[n_] = [str(v0[0]), str(v0[1])] + [float(x) for x in v0[2:12]]
        if n_ in C_["s_hide"]:
            hide_.add(n_)
    for _, r_ in ed.iterrows():
        nm = str(r_["Nombre"]).strip() if isinstance(r_["Nombre"], str) else ""
        if not nm:
            continue
        n_ = back.get(nm, nm)
        if n_ in seen:
            errs.append(f'{tr("Nombre repetido")}: {nm}')
            continue
        seen.add(n_)
        if pd.notna(r_.get(DEL_COL)) and bool(r_.get(DEL_COL)):
            del_names.append(nm)
            if n_ in SPORT:
                del_.add(n_)
            continue
        g_ = lambda c: float(r_[c]) if pd.notna(r_[c]) else 0.0  # noqa: E731
        tipo = t_back.get(r_["Tipo"], "Sólido") if isinstance(r_["Tipo"], str) else "Sólido"
        un = str(r_["Unidad"]).strip() if isinstance(r_["Unidad"], str) and r_["Unidad"].strip() else "unidad"
        if n_ in SPORT and un == tr(SPORT[n_][1]):
            un = SPORT[n_][1]
        ch, gl, fr, pr, ft = g_("Hidratos g"), g_("Glucosa g"), g_("Fructosa g"), g_("Proteína g"), g_("Grasa g")
        # Proporción glucosa:fructosa. Se compara con la fila tal como estaba (no con lo calculado ahora), así:
        #  · si cambias la proporción, se reparten los hidratos (o glucosa + fructosa si no hay hidratos) con ella;
        #  · si cambias solo los hidratos, glucosa y fructosa se reajustan con la proporción que ya tenía;
        #  · si cambias glucosa o fructosa a mano, se respetan (y la proporción se recalcula al guardar).
        rt = (r_["Glu:Fru"] if isinstance(r_["Glu:Fru"], str) else "").strip()
        o_ = orig.get(nm)
        o_rt = str(o_["Glu:Fru"]).strip() if o_ is not None else ""
        of = (lambda c: float(o_[c]) if o_ is not None and pd.notna(o_[c]) else 0.0)  # noqa: E731
        split = None
        if rt and rt not in ("—", o_rt):                                   # proporción escrita o cambiada
            split = parse_ratio(rt.replace("—", ""))
            if split is None:
                errs.append(f'{nm}: {tr("proporción glucosa:fructosa no válida (usa p. ej. 2:1 o 1:0,8)")}')
        elif (o_ is not None and abs(ch - of("Hidratos g")) > 0.05 and abs(gl - of("Glucosa g")) < 0.05
              and abs(fr - of("Fructosa g")) < 0.05 and of("Glucosa g") + of("Fructosa g") > 0):
            split = (of("Glucosa g"), of("Fructosa g"))                   # solo cambian los hidratos: misma proporción
        if split is not None:
            base_ch = ch or (gl + fr)
            if not base_ch:
                errs.append(f'{nm}: {tr("escribe los hidratos para repartirlos con la proporción")}')
            else:
                gl = round(base_ch * split[0] / (split[0] + split[1]), 1)
                fr = round(base_ch - gl, 1)
                ch = base_ch
                if (o_ is None or abs(gl - of("Glucosa g")) > 0.05 or abs(fr - of("Fructosa g")) > 0.05):
                    preview.append(f'{nm}: {fnum(ch, 1)} g → {tr("glucosa")} {fnum(gl, 1)} g · {tr("fructosa")} {fnum(fr, 1)} g '
                                   f'({glu_fru_txt(gl, fr)})')
        if not ch and (gl or fr):
            ch = gl + fr
        kc = g_("kcal") if pd.notna(r_["kcal"]) else round(4 * ch + 4 * pr + 9 * ft, 1)
        if gl + fr > ch + 0.5:
            errs.append(f'{nm}: {tr("glucosa + fructosa pasan de los hidratos")}')
        v = [tipo, un, kc, ch, gl, fr, pr, ft, g_("Sodio mg"), g_("Cafeína mg"), g_("BCAA g"), g_("Líquido ml")]
        if n_ not in SPORT or [str(x) if i < 2 else float(x) for i, x in enumerate(SPORT[n_])] != v:
            add_[n_] = v
        if r_["En la lista"] is not None and pd.notna(r_["En la lista"]) and not bool(r_["En la lista"]):
            hide_.add(n_)
    hide_ |= {n_ for n_ in SPORT if n_ not in seen}
    if preview:                      # la tabla no se puede rellenar sola mientras editas: el reparto se ve aquí y se guarda así
        st.markdown(f'<span class="note">⚖ {tr("Reparto con la proporción glucosa:fructosa (se aplica al guardar)")}:<br>'
                    + "<br>".join(_html.escape(x) for x in preview) + "</span>", unsafe_allow_html=True)
    cat_del_note(del_names)
    return add_, sorted(hide_), sorted(del_)


def _hms(sec: float) -> str:
    sg = "−" if sec < 0 else ""
    sec = int(round(abs(sec)))
    h, r = divmod(sec, 3600)
    return f"{sg}{h}:{r // 60:02d}:{r % 60:02d}"


def act_fix_section(compact: bool = False):
    """Corregir una actividad con un tramo sin grabar: sumar o restar D+, D−, tiempo y km."""
    if not compact:
        st.subheader("Corregir una actividad")
        st.markdown('<div class="note">Si el reloj se encendió tarde o se paró antes de tiempo, añade (o resta) el desnivel '
                    'positivo, el negativo, la distancia y el tiempo del tramo que falta. La corrección se aplica en toda '
                    'la app (temporada, semanas, nutrición, comparar…); las kcal del reloj se escalan con el tiempo. La actividad '
                    'original de intervals.icu no se modifica: su API no permite cambiar el tiempo ni el desnivel de una actividad '
                    'grabada, así que la corrección se guarda aparte y se puede quitar cuando quieras.</div>', unsafe_allow_html=True)
    raw_c = app_note_get(CORR_NAME, "demo_corr")[1]
    corr = dict(raw_c.get("a", {}))
    lim = today - dt.timedelta(days=60)
    da = all_df[(all_df["date"] >= lim) | all_df["id"].astype(str).isin(list(corr))].sort_values("ts", ascending=False) \
        if len(all_df) else all_df
    if not len(da):
        st.info(tr("No hay actividades recientes."))
        return
    ids = da["id"].astype(str).tolist()
    lab = {str(r_["id"]): f'{r_["ts"]:%d/%m/%Y %H:%M} · {r_["name"] or r_["sport"]} · {fnum(r_["km"], 1)} km · {fnum(r_["dp"])} m D+'
           + (" ✎" if r_["corr"] else "") for _, r_ in da.iterrows()}
    aid = st.selectbox("Actividad", ids, format_func=lambda x: lab.get(x, x), key="fix_act")
    a = da[da["id"].astype(str) == aid].iloc[0]
    c0 = corr.get(aid, {})
    o_dp, o_dm = float(a["dp"]) - float(c0.get("dp") or 0), float(a["dm"]) - float(c0.get("dm") or 0)
    o_s, o_km = float(a["secs"]) - float(c0.get("secs") or 0), float(a["km"]) - float(c0.get("km") or 0)
    is_cinta = a["sport"] in CINTA
    if is_cinta:
        st.markdown('<span class="note">En la cinta el D+ sale de la pendiente (pestaña Cinta); aquí solo cuentan el tiempo y los km '
                    '(al cambiar los km también cambia el D+ calculado).</span>',
                    unsafe_allow_html=True)
    imb = o_dm - o_dp
    if not is_cinta and abs(imb) >= 20:
        st.markdown(f'<span class="note">{tr("El reloj registró")} {fnum(o_dp)} m D+ {tr("y")} {fnum(o_dm)} m D− '
                    f'({tr("diferencia")} {fnum(abs(imb))} m). {tr("Si empezaste y acabaste en el mismo punto, el tramo que falta tiene unos")} '
                    f'<b>{fnum(abs(imb))} m {"D+" if imb > 0 else "D−"}</b>.</span>', unsafe_allow_html=True)
    # valores por defecto: la corrección guardada. Cada dato: Sumar/Restar + valor positivo
    k_ = f"fix_{aid}"
    if st.session_state.get("fix_loaded") != aid:
        st.session_state["fix_loaded"] = aid
        for f_ in ("dp", "dm", "km", "secs"):
            v0 = float(c0.get(f_, 0))
            st.session_state[f"{k_}_{f_}_sg"] = "Restar" if v0 < 0 else "Sumar"
            if f_ == "secs":
                st.session_state[k_ + "_min"] = int(abs(v0) // 60)
                st.session_state[k_ + "_sec"] = int(round(abs(v0) % 60))
            else:
                st.session_state[f"{k_}_{f_}"] = abs(v0)
        st.session_state[k_ + "_txt"] = str(c0.get("note", ""))
    if not is_cinta and abs(imb) >= 20 and not c0:
        if st.button(f'{tr("Usar la diferencia")}: +{fnum(abs(imb))} m {"D+" if imb > 0 else "D−"}', key=k_ + "_sug"):
            f_ = "dp" if imb > 0 else "dm"
            st.session_state[f"{k_}_{f_}"] = float(round(abs(imb)))
            st.session_state[f"{k_}_{f_}_sg"] = "Sumar"
            st.rerun()

    def _sgn(f_):
        return -1.0 if st.session_state.get(f"{k_}_{f_}_sg") == "Restar" else 1.0

    cols = st.columns(2 if compact else 4)
    vals = {}
    for i_, (f_, lab_, mx, stp, fmt) in enumerate((("dp", "D+ (m)", 5000.0, 10.0, "%.0f"), ("dm", "D− (m)", 5000.0, 10.0, "%.0f"),
                                                  ("km", "Distancia (km)", 100.0, 0.1, "%.2f"))):
        with cols[i_ % len(cols)]:
            st.segmented_control(lab_, ["Sumar", "Restar"], key=f"{k_}_{f_}_sg", width="stretch", disabled=is_cinta and f_ != "km")
            v_ = st.number_input(lab_, 0.0, mx, step=stp, format=fmt, key=f"{k_}_{f_}", label_visibility="collapsed",
                                 disabled=is_cinta and f_ != "km")
            vals[f_] = v_ * _sgn(f_)
    with cols[3 % len(cols)]:
        st.segmented_control("Tiempo", ["Sumar", "Restar"], key=f"{k_}_secs_sg", width="stretch")
        t1, t2 = st.columns(2)
        dmin = t1.number_input("Minutos", 0, 1440, step=1, key=k_ + "_min", label_visibility="collapsed", help="Minutos")
        dsec = t2.number_input("Segundos", 0, 59, step=1, key=k_ + "_sec", label_visibility="collapsed", help="Segundos")
        st.markdown('<span class="note">min · s</span>', unsafe_allow_html=True)
    note = st.text_input("Motivo (opcional)", key=k_ + "_txt", max_chars=120, placeholder="Reloj encendido tarde")
    ddp, ddm, dkm = vals["dp"], vals["dm"], vals["km"]
    dsecs = (dmin * 60 + dsec) * _sgn("secs")
    if is_cinta:
        ddp = ddm = 0.0
    n_dp, n_dm = max(0.0, o_dp + ddp), max(0.0, o_dm + ddm)
    n_s, n_km = max(0.0, o_s + dsecs), max(0.0, o_km + dkm)
    pace = lambda s_, k__: (f'{int(s_ / k__ // 60)}:{int(s_ / k__ % 60):02d} /km' if k__ > 0 and s_ > 0 else "—")  # noqa: E731
    R_ = pd.DataFrame([
        {"Dato": "D+ (m)", "Reloj": fnum(o_dp), "Corrección": f'{"+" if ddp >= 0 else "−"}{fnum(abs(ddp))}', "Resultado": fnum(n_dp)},
        {"Dato": "D− (m)", "Reloj": fnum(o_dm), "Corrección": f'{"+" if ddm >= 0 else "−"}{fnum(abs(ddm))}', "Resultado": fnum(n_dm)},
        {"Dato": "Tiempo", "Reloj": _hms(o_s), "Corrección": ("+" if dsecs >= 0 else "") + _hms(dsecs), "Resultado": _hms(n_s)},
        {"Dato": "Km", "Reloj": fnum(o_km, 2), "Corrección": f'{"+" if dkm >= 0 else "−"}{fnum(abs(dkm), 2)}', "Resultado": fnum(n_km, 2)},
        {"Dato": "Ritmo", "Reloj": pace(o_s, o_km), "Corrección": "", "Resultado": pace(n_s, n_km)},
        {"Dato": "D+/h", "Reloj": fnum(o_dp / (o_s / 3600)) if o_s else "—", "Corrección": "",
         "Resultado": fnum(n_dp / (n_s / 3600)) if n_s else "—"},
    ])
    html_table(R_, left={"Dato"})
    new_c = {k2: v for k2, v in {"dp": round(ddp), "dm": round(ddm), "secs": int(dsecs), "km": round(dkm, 3)}.items() if v}
    b1, b2, b3 = st.columns([1, 1, 2], vertical_alignment="center")
    if b1.button("Guardar la corrección" + ("" if demo else " en intervals.icu"), type="primary", key="fix_save", width="stretch",
                 disabled=not new_c or (new_c == {k2: v for k2, v in c0.items() if k2 in ("dp", "dm", "secs", "km")}
                                         and note == c0.get("note", ""))):
        corr[aid] = {**new_c, "note": note.strip(), "date": str(a["date"]), "name": str(a["name"] or a["sport"]),
                     "orig": {"dp": round(o_dp), "dm": round(o_dm), "secs": int(o_s), "km": round(o_km, 3)}}
        try:
            app_note_save(CORR_NAME, "demo_corr", {"v": 1, "a": corr})
            st.session_state.pop("fix_loaded", None)
            st.toast(tr("Corrección guardada"))
            st.rerun()
        except Exception as e:  # noqa: BLE001
            st.error(f"{tr('No se pudo guardar')}: {e}")
    if b2.button("Quitar la corrección", key="fix_del", width="stretch", disabled=aid not in corr):
        corr.pop(aid, None)
        try:
            app_note_save(CORR_NAME, "demo_corr", {"v": 1, "a": corr})
            st.session_state.pop("fix_loaded", None)
            st.toast(tr("Corrección quitada"))
            st.rerun()
        except Exception as e:  # noqa: BLE001
            st.error(f"{tr('No se pudo guardar')}: {e}")
    b3.markdown('<span class="note">' + ("Se guarda en la sesión (DEMO)." if demo else
                "Se guarda en intervals.icu en una nota del calendario del 01/01/2000 («Llibreta D+ · correcciones de actividades»).")
                + "</span>", unsafe_allow_html=True)
    if corr and not compact:
        st.markdown("**" + tr("Correcciones guardadas") + "**")
        rows = []
        for i_, c_ in sorted(corr.items(), key=lambda kv: kv[1].get("date", ""), reverse=True):
            rows.append({"Fecha": dt.date.fromisoformat(c_["date"]).strftime("%d/%m/%Y") if c_.get("date") else "—",
                         "Actividad": c_.get("name", i_), "D+": f'{"+" if c_.get("dp", 0) >= 0 else "−"}{fnum(abs(c_.get("dp", 0)))}',
                         "D−": f'{"+" if c_.get("dm", 0) >= 0 else "−"}{fnum(abs(c_.get("dm", 0)))}',
                         "Tiempo": ("+" if c_.get("secs", 0) >= 0 else "") + _hms(c_.get("secs", 0)),
                         "Km": f'{"+" if c_.get("km", 0) >= 0 else "−"}{fnum(abs(c_.get("km", 0)), 2)}', "Motivo": c_.get("note") or "—"})
        html_table(pd.DataFrame(rows), left={"Fecha", "Actividad", "Motivo"})


def food_admin_section(compact: bool = False):
    """Alimentos y bebidas: lista de la app más los propios; añadir, cambiar valores o quitar."""
    C_ = food_cat()
    if not compact:
        st.subheader("Alimentos y bebidas")
        st.markdown('<div class="note">La lista que sale al registrar las comidas en <b>Nutrición</b>. Valores por 100 g '
                    '(alimentos) o 100 ml (bebidas) y la ración habitual con su nombre (pieza, vaso, plato…): al registrar el día basta con poner cuántas raciones. '
                    '<b>Añadir</b>: escribe en la última fila de la tabla. <b>Quitar</b>: desmarca «En la lista» (sigue en la tabla y se '
                    'puede volver a poner). <b>Eliminar</b>: marca «🗑 Eliminar» y guarda; los propios se borran y los de la app dejan '
                    'de salir (se recuperan debajo de la tabla). También puedes cambiar los valores de los de la app. Si dejas las '
                    'kcal vacías se calculan con los macros (4 · hidratos + 4 · proteína + 9 · grasa). Los días ya registrados '
                    'conservan los valores con los que se guardaron.</div>', unsafe_allow_html=True)
    st.markdown("&nbsp;", unsafe_allow_html=True)
    tabs = st.tabs(["Alimentos", "Bebidas", "Deporte", "🍱 Combinaciones"])
    with tabs[3]:
        comb_admin(C_)
    new_add, new_hide, new_del, new_unit, new_cheat, errs = {}, {}, {}, {}, {}, []
    for (t_, base, unit), tb in zip((("f", FOODS, "g"), ("b", DRINKS, "ml")), tabs):
        with tb:
            all_ = C_[t_]
            disp = {n_: (tr(n_) if n_ in base else n_) for n_ in all_}
            back = {v: k_ for k_, v in disp.items()}
            dels = C_[t_ + "_del"]
            rows = [{"En la lista": n_ not in C_[t_ + "_hide"], "Cheat": n_ in C_["cheat"][t_], "Nombre": disp[n_], "kcal": v[0], "Hidratos": v[1],
                     "Proteína": v[2], "Grasa": v[3], f"Ración ({unit})": v[4], "Unidad": tr(C_[t_ + "_unit"][n_]),
                     "Origen": (tr("App · cambiado") if tuple(v) != tuple(base[n_]) else tr("App")) if n_ in base else tr("Propio"),
                     DEL_COL: False}
                    for n_, v in sorted(all_.items(), key=lambda kv: (kv[0] not in base, disp[kv[0]].lower())) if n_ not in dels]
            df0 = pd.DataFrame(rows, columns=["En la lista", "Cheat", "Nombre", "kcal", "Hidratos", "Proteína", "Grasa", f"Ración ({unit})",
                                              "Unidad", "Origen", DEL_COL]).astype(
                {"En la lista": bool, "Cheat": bool, "Nombre": object, "kcal": float, "Hidratos": float, "Proteína": float,
                 "Grasa": float, f"Ración ({unit})": float, "Unidad": object, "Origen": object, DEL_COL: bool})
            n_act = len(C_[t_ + "_act"])
            n_own = sum(1 for n_ in all_ if n_ not in base)
            st.markdown(f'<span class="note">{fnum(n_act)} {tr("en la lista")} · {fnum(len(all_) - n_act - len(dels))} {tr("quitados")} · '
                        f'{fnum(n_own)} {tr("propios")}' + (f' · {fnum(len(dels))} {tr("eliminados")}' if dels else '')
                        + '</span>', unsafe_allow_html=True)
            num = lambda lab, mx, stp: st.column_config.NumberColumn(tr(lab), min_value=0, max_value=mx, step=stp, format="%.1f")  # noqa: E731
            off_lookup_ui(t_, C_)
            view = cat_view(df0, f"fcat_{t_}", ["Nombre", "kcal", "Hidratos", "Proteína", "Grasa", f"Ración ({unit})", "Origen"],
                            compact=compact)
            hidden = set(df0["Nombre"]) - set(view["Nombre"])
            ed = st.data_editor(view, key=cat_key(f"fcat_{t_}"), num_rows="dynamic", hide_index=True, width="stretch",
                                height=min(36 * (len(view) + 2), 640) if not compact else 420,
                                column_config={"En la lista": st.column_config.CheckboxColumn(tr("En la lista"), default=True, width="medium"),
                                               "Cheat": st.column_config.CheckboxColumn(
                                                   "🍫 Cheat", default=False, width="small",
                                                   help=tr("Fuera de la dieta habitual (dulces, bollería, fritos…): sale primero en la "
                                                           "pestaña «Cheat» del registro y se cuenta aparte.")),
                                               "Nombre": st.column_config.TextColumn(tr("Nombre"), width="large", required=True, max_chars=60),
                                               "kcal": num("kcal", 950, 1.0), "Hidratos": num("Hidratos", 100, 0.1),
                                               "Proteína": num("Proteína", 100, 0.1), "Grasa": num("Grasa", 100, 0.1),
                                               f"Ración ({unit})": num(f"Ración ({unit})", 3000, 5.0),
                                               "Unidad": st.column_config.TextColumn(
                                                   tr("Nombre de la ración"), width="small", max_chars=20,
                                                   help=tr("Cómo cuentas una ración al registrar el día: pieza, vaso, plato, rebanada… "
                                                           "La cantidad es la de la columna «Ración».")),
                                               "Origen": st.column_config.TextColumn(tr("Origen"), disabled=True, width="small"),
                                               DEL_COL: st.column_config.CheckboxColumn(
                                                   f'🗑 {tr("Eliminar")}', default=False, width="medium",
                                                   help=tr("Marca las filas que quieras eliminar y pulsa «Guardar la lista». Los propios se "
                                                           "borran; los de la app dejan de salir y se pueden recuperar debajo de la tabla."))},
                                column_order=[DEL_COL, "En la lista", "Cheat", "Nombre", "kcal", "Hidratos", "Proteína", "Grasa",
                                              f"Ración ({unit})", "Unidad", "Origen"])
            rest_ = cat_restore(dels, lambda n_: tr(n_), f"fcat_{t_}")
            add_, hide_, seen, del_, del_names = {}, set(), set(dels), set(dels) - rest_, []
            U_ = FOOD_UNITS if t_ == "f" else DRINK_UNITS
            unit_ = {n_: u_ for n_, u_ in ((C_["unit"].get(t_) or {}).items()) if n_ in dels}
            cheat_ = {n_ for n_ in C_["cheat"][t_] if n_ in dels}
            for nm in hidden:             # filas ocultas por el filtro: se quedan como estaban
                n_ = back.get(nm, nm)
                seen.add(n_)
                if n_ in C_["cheat"][t_]:
                    cheat_.add(n_)
                if n_ in (C_["add"].get(t_) or {}):
                    add_[n_] = [float(x) for x in C_["add"][t_][n_]]
                if n_ in C_[t_ + "_hide"]:
                    hide_.add(n_)
                if n_ in (C_["unit"].get(t_) or {}):
                    unit_[n_] = C_["unit"][t_][n_]
            for _, r_ in ed.iterrows():
                nm = str(r_["Nombre"]).strip() if isinstance(r_["Nombre"], str) else ""
                if not nm:
                    continue
                n_ = back.get(nm, nm)
                if n_ in seen:
                    errs.append(f'{tr("Nombre repetido")}: {nm}')
                    continue
                seen.add(n_)
                if pd.notna(r_.get(DEL_COL)) and bool(r_.get(DEL_COL)):
                    del_names.append(nm)
                    if n_ in base:
                        del_.add(n_)
                    continue
                g_ = lambda c: float(r_[c]) if pd.notna(r_[c]) else 0.0  # noqa: E731
                ch, pr, ft = g_("Hidratos"), g_("Proteína"), g_("Grasa")
                kc = g_("kcal") if pd.notna(r_["kcal"]) else round(4 * ch + 4 * pr + 9 * ft, 1)
                po = g_(f"Ración ({unit})") or 100.0
                v = (kc, ch, pr, ft, po)
                if ch + pr + ft > 100.5 and t_ == "f":
                    errs.append(f'{nm}: {tr("hidratos + proteína + grasa pasan de 100 g")}')
                if n_ not in base or tuple(float(x) for x in base[n_]) != v:
                    add_[n_] = list(v)
                u_ = str(r_["Unidad"]).strip() if isinstance(r_.get("Unidad"), str) and r_["Unidad"].strip() else ""
                d_u = U_.get(n_, UNIT_DEF)
                if u_ and u_ not in (d_u, tr(d_u)):
                    unit_[n_] = u_[:20]
                if r_["En la lista"] is not None and pd.notna(r_["En la lista"]) and not bool(r_["En la lista"]):
                    hide_.add(n_)
                if pd.notna(r_.get("Cheat")) and bool(r_.get("Cheat")):
                    cheat_.add(n_)
            hide_ |= {n_ for n_ in base if n_ not in seen}         # fila de la app borrada con la papelera = quitada
            cat_del_note(del_names)
            new_add[t_], new_hide[t_], new_del[t_] = add_, sorted(hide_), sorted(del_)
            new_unit[t_] = dict(sorted(unit_.items()))
            new_cheat[t_] = sorted(cheat_)
    with tabs[2]:
        new_add["s"], new_hide["s"], new_del["s"] = sport_admin(C_, errs, compact)
    for e in errs:
        st.warning(e)
    old_add = {t_: {k_: list(map(float, v)) for k_, v in (C_["add"].get(t_) or {}).items()} for t_ in ("f", "b")}
    old_add["s"] = {k_: [str(v[0]), str(v[1])] + [float(x) for x in v[2:12]] for k_, v in (C_["add"].get("s") or {}).items()}
    changed = (new_add != old_add or {t_: sorted(C_[t_ + "_hide"]) for t_ in ("f", "b", "s")} != new_hide
               or {t_: sorted(C_[t_ + "_del"]) for t_ in ("f", "b", "s")} != new_del
               or {t_: dict(sorted((C_["unit"].get(t_) or {}).items())) for t_ in ("f", "b")} != new_unit
               or {t_: sorted(C_["cheat"][t_]) for t_ in ("f", "b")} != new_cheat)
    b1, b2, b3 = st.columns([1, 1, 2], vertical_alignment="center")
    if b1.button("Guardar la lista" + ("" if demo else " en intervals.icu"), type="primary", key="fcat_save", width="stretch",
                 disabled=bool(errs) or not changed):
        try:
            food_cat_save(new_add, new_hide, new_del, new_unit, cheat=new_cheat)
            for k_ in [k2 for k2 in st.session_state if (str(k2).startswith(("fcat_f__", "fcat_b__", "fcat_s__")) or str(k2).endswith("_restore"))]:
                st.session_state.pop(k_, None)
            st.toast(tr("Lista guardada"))
            st.rerun()
        except Exception as e:  # noqa: BLE001
            st.error(f"{tr('No se pudo guardar')}: {e}")
    if b2.button("Volver a la lista de la app", key="fcat_reset", width="stretch",
                 disabled=not (C_["add"].get("f") or C_["add"].get("b") or C_["add"].get("s") or C_["f_hide"] or C_["b_hide"]
                               or C_["s_hide"] or C_["f_del"] or C_["b_del"] or C_["s_del"] or C_["unit"].get("f")
                               or C_["unit"].get("b")),
                 help="Borra los alimentos propios, los cambios, los quitados y los eliminados"):
        st.session_state["fcat_confirm"] = True
    if st.session_state.get("fcat_confirm"):
        b3.warning(tr("Se borrarán los alimentos propios y los cambios. ¿Seguro?"))
        c1, c2 = b3.columns(2)
        if c1.button("Sí, volver a la de la app", key="fcat_reset_ok", width="stretch"):
            try:
                food_cat_save({"f": {}, "b": {}, "s": {}}, {"f": [], "b": [], "s": []}, {"f": [], "b": [], "s": []}, {}, cheat=None)
                for k_ in [k2 for k2 in st.session_state if (str(k2).startswith(("fcat_f__", "fcat_b__", "fcat_s__")) or str(k2).endswith("_restore"))] + ["fcat_confirm"]:
                    st.session_state.pop(k_, None)
                st.rerun()
            except Exception as e:  # noqa: BLE001
                st.error(f"{tr('No se pudo guardar')}: {e}")
        if c2.button("Cancelar", key="fcat_reset_no", width="stretch"):
            st.session_state.pop("fcat_confirm", None)
            st.rerun()
    elif not compact:
        b3.markdown('<span class="note">' + ("Hay cambios sin guardar." if changed else "Sin cambios.") + " "
                    + ("Se guarda en la sesión (DEMO)." if demo else "Se guarda en intervals.icu como una nota del calendario del 01/01/2000.")
                    + "</span>", unsafe_allow_html=True)


def comb_items_txt(cb: dict) -> str:
    out = []
    for t_, DB, UN, u_ in (("f", FOOD_ALL, FOOD_UNIT, "g"), ("b", DRINK_ALL, DRINK_UNIT, "ml")):
        for n_, q in cb.get(t_, []):
            po = float(DB[n_][4]) if n_ in DB and DB[n_][4] else 0
            r_ = q / po if po else 0
            out.append(f'{tr(n_)} ' + (f'{fnum(r_, 1).replace(",0", "")} × {tr(UN.get(n_, UNIT_DEF))}'
                                       if po and abs(r_ * 2 - round(r_ * 2)) < .01 else f'{fnum(q)} {u_}'))
    return ", ".join(out)


def comb_kcal(cb: dict) -> float:
    return sum((FOOD_ALL.get(n_) or (0,))[0] * q / 100 for n_, q in cb.get("f", [])) + \
        sum((DRINK_ALL.get(n_) or (0,))[0] * q / 100 for n_, q in cb.get("b", []))


def comb_admin(C_: dict):
    """Combinaciones con nombre: un conjunto de alimentos y bebidas que se repite (ensalada, bol de fruta del desayuno…).
    Al registrar el día se añaden de una vez; también sirven para platos caseros (receta con sus ingredientes)."""
    combs = C_["comb"]
    st.markdown('<span class="note">Un nombre para un conjunto de alimentos y bebidas que se repite: <b>ensalada</b>, <b>bol de fruta '
                'del desayuno</b>, un plato casero con sus ingredientes… En el registro diario, «Añadir» la pone entera de una vez '
                '(con 2 raciones, el doble de todo). También se crea desde una comida ya apuntada: «Guardar esta comida como '
                'combinación».</span>', unsafe_allow_html=True)
    if combs:
        TB = pd.DataFrame([{"Combinación": k_, "Contenido": comb_items_txt(v), "kcal": round(comb_kcal(v))} for k_, v in sorted(combs.items())])
        html_table(TB, left={"Combinación", "Contenido"}, fmt={"kcal": lambda v: fnum(v)}, max_height=360)
    NEW = "➕ Nueva combinación"
    sel = st.selectbox("Editar", [NEW] + sorted(combs), key="comb_sel")
    cb = combs.get(sel, {}) if sel != NEW else {}
    f_lab = {("f", n_): "🍽 " + tr(n_) for n_ in FOOD_ALL if n_ in C_["f_act"] or n_ in [x[0] for x in cb.get("f", [])]}
    b_lab = {("b", n_): "🥤 " + tr(n_) for n_ in DRINK_ALL if n_ in C_["b_act"] or n_ in [x[0] for x in cb.get("b", [])]}
    labs = {**f_lab, **b_lab}
    back = {v: k_ for k_, v in labs.items()}
    rows = []
    for t_, DB in (("f", FOOD_ALL), ("b", DRINK_ALL)):
        for n_, q in cb.get(t_, []):
            po = float(DB[n_][4]) if n_ in DB and DB[n_][4] else 0
            r_ = q / po if po else 0
            whole = po and abs(r_ * 2 - round(r_ * 2)) < .01
            rows.append({"Elemento": labs.get((t_, n_), tr(n_)), "Raciones": round(r_ * 2) / 2 if whole else np.nan,
                         "Cantidad": np.nan if whole else float(q)})
    df0 = pd.DataFrame(rows, columns=["Elemento", "Raciones", "Cantidad"]).astype({"Elemento": object, "Raciones": float, "Cantidad": float})
    c1, c2 = st.columns([2, 1], vertical_alignment="bottom")
    alias = c1.text_input("Nombre de la combinación", "" if sel == NEW else sel, max_chars=40, key=f"comb_alias_{sel}",
                          placeholder="p. ej. Ensalada, Bol de fruta del desayuno, Tortilla de la abuela")
    ed = st.data_editor(df0, key=f"comb_ed_{sel}", num_rows="dynamic", hide_index=True, width="stretch",
                        column_config={"Elemento": st.column_config.SelectboxColumn("Alimento o bebida", options=list(labs.values()),
                                                                                    width="large", required=True),
                                       "Raciones": st.column_config.NumberColumn("Raciones", min_value=0, max_value=20, step=0.5,
                                                                                 format="%g", help="Vacío = 1 ración"),
                                       "Cantidad": st.column_config.NumberColumn("o g / ml", min_value=0, max_value=3000, step=5,
                                                                                 format="%g", help="Sustituye a las raciones")})
    new_cb = {"f": [], "b": []}
    for _, r_ in ed.iterrows():
        k_ = back.get(r_["Elemento"]) if isinstance(r_["Elemento"], str) else None
        if not k_:
            continue
        t_, n_ = k_
        DB = FOOD_ALL if t_ == "f" else DRINK_ALL
        q = float(r_["Cantidad"]) if pd.notna(r_["Cantidad"]) and r_["Cantidad"] else \
            (float(r_["Raciones"]) if pd.notna(r_["Raciones"]) and r_["Raciones"] else 1.0) * float(DB[n_][4])
        new_cb[t_].append([n_, round(q, 1)])
    if new_cb["f"] or new_cb["b"]:
        st.markdown(f'<span class="note">{_html.escape(comb_items_txt(new_cb))} · <b>{fnum(comb_kcal(new_cb))} kcal</b></span>',
                    unsafe_allow_html=True)
    b1, b2 = st.columns([1, 1])
    alias = (alias or "").strip()
    ok_ = bool(alias) and bool(new_cb["f"] or new_cb["b"]) and (alias == sel or alias not in combs)
    if b1.button("Guardar la combinación" + ("" if demo else " en intervals.icu"), type="primary", disabled=not ok_, key=f"comb_save_{sel}",
                 width="stretch"):
        nc = dict(combs)
        if sel != NEW and sel != alias:
            nc.pop(sel, None)
        nc[alias] = {k_: v for k_, v in new_cb.items() if v}
        try:
            food_cat_save(comb=nc)
            st.session_state["comb_sel"] = alias
            st.toast(f"Combinación guardada: {alias}")
            st.rerun()
        except Exception as e:  # noqa: BLE001
            st.error(f"{tr('No se pudo guardar')}: {e}")
    if sel != NEW and b2.button("Eliminar la combinación", key=f"comb_del_{sel}", width="stretch"):
        nc = {k_: v for k_, v in combs.items() if k_ != sel}
        try:
            food_cat_save(comb=nc)
            st.session_state.pop("comb_sel", None)
            st.rerun()
        except Exception as e:  # noqa: BLE001
            st.error(f"{tr('No se pudo guardar')}: {e}")
    if alias and alias in combs and alias != sel:
        st.warning("Ya hay una combinación con ese nombre.")


def nut_section(compact: bool = False):
    """Pestaña Nutrición: gasto y macros por semana y día (plan vs real) y alimentación por tramo en las carreras."""
    D0 = nut_defaults()
    P = dict(D0)
    if not compact:
        with st.expander(f'Tus datos · {"hombre" if D0["sex"] == "M" else "mujer"}, {D0["age"]} años, {fnum(D0["h"])} cm, '
                         f'{fnum(D0["w"], 1)} kg', key="nut_x_data"):
            c1, c2, c3, c4 = st.columns(4)
            P["sex"] = "M" if c1.selectbox("Sexo", ["Hombre", "Mujer"], index=0 if D0["sex"] == "M" else 1, key="nut_sex") == "Hombre" else "F"
            P["age"] = c2.number_input("Edad", 15, 90, int(D0["age"]), key="nut_age")
            P["h"] = c3.number_input("Estatura (cm)", 130, 220, int(round(D0["h"])), key="nut_h")
            P["w"] = c4.number_input("Peso (kg)", 40.0, 150.0, round(float(D0["w"]), 1), 0.1, key="nut_w",
                                     help=f'Por defecto: {D0["w_src"]}.')
            c5, c6, c7, c8 = st.columns(4)
            P["neat"] = c5.select_slider("Actividad diaria sin entrenar", [1.2, 1.3, 1.4, 1.5], value=1.3, key="nut_neat",
                                         format_func=lambda v: {1.2: "1,2 · sentado", 1.3: "1,3 · oficina + paseos",
                                                                1.4: "1,4 · de pie", 1.5: "1,5 · trabajo físico"}[v])
            P["prot"] = c6.slider("Proteína (g/kg/día)", 1.2, 2.4, 1.8 if D0["age"] >= 40 else 1.6, 0.1, key="nut_prot",
                                  help="1,6–2,0 g/kg en deportistas de resistencia; a partir de los 40 años, mejor la parte alta.")
            P["fat"] = c7.slider("Grasa (% del gasto)", 20, 35, 28, 1, key="nut_fat", help="Con un mínimo de 0,8 g/kg.")
            P["use_bf"] = c8.toggle("Basal con % de grasa", value=bool(D0["bf"]), disabled=not D0["bf"], key="nut_bf",
                                    help=(f'Katch-McArdle con {fnum(D0["bf"], 1)} % de grasa (media de Salud)' if D0["bf"]
                                          else "Sin % de grasa en Salud: Mifflin-St Jeor"))
    else:
        P.update(neat=1.3, prot=1.8 if D0["age"] >= 40 else 1.6, fat=28, use_bf=bool(D0["bf"]))
    bmr = nut_bmr(P)
    base = bmr * P["neat"]
    k = nut_calib(P)
    try:
        S = summary_plan()
        W = S.get("W") or []
    except Exception:  # noqa: BLE001
        S, W = {}, []
    ci = next((i for i, w_ in enumerate(W) if w_["frm"] <= today <= w_["to"]), -1)
    wi = ci if ci >= 0 else (0 if W and today < W[0]["frm"] else -1)

    # Hoy
    d_today = all_df[all_df["date"] == today] if len(all_df) else all_df
    ex_today = nut_ex_real(d_today, P, k) if len(d_today) else 0.0
    plan_today = None
    if wi >= 0 and W[wi]["frm"] <= today <= W[wi]["to"]:
        plan_today = nut_week_plan(W[wi], P, k)["days"][(today - W[wi]["frm"]).days]
    ex_t = max(ex_today, plan_today["kcal"] if plan_today else 0.0)
    M_t = nut_macros(base + ex_t, P)
    lo, hi, lab = nut_ch_band(max(sum(d_today["hours"]) if len(d_today) else 0.0, (plan_today or {}).get("min", 0) / 60))
    if not compact:
        st.subheader("Nutrición · gasto y macros según el esfuerzo")
        st.markdown(f'<div class="note">Basal {fnum(bmr)} kcal ({"Katch-McArdle, con tu % de grasa" if P.get("use_bf") and P.get("bf") else "Mifflin-St Jeor: peso, estatura, edad y sexo"}) '
                    f'× {fnum(P["neat"], 1)} de actividad diaria = <b>{fnum(base)} kcal</b> sin entrenar. El ejercicio suma su gasto neto: '
                    f'el del reloj si lo da y, si no, km-esfuerzo × peso (fuerza y otras por MET). Ajuste personal según tu reloj: '
                    f'× {fnum(k, 2)}. Orientativo: no sustituye a un dietista-nutricionista.</div>', unsafe_allow_html=True)
    cards([("Hoy · gasto", GOLD, fnum(M_t["kcal"]), " kcal",
            [f'basal y día {fnum(base)} + ejercicio {fnum(ex_t)}',
             ("hecho: " + ", ".join(d_today["name"].fillna("").astype(str).str[:28].tolist())) if len(d_today) else
             ("plan: " + ", ".join(plan_today["txt"])) if plan_today and plan_today["txt"] else "día de descanso"]),
           ("Hidratos", ORANGE, fnum(M_t["ch"]), " g", [f'{fnum(M_t["chkg"], 1)} g/kg · guía {fnum(lo)}–{fnum(hi)} g/kg ({lab})']),
           ("Proteína", TEAL, fnum(M_t["p"]), " g", [f'{fnum(P["prot"], 1)} g/kg · 4–5 tomas de {fnum(0.4 * P["w"])} g']),
           ("Grasa", VIOLET, fnum(M_t["f"]), " g", [f'{fnum(9 * M_t["f"] / max(M_t["kcal"], 1) * 100)} % del gasto'])])

    # Registro diario de alimentación, cruzado con el gasto real y el del plan
    food_log(P, base, k, W, compact)

    # Esta semana, día a día
    if wi >= 0:
        w_ = W[wi]
        wp = nut_week_plan(w_, P, k)
        rows = []
        for i in range(7):
            d_ = w_["frm"] + dt.timedelta(days=i)
            dd_ = all_df[all_df["date"] == d_] if len(all_df) else all_df
            pl = wp["days"][i]
            real = nut_ex_real(dd_, P, k) if len(dd_) and d_ <= today else None
            Mp = nut_macros(base + pl["kcal"], P)
            Mr = nut_macros(base + real, P) if real is not None else None
            mins = max(pl["min"], float(dd_["hours"].sum()) * 60 if len(dd_) else 0.0)
            rows.append({"Día": f'{DIAS_L[i][:3]} {d_:%d/%m}', "Plan": " · ".join(pl["txt"]) or "descanso",
                         "Hecho": (", ".join(dd_["name"].fillna("").astype(str).str[:24]) or "—") if d_ <= today else "",
                         "Plan|kcal": Mp["kcal"], "Plan|CH": Mp["ch"], "Plan|P": Mp["p"], "Plan|G": Mp["f"],
                         "Real|kcal": Mr["kcal"] if Mr else np.nan, "Real|CH": Mr["ch"] if Mr else np.nan,
                         "Durante": nut_intra(max(pl["min"], mins)) if mins > 0 else "—"})
        DT = pd.DataFrame(rows)
        if compact:
            st.markdown(_rows([(f'{r_["Día"]} · {fnum(r_["Plan|kcal"])} kcal',
                                f'CH {fnum(r_["Plan|CH"])} g · P {fnum(r_["Plan|P"])} g · G {fnum(r_["Plan|G"])} g'
                                + (f' · durante {r_["Durante"]}' if r_["Durante"] not in ("—", "agua") else ""))
                               for _, r_ in DT.iterrows()]), unsafe_allow_html=True)
        else:
            st.subheader(("Esta semana" if ci >= 0 else "Primera semana del plan") + f' · {w_["ph"]} · día a día')
            f0 = lambda v: fnum(v) if pd.notna(v) else "—"  # noqa: E731
            html_table(DT, left={"Día", "Plan", "Hecho", "Durante"},
                       fmt={c: f0 for c in DT.columns if "|" in c},
                       groups=[("", 3, ""), ("Plan (g/día)", 4, "g"), ("Real", 2, "g"), ("", 1, "g")],
                       group_start={"Plan|kcal", "Real|kcal", "Durante"},
                       sub={"kcal": "kcal", "CH": "Hidratos", "P": "Proteína", "G": "Grasa"},
                       row_classes=["cur" if w_["frm"] + dt.timedelta(days=i) == today else "" for i in range(7)])
            st.markdown('<span class="note">Rodajes y tirada larga sin día fijo en el plan: reparto orientativo 60 % sábado y 40 % '
                        'domingo (horas de carrera de la semana menos la calidad). «Durante» = hidratos por hora en la sesión '
                        'según su duración. Real = basal y día + lo que has hecho.</span>', unsafe_allow_html=True)

    # Semana a semana: plan vs real
    def _ckg(v, lo_, hi_):
        c_ = ORANGE if v < lo_ else GLACIER if v > hi_ else GREEN
        return f'<span style="color:{c_};font-weight:600">{fnum(v, 1)}</span>'

    if W and not compact:
        st.subheader("Semana a semana · media diaria, plan vs real")
        rows = []
        for w_ in W:
            wp = nut_week_plan(w_, P, k)
            Mp = nut_macros(base + wp["ex"] / 7, P)
            lo_, hi_, _l = nut_ch_band(wp["h"] / 7)
            Mr, lr, hr_ = None, lo_, hi_
            if w_["frm"] <= today:
                n_d = min(7, (today - w_["frm"]).days + 1)
                dd_ = all_df[(all_df["date"] >= w_["frm"]) & (all_df["date"] <= min(today, w_["to"]))] if len(all_df) else all_df
                Mr = nut_macros(base + (nut_ex_real(dd_, P, k) if len(dd_) else 0.0) / n_d, P)
                lr, hr_, _l = nut_ch_band((float(dd_["hours"].sum()) if len(dd_) else 0.0) / n_d)
            rows.append({"Semana": f'{w_["frm"]:%d/%m}', "Fase": w_["ph"] + {"r": " · descarga", "t": " · taper", "R": " · carrera"}.get(w_["k"], ""),
                         "Plan|kcal": Mp["kcal"], "Plan|CH": Mp["ch"], "Plan|CHkg": _ckg(Mp["chkg"], lo_, hi_), "Plan|P": Mp["p"], "Plan|G": Mp["f"],
                         "Plan|Guía": f"{fnum(lo_)}–{fnum(hi_)}",
                         "Real|kcal": Mr["kcal"] if Mr else np.nan, "Real|CH": Mr["ch"] if Mr else np.nan,
                         "Real|CHkg": _ckg(Mr["chkg"], lr, hr_) if Mr else "—"})
        WT = pd.DataFrame(rows)
        f0 = lambda v: fnum(v) if pd.notna(v) else "—"  # noqa: E731
        html_table(WT, left={"Semana", "Fase"},
                   fmt={"Plan|kcal": f0, "Plan|CH": f0, "Plan|P": f0, "Plan|G": f0, "Real|kcal": f0, "Real|CH": f0},
                   groups=[("", 2, ""), ("Plan · por día", 6, "g"), ("Real · por día", 3, "g")],
                   group_start={"Plan|kcal", "Real|kcal"},
                   sub={"kcal": "kcal", "CH": "Hidratos g", "CHkg": "g/kg", "P": "Proteína g", "G": "Grasa g", "Guía": "guía g/kg"},
                   row_classes=["cur" if w_["frm"] <= today <= w_["to"] else "" for w_ in W], max_height=520)
        st.markdown('<span class="note">Plan: gasto del ejercicio previsto (fuerza, calidad, cinta y carrera por fuera con los km y '
                    'el D+ objetivo). Real: media de los días ya pasados de la semana. Guía de hidratos (ACSM / COI) según las '
                    'horas de entrenamiento al día: g/kg en '
                    f'<span style="color:{GREEN}">verde</span> dentro de la guía, en <span style="color:{ORANGE}">naranja</span> por debajo (baja la grasa o come algo más en los días de más '
                    f'carga) y en <span style="color:{GLACIER}">azul</span> por encima.</span>', unsafe_allow_html=True)

    # Carreras: alimentación por tramo
    try:
        C_, res = race_results_default()
    except Exception as e:  # noqa: BLE001
        st.info(f"No se pudo calcular la alimentación en carrera: {e}")
        return
    if not res:
        st.info(races_missing_msg())
        return
    if not compact:
        st.subheader("Carreras 2027 · alimentación por tramo")
        r1, r2 = st.columns([3, 2])
        _rn = [RACES[x]["name"] for x in res]
        pick = r1.segmented_control("Carrera nutrición", _rn, default=_rn[-1],
                                    key="nut_race", label_visibility="collapsed") or _rn[-1]
        sc_l = r2.segmented_control("Escenario nutrición", ["Hoy", "Con el plan"], default="Con el plan", key="nut_sc",
                                    label_visibility="collapsed") or "Con el plan"
        rk = next(x for x in res if RACES[x]["name"] == pick)
        x_ = res[rk]
        sc = "plan" if sc_l == "Con el plan" else "now"
        tot_h = x_[sc]["total"] / 3600
        q1, q2, q3 = st.columns(3)
        rate = q1.slider("Hidratos por hora (g/h)", 30, 100, 60 if tot_h < 10 else 70, 5, key="nut_rate_" + rk,
                         help="60 g/h con glucosa sola; hasta 90 g/h con mezcla glucosa:fructosa y el intestino entrenado.")
        fluid = q2.slider("Líquido por hora (ml/h)", 300, 900, NUT_FLD_DEF[rk], 50, key="nut_fl_" + rk,
                          help="Ajústalo con tu tasa de sudor: pésate antes y después de una salida larga con calor parecido.")
        na = q3.slider("Sodio (mg por litro)", 300, 1200, 600, 50, key="nut_na_" + rk)
        R_ = nut_race_tramos(x_, sc, P, k, rate, fluid, na)
        tot = R_.iloc[-1]
        cards([("Gasto en carrera", RED, fnum(tot["Gasto"]), " kcal", [f'{x_["R"]["short"]} · {_dur(x_[sc]["total"])} h ({sc_l.lower()})']),
               ("Ingesta prevista", GOLD, fnum(tot["Ingesta"]), " kcal",
                [f'{fnum(tot["CH"])} g de hidratos ≈ {fnum(tot["Geles"])} geles de 25 g', f'cubre el {fnum(100 * tot["Ingesta"] / max(tot["Gasto"], 1))} % del gasto']),
               ("Líquido y sodio", GLACIER, fnum(tot["Líquido"] / 1000, 1), " l", [f'{fnum(tot["Sodio"])} mg de sodio']),
               ("Los días antes", TEAL, fnum(9 * P["w"]), " g/día", ["hidratos 36–48 h antes (8–10 g/kg)",
                                                                       f'desayuno 3 h antes: {fnum(2 * P["w"])} g de hidratos'])])
        f0 = lambda v: fnum(v) if pd.notna(v) else "—"  # noqa: E731
        html_table(R_, left={"Tramo"}, total_last=True,
                   fmt={"Km": lambda v: fnum(v, 1), "D+": f0, "D−": f0, "Gasto": f0, "CH": f0, "Prot.": f0, "Grasa": f0,
                        "Ingesta": f0, "Líquido": f0, "Sodio": f0, "Geles": lambda v: fnum(v, 1)},
                   group_start={"Gasto", "CH", "Líquido"})
        lg_ = [r_ for _, r_ in R_.iloc[:-1].iterrows() if _hhmm_min(r_["Tiempo"]) is not None and _hhmm_min(r_["Tiempo"]) >= 180]
        if lg_:
            st.markdown('<div class="reading" style="--c:' + ORANGE + '">Tramos de más de 3 h sin avituallamiento: '
                        + "; ".join(f'<b>{_html.escape(r_["Tramo"])}</b> ({r_["Tiempo"]} h: {fnum(r_["CH"])} g de hidratos y '
                                    f'{fnum(r_["Líquido"] / 1000, 1)} l)' for r_ in lg_)
                        + '. Si no hay puntos de agua intermedios, sal con la comida del tramo y repón líquido en fuentes o '
                        'refugios.</div>', unsafe_allow_html=True)
        st.markdown('<span class="note">Tramos entre avituallamientos con los tiempos de la sección Carreras 2027. Gasto = '
                    'km-esfuerzo × peso (con tu ajuste) + basal del tiempo en carrera. Hidratos (g), proteína a partir de la 3.ª '
                    'hora en carreras de más de 8 h y algo de grasa (comida real) a partir de la 6.ª en las de más de 12 h; líquido '
                    'en ml y sodio en mg. Es normal no cubrir todo el gasto: el resto sale de las reservas. Al acabar: '
                    f'{fnum(1.1 * P["w"])} g de hidratos y {fnum(0.3 * P["w"])} g de proteína en la primera hora. Prueba la '
                    'estrategia en las tiradas largas antes de la carrera.</span>', unsafe_allow_html=True)
    else:
        for rk, x_ in res.items():
            R_ = nut_race_tramos(x_, "plan", P, k, 60 if x_["plan"]["total"] < 36000 else 70, NUT_FLD_DEF[rk], 600)
            st.markdown(f'<div class="eyebrow">{_html.escape(x_["R"]["name"])} · con el plan</div>' + _rows(
                [(f'{_html.escape(r_["Tramo"])} · {r_["Tiempo"]} h',
                  f'{fnum(r_["CH"])} g CH ({fnum(r_["Geles"], 1)} geles) · {fnum(r_["Líquido"])} ml · {fnum(r_["Sodio"])} mg Na'
                  + (f' · {fnum(r_["Prot."])} g prot.' if r_["Prot."] > 0 else "") + f' · gasto {fnum(r_["Gasto"])} kcal')
                 for _, r_ in R_.iterrows()]), unsafe_allow_html=True)


