def _kind_of(sport: str) -> str:
    return {"TrailRun": "trail", "Run": "carrera", "VirtualRun": "cinta", "Hike": "caminata", "Walk": "caminata"}.get(
        sport, "fuerza" if sport in GIM else sport.lower())


_KIND_TXT = {"ca": {"trail": "trail", "carrera": "cursa", "cinta": "cinta", "caminata": "caminada", "fuerza": "força"},
             "en": {"trail": "trail", "carrera": "run", "cinta": "treadmill", "caminata": "hike", "fuerza": "strength"}}


def _kind_txt(sport: str) -> str:
    k_ = _kind_of(sport)
    return _KIND_TXT.get(LANG, {}).get(k_, k_)


def _hms_short(sec: float) -> str:
    sec = int(round(sec or 0))
    return f"{sec // 3600}:{sec % 3600 // 60:02d}" if sec >= 3600 else f"{sec // 60} min"


def _act_line(r_) -> str:
    bits = []
    if r_["km"] and r_["km"] > 0.2:
        bits.append(f'{fnum(r_["km"], 1)} km')
    bits.append(_hms_short(r_["secs"]))
    if r_["dp"] and r_["dp"] >= 20 and r_["sport"] not in CINTA:
        bits.append(f'{fnum(r_["dp"])} m D+')
    if pd.notna(r_["load"]) and r_["load"]:
        bits.append(f'<span class="ld">{tr("carga")} {fnum(r_["load"])}</span>')
    return " · ".join(bits).replace(' · <span class="ld">', '<span class="ld"> · ')


def _hoy_data() -> dict:
    S = summary_plan()
    D = dict(S=S, ok=bool(S.get("ok")), ci=S.get("ci", -1) if S.get("ok") else -1)
    if D["ci"] >= 0:
        ci = D["ci"]
        w, a = S["W"][ci], S["A"][ci]
        todo = week_todo(S, ci)
        rem = dict(load=max(0.0, w["load"] - a["load"]), h=max(0.0, w["h"] - a["h"]), dp=max(0.0, w["dp"] - a["dp"]))
        pct = dict(load=a["load"] / w["load"] * 100 if w["load"] else 100, h=a["h"] / w["h"] * 100 if w["h"] else 100,
                   dp=a["dp"] / w["dp"] * 100 if w["dp"] else 100)
        D.update(w=w, a=a, todo=todo, rem=rem, pct=pct)
        # titular: lo que más falta
        lab_ = {"load": "carga", "h": "horas", "dp": "desnivel"}
        worst = min(pct, key=pct.get)
        if min(pct.values()) >= 100:
            head = "Semana cumplida: el resto, suave o descanso"
        elif worst == "dp" and pct["dp"] < pct["load"] - 15:
            head = f'Te falta sobre todo desnivel: {fnum(rem["dp"])} m D+ para cerrar la semana'
        elif worst == "load":
            head = f'Te faltan {fnum(rem["load"])} de carga para cerrar la semana'
        else:
            head = f'Te falta {lab_[worst]} para cerrar la semana: {fnum(rem["h"], 1)} h'
        D["head"] = head
        pend = [t for t in todo if t["st"] == "pendiente"]
        D["pend"] = pend
    fnow = fit.iloc[-1] if len(fit) else None
    D["fit"] = fnow
    if fnow is not None:
        D["tsb_z"] = zone_tsb(fnow["tsb"])
    races = S.get("races") if S.get("ok") else None
    if not races:
        races = [dict(name=r["name"], d=_d(r["date"]), c=GOLD) for r in RACES.values()]
    D["races"] = [dict(r, dd=(r["d"] - today).days) for r in races if r.get("d")]
    D["recent"] = all_df.sort_values("ts", ascending=False).head(6) if len(all_df) else all_df
    return D


def _week_days(D: dict) -> list[dict]:
    """Los 7 días de la semana del plan con sus sesiones, su estado y las actividades del día."""
    w = D["w"]
    out = []
    for k_ in range(7):
        d_ = w["frm"] + dt.timedelta(days=k_)
        ts_ = [t for t in D["todo"] if t["date"] == d_]
        acts = all_df[all_df["date"] == d_].sort_values("ts") if len(all_df) else all_df
        if ts_:
            sts = [t["st"] for t in ts_]
            st_ = ("no hecha" if "no hecha" in sts else "pendiente" if "pendiente" in sts else
                   "hecha otro día" if "hecha otro día" in sts else "hecha")
        else:
            st_ = "libre" if not len(acts) else "extra"
        if d_ == today and st_ in ("pendiente", "libre"):
            st_ = "hoy"
        out.append(dict(d=d_, ses=ts_, st=st_, acts=acts))
    return out


_ST_ICO = {"hecha": "✓", "hecha otro día": "↷", "pendiente": "○", "no hecha": "✗", "libre": "·", "extra": "+", "hoy": "●"}


def _st_col(st_: str) -> str:
    return {"hecha": GREEN, "hecha otro día": GOLD, "pendiente": MUTED, "no hecha": RED, "libre": MUTED, "extra": GLACIER,
            "hoy": INK}.get(st_, MUTED)


def _bar_html(p: float, c: str, h: int = 8) -> str:
    return (f'<div style="height:{h}px;border-radius:{h // 2}px;background:{LINE};overflow:hidden">'
            f'<div style="height:100%;width:{min(100, max(0, p)):.0f}%;background:{c};border-radius:{h // 2}px"></div></div>')


def _pct_col(p: float) -> str:
    return GREEN if p >= 60 else (GOLD if p >= 30 else ORANGE)


def _phase_col(w: dict) -> str:
    if w["k"] == "R":
        return RED
    if w["k"] in ("r",) or "Recuper" in w["ph"] or "Descarga" in w["ph"]:
        return ZERO
    if w["k"] == "t" or "Taper" in w["ph"]:
        return PREV
    if "Pico" in w["ph"]:
        return _mix(GLACIER, "#ffffff", .35) if not LIGHT else GLACIER
    if "Espec" in w["ph"]:
        return GLACIER
    if "Base 2" in w["ph"]:
        return _mix(GLACIER, BG, .35)
    return _mix(GLACIER, BG, .55)


def _plan_profile_fig(D: dict, h: int, sel: int | None = None, mini: bool = False):
    S = D["S"]
    W = S["W"]
    x = list(range(1, len(W) + 1))
    cols = []
    for i, w in enumerate(W):
        c_ = _phase_col(w)
        if i == D["ci"]:
            c_ = GOLD
        cols.append(c_)
    fig = go.Figure()
    fig.add_bar(x=x, y=[w["load"] for w in W], marker=dict(color=cols, line=dict(width=[3 if (sel is not None and i == sel) else 0
                                                                                        for i in range(len(W))], color=INK)),
                customdata=np.stack([[w["ph"] for w in W], [f'{w["frm"]:%d/%m}' for w in W], [fnum(w["h"], 1) for w in W],
                                     [fnum(w["dp"]) for w in W]], axis=-1),
                hovertemplate=tr("Semana") + " %{x} · %{customdata[1]}<br>%{customdata[0]}<br>" + tr("carga")
                + " %{y:.0f} · %{customdata[2]} h · %{customdata[3]} m D+<extra></extra>", showlegend=False)
    ymax = max(w["load"] for w in W)
    for r in D["races"]:
        wi = next((i for i, w in enumerate(W) if w["frm"] <= r["d"] <= w["to"]), None)
        if wi is None:
            continue
        if mini:
            fig.add_annotation(x=wi + 1, y=W[wi]["load"], text="▲", showarrow=False, yshift=12, font=dict(color=r.get("c", RED), size=12))
        else:
            fig.add_shape(type="line", x0=wi + 1, x1=wi + 1, y0=W[wi]["load"], y1=ymax * 1.12, line=dict(color=r.get("c", RED), width=1, dash="dot"))
            fig.add_annotation(x=wi + 1, y=ymax * 1.12, text=f'▲ {r.get("short") or r["name"]}', showarrow=False, yshift=10,
                               xanchor="right" if wi > len(W) * .8 else "center", font=dict(color=r.get("c", RED), size=12))
    if D["ci"] >= 0 and not mini:
        fig.add_annotation(x=D["ci"] + 1, y=W[D["ci"]]["load"], text=tr("estás aquí"), showarrow=True, arrowhead=0, ay=-34,
                           arrowcolor=GOLD, font=dict(color=ACC_ON, size=11), bgcolor=GOLD, borderpad=3)
    fig.update_xaxes(tickvals=[i + 1 for i, w in enumerate(W) if w["frm"].day <= 7],
                     ticktext=[MES[w["frm"].month - 1] for w in W if w["frm"].day <= 7], showgrid=False)
    fig.update_yaxes(showticklabels=not mini, showgrid=not mini, range=[0, ymax * (1.05 if mini else 1.25)])
    plot_layout(fig, h, legend=False)
    fig.update_layout(bargap=.18, margin=dict(l=4 if mini else 10, r=4, t=26 if not mini else 18, b=4))
    return fig


def _races_html(D: dict, big: bool = False) -> str:
    out = []
    for r in D["races"]:
        dd = r["dd"]
        val = f'{fnum(dd)} {tr("días")}' if dd >= 0 else "✓"
        out.append(f'<div class="hy-race"><span class="k">{r["d"]:%d/%m/%y}</span><span class="n">{_html.escape(r["name"])}</span>'
                   f'<span class="v" style="color:{r.get("c", GOLD)}">{val}</span></div>')
    return "".join(out)


