                         f'<span class="m">· {_html.escape(W[i]["ph"])}</span></span><span>{tr("carga")} {fnum(W[i]["load"])} · '
                         f'{fnum(W[i]["h"], 1)} h · {fnum(W[i]["dp"])} m D+</span></div>'
