def home_perfil(D: dict | None = None, hero: bool = True):
    if D is None:
        D = _hoy_data()
        st.markdown(_home_css(), unsafe_allow_html=True)
    if not D["ok"]:
        st.info("No hay objetivos semanales en el calendario de intervals.icu.")
        return
    S, W = D["S"], D["S"]["W"]
    if hero:
        st.markdown(f'<div class="hy-hero"><div class="e">{_html.escape(S.get("title", ""))} · {len(W)} {tr("semanas")} · '
                    f'{W[0]["frm"]:%d/%m/%y} – {W[-1]["to"]:%d/%m/%y}</div><h1>{tr("La temporada como una montaña")}</h1></div>',
                    unsafe_allow_html=True)
    else:
        st.subheader("La temporada como una montaña")
        st.markdown(f'<span class="note">{_html.escape(S.get("title", ""))} · {len(W)} {tr("semanas")} · '
                    f'{W[0]["frm"]:%d/%m/%y} – {W[-1]["to"]:%d/%m/%y}</span>', unsafe_allow_html=True)
    st.markdown(f'<span class="note">{tr("Cada columna es una semana del plan y su altura, la carga objetivo. Pulsa una semana para ver qué toca y cómo fue.")}</span>',
                unsafe_allow_html=True)
    if "hy_wsel" not in st.session_state:
        st.session_state["hy_wsel"] = max(0, D["ci"])
    sel = int(st.session_state["hy_wsel"])
    ev = st.plotly_chart(_plan_profile_fig(D, 300, sel=sel), width="stretch", theme=None, on_select="rerun",
                         selection_mode="points", key="hy_prof")
    try:
        pts = ev.selection.points if ev else []
    except Exception:  # noqa: BLE001
        pts = []
    if pts:
        nsel = int(pts[0].get("x", sel + 1)) - 1
        if nsel != st.session_state.get("hy_prof_last"):
            st.session_state["hy_prof_last"] = nsel
            st.session_state["hy_wsel"] = nsel
            st.rerun()
    # franja de fases
    groups = []
    for i, w in enumerate(W):
        k_ = w["ph"].split(" · ")[0]
        if groups and groups[-1][0] == k_:
            groups[-1][1] += 1
        else:
            groups.append([k_, 1, _phase_col(w)])
    st.markdown('<div style="display:flex;gap:3px;margin:-6px 0 14px">' + "".join(
        f'<div title="{_html.escape(g[0])}" style="flex:{g[1]} 0 0;min-width:0;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;'
        f'font-size:12px;font-weight:600;color:{ACC_ON if g[2] == GOLD else INK};background:{rgba(g[2], .55)};padding:4px 6px;border-radius:4px">'
        f'{_html.escape(g[0]) if g[1] >= 3 else ""}</div>' for g in groups) + "</div>", unsafe_allow_html=True)
    nav1, nav2, nav3 = st.columns([1, 4, 1], vertical_alignment="center")
    if nav1.button("← " + tr("Anterior"), key="hy_prev", disabled=sel <= 0, width="stretch"):
        st.session_state["hy_wsel"] = sel - 1
        st.rerun()
    nav2.markdown(f'<div style="text-align:center" class="note">{tr("Semana")} {sel + 1} · {W[sel]["frm"]:%d/%m} – {W[sel]["to"]:%d/%m}'
                  + (f' · <b style="color:{GOLD}">{tr("en curso")}</b>' if sel == D["ci"] else "") + "</div>", unsafe_allow_html=True)
    if nav3.button(tr("Siguiente") + " →", key="hy_next", disabled=sel >= len(W) - 1, width="stretch"):
        st.session_state["hy_wsel"] = sel + 1
        st.rerun()
    w, a = W[sel], S["A"][sel]
    fut = w["frm"] > today
    rows = []
    for k, lab, u, dc in (("load", tr("Carga"), "", 0), ("h", tr("Horas"), " h", 1), ("dp", tr("D+ por fuera"), " m", 0)):
        if fut:
            rows.append(f'<div><div class="hy-lab"><span>{lab}</span><b>{tr("objetivo")} {fnum(w[k], dc)}{u}</b></div>{_bar_html(100, ZERO)}</div>')
        else:
            p_ = a[k] / w[k] * 100 if w[k] else 0
            rows.append(f'<div><div class="hy-lab"><span>{lab}</span><b>{fnum(a[k], dc)} / {fnum(w[k], dc)}{u} · {fnum(p_)} %</b></div>'
                        f'{_bar_html(p_, _pct_col(p_))}</div>')
    note_ = (tr("Semana futura: objetivos del plan en intervals.icu.") if fut else tr("En curso.") if sel == D["ci"] else tr("Semana terminada."))
    c_week = (f'<div class="hy-card"><div class="pf-wk"><h3>{tr("Semana")} {sel + 1} {tr("de")} {len(W)}</h3>'
              f'<span class="note">{w["frm"]:%d/%m} – {w["to"]:%d/%m}</span></div><span style="color:{GOLD};font-weight:600;font-size:14px">'
              f'{_html.escape(w["ph"])}</span>{"".join(rows)}<span class="note">{note_}</span></div>')
    if fut:
        ses_rows = [(d_, sess(sid), "pendiente", None) for d_, sid in w["ses"]]
    else:
        ses_rows = [(t["date"], t["s"], t["st"], t) for t in week_todo(S, sel)]
    ses_html = "".join(f'<div class="pf-ses"><span class="k">{DIAS[d_.weekday()]} {d_.day}</span>'
                       f'<span class="i" style="color:{_st_col(st_)}">{_ST_ICO[st_]}</span>'
                       f'<span><b>{_html.escape(s_["name"])}</b> <span style="color:{MUTED}">· {KIND_L[s_["kind"]].lower()} · '
                       f'{(tr("hecha el") + " " + DIAS[t["act"]["date"].weekday()].lower()) if st_ == "hecha otro día" else tr(st_)}</span></span></div>'
                       for d_, s_, st_, t in ses_rows)
    c_ses = (f'<div class="hy-card" style="gap:4px"><h3 style="margin-bottom:6px !important">{tr("Sesiones")} · {tr("semana")} {sel + 1}</h3>'
             f'{ses_html or "<span class=note>—</span>"}</div>')
    f_ = D["fit"]
    forma_txt = (f'<div class="hy-row" style="font-size:14px;color:{MUTED}"><span>{tr("Forma")} <b style="color:{INK}">{fnum(f_["ctl"])}</b></span>'
                 f'<span>{tr("Fatiga")} <b style="color:{INK}">{fnum(f_["atl"])}</b></span><span>Balance <b style="color:{INK}">'
                 f'{("+" if f_["tsb"] > 0 else "") + fnum(f_["tsb"])}</b> {D["tsb_z"][0].lower()}</span></div>') if f_ is not None else ""
    c_race = f'<div class="hy-card"><h3>{tr("Hacia las carreras")}</h3>{_races_html(D, True)}{forma_txt}</div>'
    st.markdown('<div class="hy-grid">' + c_week + c_ses + c_race + "</div>", unsafe_allow_html=True)
    if len(D["recent"]):
        st.markdown(f'<div class="hy-card" style="gap:0"><h3 style="margin-bottom:8px !important">{tr("Últimas actividades")}</h3>'
                    f'{_recent_html(D)}</div>', unsafe_allow_html=True)


