    cards([(lab, col, fnum(LW[k], d), u, [delta_html(LW[k], PW[k], "sem. anterior"), delta_html(LW[k], AVG[k], "media 8 sem")]
            + ([dp_split_line(LW)] if k == "dp" and dp_split_line(LW) else []))
           for k, lab, col, u, d in WKM[:4]])
    cards([(lab, col, fnum(LW[k], d), u, [delta_html(LW[k], PW[k], "sem. anterior"), delta_html(LW[k], AVG[k], "media 8 sem")])
           for k, lab, col, u, d in WKM[4:]])

    c1, c2 = st.columns([3, 2])
