# ─────────────────────────── Nombrar actividades: zona, tipo y contador ───────────────────────────
# «Trail run · La Mola per Pi Tort #3», «Asfalto · Volta al parc #12», «Cinta #42». Las salidas por fuera se agrupan por
# recorrido (punto de salida, punto más alejado, punto más alto y km); cada grupo es una zona con un nombre fijo que se guarda
# en una nota de intervals.icu y se reconoce en las salidas nuevas. El contador cuenta desde el 1 de enero de 2026.
ZONES_NAME = "Llibreta D+ · zonas de recorrido"
NAME_FROM = dt.date(2026, 1, 1)
NAME_TYPES = {"trail": "Trail run", "asfalto": "Asfalto"}
_RE_AUTO = re.compile(r"^(Trail run|Asfalto|Cinta)\b.*#\d+\s*$")


def _hav(a, b) -> float:
    """Distancia en metros entre dos puntos (lat, lng)."""
    la1, lo1, la2, lo2 = map(math.radians, (a[0], a[1], b[0], b[1]))
    h = math.sin((la2 - la1) / 2) ** 2 + math.cos(la1) * math.cos(la2) * math.sin((lo2 - lo1) / 2) ** 2
    return 2 * 6371000 * math.asin(min(1.0, math.sqrt(h)))


def route_sig_df(d_):
    """Firma del recorrido: salida, punto más alejado de la salida, punto más alto y llegada (lat, lng)."""
    if d_ is None or not len(d_) or "lat" not in d_ or d_["lat"].notna().sum() < 20:
        return None
    g = d_.dropna(subset=["lat", "lng"])
    g = g[(g["lat"].abs() > 0.01) & (g["lng"].abs() > 0.01)]
    if len(g) < 20:
        return None
    st_ = (float(g["lat"].iloc[0]), float(g["lng"].iloc[0]))
    en_ = (float(g["lat"].iloc[-1]), float(g["lng"].iloc[-1]))
    step = max(1, len(g) // 400)
    gs = g.iloc[::step]
    far = max(((float(a), float(b)) for a, b in zip(gs["lat"], gs["lng"])), key=lambda q: _hav(st_, q))
    if g["alt"].notna().any():
        r_ = g.loc[g["alt"].idxmax()]
        top = (float(r_["lat"]), float(r_["lng"]))
    else:
        top = far
    return dict(s=st_, f=far, t=top, e=en_)


@st.cache_data(ttl=7 * 86400, show_spinner=False)
def route_sig(key: str, act_id: str):
    try:
        d_ = streams_to_df(fetch_streams(key, act_id))
    except Exception:  # noqa: BLE001
        return None
    return route_sig_df(d_)


def climbs_of(d_, min_gain: float = 50.0, max_dip: float = 15.0) -> list[dict]:
    """Subidas de una actividad (cada 25 m, se permiten bajadas de hasta max_dip m dentro de una subida)."""
    g = d_.dropna(subset=["dist", "alt_s"])
    if len(g) < 30:
        return []
    xs = np.arange(0, float(g["dist"].iloc[-1]), 25.0)
    al = np.interp(xs, g["dist"].to_numpy(), g["alt_s"].to_numpy())
    out, lo_i, hi_i = [], 0, 0

    def _rec(lo, hi):
        gain = al[hi] - al[lo]
        if gain >= min_gain and hi > lo:
            L = xs[hi] - xs[lo]
            out.append(dict(km0=xs[lo] / 1000, km1=xs[hi] / 1000, a0=al[lo], a1=al[hi], gain=gain, grade=100 * gain / max(L, 1)))
    for i in range(1, len(al)):
        if al[i] >= al[hi_i]:
            hi_i = i
        elif al[hi_i] - al[i] > max_dip:          # la subida terminó en hi_i
            _rec(lo_i, hi_i)
            lo_i = hi_i = i
        if al[i] < al[lo_i]:
            lo_i = hi_i = i
    _rec(lo_i, hi_i)
    return out


def _same_route(a: dict, b: dict) -> bool:
    """Mismo recorrido: salida, punto más alejado y punto más alto cerca, y km parecidos."""
    if abs(a["km"] - b["km"]) > max(0.6, 0.08 * max(a["km"], b["km"])):
        return False
    sa, sb = a.get("sig"), b.get("sig")
    if sa and sb:
        return (_hav(sa["s"], sb["s"]) < 500 and _hav(sa["f"], sb["f"]) < 700 and _hav(sa["t"], sb["t"]) < 700)
    return abs(a["dp"] - b["dp"]) <= max(40, 0.12 * max(a["dp"], b["dp"]))      # sin GPS: km y D+


@st.cache_data(ttl=30 * 86400, show_spinner=False)
def zone_hint(lat: float, lng: float) -> str:
    """Nombre propuesto para una zona: la cima con nombre más cercana al punto más alto (OpenStreetMap) o, si no hay, el lugar."""
    ua = {"User-Agent": "LlibretaD+/2 (app personal de entrenamiento)"}
    try:
        q = f'[out:json][timeout:10];node(around:600,{lat:.5f},{lng:.5f})[natural~"peak|saddle"][name];out 5;'
        r = requests.post("https://overpass-api.de/api/interpreter", data={"data": q}, timeout=6, headers=ua)
        if r.ok:
            els = r.json().get("elements") or []
            if els:
                el = min(els, key=lambda e: _hav((lat, lng), (e["lat"], e["lon"])))
                return str(el.get("tags", {}).get("name") or "")
    except Exception:  # noqa: BLE001
        pass
    try:
        r = requests.get("https://nominatim.openstreetmap.org/reverse", params={"lat": lat, "lon": lng, "format": "json", "zoom": 14},
                         timeout=6, headers=ua)
        if r.ok:
            a_ = r.json().get("address") or {}
            return str(next((a_[k] for k in ("hamlet", "village", "suburb", "town", "city", "municipality") if a_.get(k)), ""))
    except Exception:  # noqa: BLE001
        pass
    return ""


ZONE_COLS = ["#e09b00", "#0a84c6", "#d6336c", "#2b9348", "#7b2cbf", "#e8590c", "#1098ad", "#5c940d"]


def zone_map_ui(groups: list, trows: list):
    """Mapa y perfil de un recorrido agrupado: las salidas del grupo superpuestas, con salida, punto más alto y subidas."""
    with st.expander("🗺 Ver el recorrido de una zona: mapa, perfil y subidas", expanded=False, key="nom_map_x"):
        if not groups:
            return
        labs = [f'{(t["Zona"] or "Sin nombre")} · {t["Tipo"]} · {t["Salidas"]} salidas · {fnum(t["Km"], 1)} km · '
                f'+{fnum(t["D+"])} / −{fnum(t["D−"])} m' for t in trows]
        gi = st.selectbox("Zona", range(len(groups)), format_func=lambda i: labs[i], key="nom_map_g")
        g = groups[gi]
        acts_ = sorted(g["acts"], key=lambda a: a["ts"], reverse=True)[:8]
        if not acts_:
            st.info("Esta zona guardada no tiene salidas desde enero de 2026.")
            return
        dfs = []
        with st.spinner("Leyendo los recorridos…"):
            for a in acts_:
                d_, _src = act_df(a["id"], a["km"], a["dp"], a["secs"])
                ok_ = d_.dropna(subset=["lat", "lng"]) if len(d_) else d_
                if len(ok_) >= 50:
                    dfs.append((a, d_, ok_))
        if not dfs:
            st.info("Las salidas de esta zona no tienen GPS: no se puede dibujar el mapa.")
            return
        a0, d0, ok0 = dfs[0]
        c_lat, c_lng = float(ok0["lat"].mean()), float(ok0["lng"].mean())
        bgs = map_backgrounds(c_lat, c_lng)
        if st.session_state.get("nom_bg") not in bgs:
            st.session_state["nom_bg"] = bgs[0]
        fondo = st.segmented_control("Fondo del mapa", bgs, key="nom_bg") or bgs[0]
        TS = track_style(fondo)
        tiles = base_tiles(fondo, c_lat, c_lng)
        rd = lambda v: np.round(np.asarray(v, dtype=float), 5)  # noqa: E731
        f_m = go.Figure()
        for k, (a, d_, ok_) in reversed(list(enumerate(dfs))):          # la más reciente encima
            idx = np.unique(np.linspace(0, len(ok_) - 1, min(len(ok_), 1500)).astype(int))
            s_ = ok_.iloc[idx]
            w_ = 6 if k == 0 else 3
            f_m.add_trace(go.Scattermap(lat=rd(s_["lat"]), lon=rd(s_["lng"]), mode="lines", line=dict(color=TS["halo"], width=w_ + 4),
                                        opacity=TS["halo_op"], hoverinfo="skip", showlegend=False))
            f_m.add_trace(go.Scattermap(lat=rd(s_["lat"]), lon=rd(s_["lng"]), mode="lines",
                                        line=dict(color=ZONE_COLS[k % len(ZONE_COLS)], width=w_),
                                        name=f'{a["date"]:%d/%m/%y} · {fnum(a["km"], 1)} km · +{fnum(a["dp"])} / −{fnum(a["dm"])} m',
                                        hovertemplate=f'{a["date"]:%d/%m/%y} · {_html.escape(a["name"])}<extra></extra>'))
        # salida, meta y punto más alto de la más reciente; marcas de km
        dd = ok0["dist"].to_numpy()
        kms = [k for k in range(1, int(dd[-1] // 1000) + 1)]
        if kms:
            pos = np.clip(np.searchsorted(dd, [k * 1000 for k in kms]), 0, len(dd) - 1)
            f_m.add_trace(go.Scattermap(lat=rd(ok0["lat"].to_numpy()[pos]), lon=rd(ok0["lng"].to_numpy()[pos]), mode="markers+text",
                                        marker=dict(size=14, color=TS["halo"]), text=[str(k) for k in kms],
                                        textfont=dict(size=9, color="#111417" if fondo != "Satélite" else "#ffffff"),
                                        textposition="middle center", hovertemplate="km %{text}<extra></extra>", showlegend=False))
        top_ = ok0.loc[ok0["alt_s"].idxmax()] if ok0["alt_s"].notna().any() else ok0.iloc[len(ok0) // 2]
        pts = [(float(ok0["lat"].iloc[0]), float(ok0["lng"].iloc[0]), GREEN, f'Salida · {fnum(ok0["alt_s"].iloc[0])} m'),
               (float(ok0["lat"].iloc[-1]), float(ok0["lng"].iloc[-1]), RED, f'Llegada · {fnum(ok0["alt_s"].iloc[-1])} m'),
               (float(top_["lat"]), float(top_["lng"]), GOLD, f'Punto más alto · {fnum(top_["alt_s"])} m · km {fnum(top_["dist"] / 1000, 1)}')]
        f_m.add_trace(go.Scattermap(lat=[p_[0] for p_ in pts], lon=[p_[1] for p_ in pts], mode="markers", marker=dict(size=17, color=TS["halo"]),
                                    hoverinfo="skip", showlegend=False))
        f_m.add_trace(go.Scattermap(lat=[p_[0] for p_ in pts], lon=[p_[1] for p_ in pts], mode="markers",
                                    marker=dict(size=11, color=[p_[2] for p_ in pts]), text=[p_[3] for p_ in pts],
                                    hovertemplate="%{text}<extra></extra>", showlegend=False))
        la_all = pd.concat([o["lat"] for _a, _d, o in dfs])
        lo_all = pd.concat([o["lng"] for _a, _d, o in dfs])
        span_ = max(float(np.ptp(la_all)) * 1.5, float(np.ptp(lo_all)) * math.cos(math.radians(c_lat)) * 1.05, 0.002)
        zoom_ = float(np.clip(math.log2(360 / span_) - 0.7, 8, 16))
        plot_layout(f_m, 520)
        f_m.update_layout(map=dict(style="white-bg", center=dict(lat=float(la_all.mean()), lon=float(lo_all.mean())), zoom=zoom_,
                                   layers=[dict(sourcetype="raster", source=tiles["urls"], below="traces",
                                                sourceattribution=tiles["attr"], maxzoom=tiles["maxzoom"])]),
                          margin=dict(l=8, r=8, t=8, b=8), showlegend=True,
                          legend=dict(x=.01, y=.99, xanchor="left", yanchor="top", orientation="v", bgcolor=SURFACE, bordercolor=LINE,
                                      borderwidth=1, font=dict(color=INK, size=11)))
        st.plotly_chart(f_m, width="stretch", theme=None, config={"scrollZoom": True}, key=f"nom_map_{gi}")
        # perfil de las salidas del grupo
        f_p = go.Figure()
        for k, (a, d_, _ok) in reversed(list(enumerate(dfs))):
            g_ = d_.dropna(subset=["dist", "alt_s"])
            idx = np.unique(np.linspace(0, len(g_) - 1, min(len(g_), 800)).astype(int))
            s_ = g_.iloc[idx]
            f_p.add_scatter(x=s_["dist"] / 1000, y=s_["alt_s"], mode="lines", name=f'{a["date"]:%d/%m/%y}',
                            line=dict(color=ZONE_COLS[k % len(ZONE_COLS)], width=3 if k == 0 else 1.5),
                            hovertemplate="km %{x:.2f} · %{y:.0f} m<extra>" + f'{a["date"]:%d/%m/%y}' + "</extra>")
        f_p.update_xaxes(title="km")
        f_p.update_yaxes(ticksuffix=" m")
        st.plotly_chart(plot_layout(f_p, 240), width="stretch", theme=None, key=f"nom_prof_{gi}")
        # ficha del recorrido (la salida más reciente)
        cl = climbs_of(d0)
        alt_ = d0["alt_s"].dropna()
        lines_ = [f'<b>Salida</b> a {fnum(alt_.iloc[0])} m · <b>punto más alto</b> {fnum(alt_.max())} m (km {fnum(top_["dist"] / 1000, 1)}) · '
                  f'<b>llegada</b> a {fnum(alt_.iloc[-1])} m'
                  + (" · vuelve al punto de salida" if _hav((pts[0][0], pts[0][1]), (pts[1][0], pts[1][1])) < 300 else
                     f' · termina a {fnum(_hav((pts[0][0], pts[0][1]), (pts[1][0], pts[1][1])) / 1000, 1)} km de la salida (solo ida)')]
        if cl:
            lines_.append("<b>Subidas</b>: " + " · ".join(
                f'km {fnum(c_["km0"], 1)}–{fnum(c_["km1"], 1)}: {fnum(c_["a0"])}→{fnum(c_["a1"])} m (+{fnum(c_["gain"])} m, {fnum(c_["grade"])} %)'
                for c_ in cl))
        lines_.append(f'Salidas de la zona: ' + ", ".join(f'{a["date"]:%d/%m/%y}' for a in sorted(g["acts"], key=lambda a: a["ts"])))
        st.markdown('<div class="note">' + "<br>".join(lines_) + "</div>", unsafe_allow_html=True)
        st.markdown(f'<span class="note">En el mapa, las {len(dfs)} salidas más recientes del grupo (la última, más gruesa). '
                    'Números = kilómetros de la última. Si una salida se aparta del resto, es otro recorrido: ponle otro nombre.</span>',
                    unsafe_allow_html=True)


FZ_SPORTS = {"WeightTraining", "Workout"}
PLAN_MARK = "— Plan · Llibreta D+ —"
_WK_TYPE = {"r": "descarga y recuperación", "t": "taper", "R": "semana de carrera"}


def plan_session_of(date_, kind: str, aid: str, W: list, adj: dict):
    """Semana del plan y sesión planificada de una actividad de cinta o fuerza: la enlazada en «Ajustar las sesiones» o, si no,
    la de ese tipo planificada ese día (o, si se hizo otro día, la primera de ese tipo de esa semana)."""
    for k_, v_ in (adj or {}).items():
        if isinstance(v_, dict) and str(v_.get("act")) == str(aid) and "|" in k_:
            o_, sid_ = k_.split("|", 1)
            try:
                od = dt.date.fromisoformat(o_)
            except ValueError:
                continue
            w_ = next((w for w in W if w["frm"] <= od <= w["to"]), None)
            if w_ is not None:
                try:
                    if sess(sid_)["kind"] == kind:
                        return w_, sid_
                except KeyError:
                    pass
    w_ = next((w for w in W if w["frm"] <= date_ <= w["to"]), None)
    if w_ is None:
        return None, None
    same = [sid for d_, sid in w_["ses"] if d_ == date_ and sess(sid)["kind"] == kind]
    anyw = [sid for d_, sid in w_["ses"] if sess(sid)["kind"] == kind]
    return w_, (same or anyw or [None])[0]


def plan_desc(w_, sid) -> str:
    """Bloque de la descripción: fase y semana del plan, y la sesión planificada con su resumen de ejercicios."""
    lines = [PLAN_MARK, f'Fase: {w_["ph"]} · semana S{w_["i"] + 1} ({w_["frm"]:%d/%m} – {w_["to"]:%d/%m})'
             + (f' · {_WK_TYPE[w_["k"]]}' if w_["k"] in _WK_TYPE else "")]
    if sid:
        ss = sess(sid)
        lines.append(f'Sesión: {ss["name"]} · {ss["min"]} min' + (f' · ≈ {fnum(ss["km"], 1)} km · ≈ {fnum(ss["dp"])} m D+ · '
                                                                   f'pendiente media {cinta_pend_txt(ss["km"], ss["dp"])}'
                                                                   if ss["kind"] == "cinta" else ""))
        if ss.get("focus"):
            lines.append(ss["focus"])
        lines += [f"- {x}" for x in ss.get("ex", [])]
    else:
        lines.append("Sin sesión de este tipo en el plan esa semana.")
    return "\n".join(lines)


def desc_with_plan(old: str, block: str) -> str:
    """Descripción con el bloque del plan: se conserva lo que escribiste tú (lo que hay antes del bloque) y se sustituye el bloque."""
    old = str(old or "")
    keep = old.split(PLAN_MARK)[0].rstrip()
    return (keep + "\n\n" + block) if keep else block


def name_section():
    if st.session_state.get("nom_msg"):
        st.success(st.session_state.pop("nom_msg"))
    st.markdown('<span class="note">Pone a las carreras un nombre fijo según el tipo, la zona y un contador desde enero de 2026: '
                '<b>«Trail run · La Mola per Pi Tort #3»</b>, <b>«Asfalto · Volta al parc #12»</b> y <b>«Cinta #42»</b>. Las salidas por '
                'fuera se agrupan por recorrido (salida, punto más alejado, punto más alto y km, con el GPS de cada actividad). '
                'Pones el nombre de cada zona una vez; se guarda en intervals.icu y las salidas nuevas por el mismo sitio lo toman solas. '
                'Nada se cambia hasta que pulsas los botones.</span>', unsafe_allow_html=True)
    yrs = range(NAME_FROM.year, today.year + 1)
    rows_ = []
    for y in yrs:
        try:
            rows_ += raw.get(y) if y in raw else (demo_year(y) if demo else fetch_year(athlete, key, y))
        except Exception:  # noqa: BLE001
            pass
    df = to_frame(rows_, True, cinta_dp, st.session_state.get("incline_overrides")) if rows_ else pd.DataFrame()
    if not len(df):
        st.info("No hay actividades desde enero de 2026.")
        return
    df = df[(df["date"] >= NAME_FROM) & df["sport"].isin({"Run", "TrailRun"} | set(CINTA) | FZ_SPORTS)].sort_values("ts")
    desc_of = {str(r0.get("id")): str(r0.get("description") or "") for r0 in rows_ if isinstance(r0, dict)}
    # Periodo: solo se lee el GPS de las salidas del periodo (leerlo todo desde enero tarda). Los contadores siguen la numeración
    # de los nombres ya puestos antes del periodo.
    PERS = ["Última semana", "Últimos 30 días", "Desde 01/01/2026", "Fechas"]
    pc_, pd_ = st.columns([2, 2], vertical_alignment="bottom")
    with pc_:
        per_n = st.segmented_control("Actividades a revisar", PERS, default="Última semana", key="nom_per") or "Última semana"
    if per_n == "Última semana":
        n_from, n_to = today - dt.timedelta(days=6), today
    elif per_n == "Últimos 30 días":
        n_from, n_to = today - dt.timedelta(days=29), today
    elif per_n == "Fechas":
        with pd_:
            rng_ = st.date_input("Desde – hasta", value=(max(NAME_FROM, today - dt.timedelta(days=13)), today), min_value=NAME_FROM,
                                 max_value=today, format="DD/MM/YYYY", key="nom_rng")
        if isinstance(rng_, (list, tuple)) and len(rng_) == 2:
            n_from, n_to = min(rng_), max(rng_)
        else:
            n_from = n_to = rng_[0] if isinstance(rng_, (list, tuple)) and rng_ else today
    else:
        n_from, n_to = NAME_FROM, today
    if per_n != "Fechas":
        with pd_:
            st.markdown(f'<div class="note">{n_from:%d/%m/%y} – {n_to:%d/%m/%y}</div>', unsafe_allow_html=True)
    in_rng = (df["date"] >= n_from) & (df["date"] <= n_to)
    out_all = df[df["sport"].isin({"Run", "TrailRun"})]
    out_ = out_all[in_rng[out_all.index]]
    out_prev = out_all[~in_rng[out_all.index]]          # fuera del periodo: solo cuentan sus nombres ya puestos
    ci_all = df[df["sport"].isin(CINTA)]
    fz_all = df[df["sport"].isin(FZ_SPORTS)]
    ci_ = ci_all
    _, zdata = app_note_get(ZONES_NAME, "demo_zones")
    zones = [z for z in (zdata.get("z") or []) if isinstance(z, dict) and z.get("name")]

    # Firmas de recorrido (GPS); se guardan en caché una semana
    acts = []
    todo_ = [r_ for _, r_ in out_.iterrows()]
    prog = st.progress(0.0, text="Leyendo el GPS de las salidas…") if (len(todo_) and not demo) else None
    for i, r_ in enumerate(todo_):
        if demo:
            sig = route_sig_df(act_df(str(r_["id"]), float(r_["km"]), float(r_["dp"]), float(r_["secs"]))[0])
        else:
            sig = route_sig(key, str(r_["id"]))
        acts.append(dict(id=str(r_["id"]), date=r_["date"], ts=r_["ts"], sport=r_["sport"], name=str(r_["name"] or ""),
                         km=float(r_["km"]), dp=float(r_["dp"]), dm=float(r_["dm"]) if pd.notna(r_.get("dm")) else 0.0,
                         secs=float(r_["secs"]), sig=sig))
        if prog is not None:
            prog.progress((i + 1) / len(todo_), text="Leyendo el GPS de las salidas…")
    if prog is not None:
        prog.empty()

    # Grupos: primero las zonas guardadas, luego los recorridos nuevos
    groups = [dict(zi=i, name=z["name"], type=z.get("type", "trail"), ref=dict(km=z["km"], dp=z.get("dp", 0), sig=z.get("sig")),
                   acts=[]) for i, z in enumerate(zones)]
    for a in acts:
        g_ = next((g for g in groups if _same_route(g["ref"], a)), None)
        if g_ is None:
            g_ = dict(zi=None, name="", type="trail" if a["sport"] == "TrailRun" else "asfalto",
                      ref=dict(km=a["km"], dp=a["dp"], sig=a["sig"]), acts=[])
            groups.append(g_)
        g_["acts"].append(a)
    groups = [g for g in groups if g["acts"] or g["zi"] is not None]
    groups.sort(key=lambda g: (-len(g["acts"]), -g["ref"]["km"]))

    n_gps = sum(1 for a in acts if a["sig"])
    n_ci_r = int(in_rng[ci_all.index].sum())
    n_fz_r = int(in_rng[fz_all.index].sum())
    st.markdown(f'<span class="note">{len(acts)} salidas por fuera del {n_from:%d/%m/%y} al {n_to:%d/%m/%y} ({n_gps} con GPS) en '
                f'{len(groups)} recorridos · {n_ci_r} sesiones de cinta · {n_fz_r} de fuerza.'
                + ("" if per_n == "Desde 01/01/2026" else
                   ' Los contadores continúan la numeración de las salidas ya renombradas antes del periodo; si hay salidas anteriores '
                   'sin renombrar, revisa «Desde 01/01/2026» una vez.') + '</span>', unsafe_allow_html=True)

    st.markdown("#### 1 · Zonas")
    # Nombres propuestos con OpenStreetMap: solo al pulsar el botón (cada consulta tarda unos segundos y, hecha en cada
    # recarga de la página, la dejaba bloqueada). Lo encontrado se recuerda durante la sesión.
    hints = st.session_state.setdefault("nom_hints_d", {})
    hk = lambda sig: f'{sig["t"][0]:.4f},{sig["t"][1]:.4f}'  # noqa: E731
    sig_of = lambda g: g["ref"].get("sig") or next((a["sig"] for a in g["acts"] if a["sig"]), None)  # noqa: E731
    pend_ = [g for g in groups if not g["name"] and sig_of(g) and hk(sig_of(g)) not in hints]
    if pend_ and not demo:
        if st.button(f"🗺 Proponer nombres con OpenStreetMap ({len(pend_)} zonas sin nombre)", key="nom_hint_go",
                     help="Busca la cima con nombre más cercana al punto más alto de cada zona (o el lugar). Tarda unos segundos por zona."):
            pr_ = st.progress(0.0, text="Buscando nombres en OpenStreetMap…")
            for j, g in enumerate(pend_[:25]):
                sg = sig_of(g)
                hints[hk(sg)] = zone_hint(round(sg["t"][0], 4), round(sg["t"][1], 4))
                pr_.progress((j + 1) / min(len(pend_), 25), text="Buscando nombres en OpenStreetMap…")
            pr_.empty()
            st.session_state.pop("nom_zones_ed", None)
            st.rerun()
    trows = []
    for gi, g in enumerate(groups):
        sig = sig_of(g)
        hint = ""
        if not g["name"] and sig:
            hint = hints.get(hk(sig), "")
        a0 = g["acts"]
        km_ = float(np.median([a["km"] for a in a0])) if a0 else g["ref"]["km"]
        dp_ = float(np.median([a["dp"] for a in a0])) if a0 else g["ref"]["dp"]
        dm_ = float(np.median([a["dm"] for a in a0])) if a0 else 0.0
        trows.append({"gi": gi, "Zona": g["name"] or hint, "Tipo": NAME_TYPES[g["type"]],
                      "Salidas": len(a0), "Km": round(km_, 1), "D+": round(dp_), "D−": round(dm_),
                      "Fechas": (f'{a0[0]["date"]:%d/%m/%y} – {a0[-1]["date"]:%d/%m/%y}' if len(a0) > 1 else
                                 f'{a0[0]["date"]:%d/%m/%y}' if a0 else "—"),
                      "Mapa": (f'https://www.openstreetmap.org/?mlat={sig["t"][0]:.5f}&mlon={sig["t"][1]:.5f}#map=15/{sig["t"][0]:.5f}/{sig["t"][1]:.5f}'
                               if sig else None),
                      "Estado": "guardada" if g["zi"] is not None else ("propuesta" if hint else "sin nombre")})
    TB = pd.DataFrame(trows)
    ed = st.data_editor(TB, key="nom_zones_ed", hide_index=True, width="stretch", num_rows="fixed",
                        column_order=["Zona", "Tipo", "Salidas", "Km", "D+", "D−", "Fechas", "Mapa", "Estado"],
                        column_config={
                            "Zona": st.column_config.TextColumn("Zona", max_chars=50, width="large",
                                                                help="El nombre fijo del recorrido, p. ej. «La Mola per Pi Tort»"),
                            "Tipo": st.column_config.SelectboxColumn("Tipo", options=list(NAME_TYPES.values()), required=True),
                            "Salidas": st.column_config.NumberColumn("Salidas", disabled=True),
                            "Km": st.column_config.NumberColumn("Km", disabled=True, format="%.1f"),
                            "D+": st.column_config.NumberColumn("D+ m", disabled=True, format="%d"),
                            "D−": st.column_config.NumberColumn("D− m", disabled=True, format="%d"),
                            "Fechas": st.column_config.TextColumn("Fechas", disabled=True),
                            "Mapa": st.column_config.LinkColumn("Punto más alto", display_text="mapa ↗", disabled=True),
                            "Estado": st.column_config.TextColumn("Estado", disabled=True, width="small")})
    st.markdown('<span class="note">«Propuesta» = nombre sacado del mapa: revísalo y cámbialo por el tuyo. Dos zonas con el mismo nombre '
                'se cuentan juntas (sirve para unir variantes del mismo recorrido). Una zona vacía no se renombra.</span>',
                unsafe_allow_html=True)
    zone_map_ui(groups, trows)
    inv_t = {v: k for k, v in NAME_TYPES.items()}
    for _, r_ in ed.iterrows():
        g = groups[int(r_["gi"])]
        g["name_new"] = str(r_["Zona"] or "").strip()
        g["type_new"] = inv_t.get(r_["Tipo"], g["type"])
    new_z = []
    for g in groups:
        if not g["name_new"]:
            continue
        sig = g["ref"].get("sig") or next((a["sig"] for a in g["acts"] if a["sig"]), None)
        km_ = float(np.median([a["km"] for a in g["acts"]])) if g["acts"] else g["ref"]["km"]
        dp_ = float(np.median([a["dp"] for a in g["acts"]])) if g["acts"] else g["ref"]["dp"]
        new_z.append(dict(name=g["name_new"][:50], type=g["type_new"], km=round(km_, 2), dp=round(dp_),
                          sig={k_: [round(v[0], 5), round(v[1], 5)] for k_, v in sig.items()} if sig else None))
    old_cmp = [(z["name"], z.get("type"), round(float(z["km"]), 1)) for z in zones]
    new_cmp = [(z["name"], z["type"], round(float(z["km"]), 1)) for z in new_z]
    if st.button(f'Guardar las zonas ({len(new_z)})', key="nom_save_z", disabled=sorted(old_cmp) == sorted(new_cmp)):
        try:
            app_note_save(ZONES_NAME, "demo_zones", {"v": 1, "z": new_z})
            st.session_state["nom_msg"] = f"Guardadas {len(new_z)} zonas."
            st.session_state.pop("nom_zones_ed", None)
            st.rerun()
        except Exception as e:  # noqa: BLE001
            st.error(f"No se pudieron guardar las zonas: {e}")

    # Nombres nuevos (con lo que hay ahora en la tabla, guardado o no)
    st.markdown("#### 2 · Nombres")
    plan_ = []
    by_zone = {}
    for g in groups:
        if g["name_new"]:
            by_zone.setdefault(g["name_new"], []).extend((a, g["type_new"]) for a in g["acts"])
    prev_names = [(r_["ts"], str(r_["name"] or "")) for _, r_ in out_prev.iterrows()]
    for zn, lst in by_zone.items():
        lst.sort(key=lambda x: x[0]["ts"])
        pat = re.compile(r"·\s*" + re.escape(zn) + r"\s*#\d+\s*$")
        prev_ts = sorted(t for t, nm in prev_names if pat.search(nm))   # ya renombradas de esta zona, fuera del periodo
        for k_, (a, ty) in enumerate(lst):
            n_ = 1 + k_ + sum(1 for t in prev_ts if t < a["ts"])
            plan_.append(dict(id=a["id"], ts=a["ts"], old=a["name"], new=f'{NAME_TYPES[ty]} · {zn} #{n_}'))
    # Cinta y fuerza: contador con todas las de 2026 (no necesitan GPS) y, en la descripción, la fase y la sesión del plan
    use_desc = st.toggle("Cinta y fuerza: poner en la descripción la fase del plan y la sesión con sus ejercicios", value=True,
                         key="nom_desc", help="Se añade un bloque «" + PLAN_MARK + "» al final de la descripción; lo que hayas "
                                              "escrito tú se conserva. Si ya hay un bloque, se sustituye.")
    try:
        W_pl = summary_plan().get("W") or []
    except Exception:  # noqa: BLE001
        W_pl = []
    try:
        adj_ = plan_adj()
    except Exception:  # noqa: BLE001
        adj_ = {}
    for lab_, kind_, frame_ in (("Cinta", "cinta", ci_all), ("Fuerza", "fuerza", fz_all)):
        for n_, (ix, r_) in enumerate(frame_.iterrows(), 1):
            if not in_rng[ix]:
                continue
            aid = str(r_["id"])
            x = dict(id=aid, ts=r_["ts"], old=str(r_["name"] or ""), new=f"{lab_} #{n_}", desc_old=desc_of.get(aid, ""))
            if use_desc and W_pl:
                w_, sid_ = plan_session_of(r_["date"], kind_, aid, W_pl, adj_)
                if w_ is not None:
                    x["desc_new"] = desc_with_plan(x["desc_old"], plan_desc(w_, sid_))
                    x["ses"] = sess(sid_)["name"] if sid_ else "—"
                    x["fase"] = f'{w_["ph"]} · S{w_["i"] + 1}'
            plan_.append(x)
    plan_.sort(key=lambda x: x["ts"], reverse=True)
    for x in plan_:
        x["name_chg"] = x["new"] != x["old"]
        x["desc_chg"] = "desc_new" in x and x["desc_new"].strip() != str(x.get("desc_old", "")).strip()
    chg = [x for x in plan_ if x["name_chg"] or x["desc_chg"]]
    sin = sum(len(g["acts"]) for g in groups if not g["name_new"])
    c1, c2 = st.columns([1, 1])
    only_auto = c1.toggle("No tocar los nombres que ya cambié a mano", value=True, key="nom_keep",
                          help="Solo renombra las que tienen el nombre de Suunto («Morning Carrera de senderos»…) o uno puesto por "
                               "esta herramienta; deja las que tú ya bautizaste (p. ej. una carrera).")
    if only_auto:
        gen = re.compile(r"^(Morning|Afternoon|Evening|Lunch|Night)\b|^(Carrera|Correr|Trail|Run|Ejercicio|Entrenamiento)\b", re.I)
        for x in chg:                          # nombre puesto a mano: se deja (la descripción del plan sí se puede añadir)
            if x["name_chg"] and not (gen.search(x["old"]) or _RE_AUTO.match(x["old"]) or re.match(r"^(Cinta|Fuerza) #\d+$", x["old"])):
                x["name_chg"] = False
        chg = [x for x in chg if x["name_chg"] or x["desc_chg"]]
    n_nm, n_ds = sum(1 for x in chg if x["name_chg"]), sum(1 for x in chg if x["desc_chg"])
    c2.markdown(f'<div class="note">{n_nm} nombres y {n_ds} descripciones cambian'
                + (f' · {sin} salidas sin zona (no se tocan)' if sin else "") + '</div>', unsafe_allow_html=True)
    if chg:
        PV = pd.DataFrame([{"Fecha": x["ts"].strftime("%d/%m/%y"), "Nombre actual": x["old"],
                            "Nombre nuevo": x["new"] if x["name_chg"] else "(igual)",
                            "Descripción: fase · sesión del plan": (f'{x.get("fase", "")} · {x.get("ses", "")}' if x["desc_chg"] else "")}
                           for x in chg])
        html_table(PV, left={"Fecha", "Nombre actual", "Nombre nuevo", "Descripción: fase · sesión del plan"}, max_height=420)
        ex_ = next((x for x in chg if x["desc_chg"]), None)
        if ex_ is not None:
            with st.expander(f'Ejemplo de descripción ({ex_["ts"]:%d/%m/%y} · {ex_["new"]})', expanded=False, key="nom_desc_ex"):
                st.code(ex_["desc_new"], language=None, wrap_lines=True)
    conf = st.checkbox(f"Sí, cambiar {len(chg)} actividades en intervals.icu", key="nom_ok", disabled=not chg)
    if st.button(f"Guardar {len(chg)} actividades", type="primary", disabled=not (chg and conf), key="nom_go"):
        ok, fails = 0, []
        pr = st.progress(0.0)
        for j, x in enumerate(chg):
            body_ = {}
            if x["name_chg"]:
                body_["name"] = x["new"]
            if x["desc_chg"]:
                body_["description"] = x["desc_new"]
            try:
                if not demo and body_:
                    icu_write("PUT", f"/activity/{x['id']}", body_)
                ok += 1
            except Exception as e:  # noqa: BLE001
                fails.append(f'{x["ts"]:%d/%m/%y} {x["old"]}: {e}')
            pr.progress((j + 1) / len(chg))
        if fails:
            st.error(f"No se pudieron renombrar {len(fails)}:\n\n" + "\n\n".join(fails[:10]))
        if ok:
            fetch_year.clear()                     # los nombres nuevos (sin borrar la caché del GPS de las salidas)
            st.session_state.pop("nom_ok", None)
            st.session_state["nom_msg"] = f"Guardadas {ok} actividades en intervals.icu (nombre y/o descripción)."
            st.rerun()


if SEC == "fix":
    act_fix_section()

if SEC == "nom":
    name_section()

if SEC == "cinta":
    st.subheader("Pendiente de las sesiones de cinta")
    if st.session_state.get("cinta_msg"):
        st.success(st.session_state.pop("cinta_msg"))
    st.markdown(
        f'<span class="note">El reloj no registra el desnivel en cinta. Escribe el <b>nivel de inclinación de la cinta</b> '
        f'(el número de la máquina, 0–{fnum(CINTA_MAX_LEVEL)}) y la app lo convierte a <b>pendiente real</b>: '
        f'nivel {fnum(CINTA_MAX_LEVEL)} = {fnum(CINTA_MAX_PCT)} % real (cada nivel = {fnum(level_to_pct(1), 2)} %). '
        f'D+ = km × pendiente real. El nivel se guarda en intervals.icu, en el campo personalizado de actividad <b>{INCLINE_FIELD}</b>.</span>',
        unsafe_allow_html=True)
    eq_ = [0, 2, 4, 5, 6, 8, 10, 12]
    st.markdown('<div class="tblw" style="display:inline-block"><table class="tbl"><thead><tr><th class="l">Nivel cinta</th>'
                + "".join(f"<th>{fnum(l_)}</th>" for l_ in eq_) + '</tr></thead><tbody><tr><td class="l">% real</td>'
                + "".join(f"<td>{fnum(level_to_pct(l_), 1)}</td>" for l_ in eq_) + "</tr></tbody></table></div>", unsafe_allow_html=True)
    tm_ = all_df[all_df["sport"].isin(CINTA)].sort_values("ts", ascending=False) if len(all_df) else all_df
    periodo = st.segmented_control("Periodo cinta", ["30 días", "90 días", f"Año {year}", "Todo"], default="90 días",
                                   label_visibility="collapsed", key="cinta_rng") or "90 días"
    if periodo == "30 días":
        tm_ = tm_[tm_["date"] >= today - dt.timedelta(days=30)]
    elif periodo == "90 días":
        tm_ = tm_[tm_["date"] >= today - dt.timedelta(days=90)]
    elif periodo.startswith("Año"):
        tm_ = tm_[tm_["ts"].dt.year == year]
    if not len(tm_):
        st.info("No hay sesiones de cinta en este periodo.")
    else:
        pend_n = int(tm_["incline"].isna().sum())
        pm_ = (tm_["dp"].sum() / (tm_["km"].sum() * 10)) if tm_["km"].sum() else 0
        cards([
            ("Sesiones", GLACIER, fnum(len(tm_)), "", [f"{pend_n} sin nivel" if pend_n else "todas con nivel"]),
            ("Km cinta", GLACIER, fnum(tm_["km"].sum(), 1), "km", ["&nbsp;"]),
            ("D+ cinta", GOLD, fnum(tm_["dp"].sum()), "m", ["sumado al D+ total" if cinta_dp else "no se suma (desactivado)"]),
            ("Pendiente media", ORANGE, fnum(pm_, 1), "% real",
             [f"nivel medio {fnum(pm_ * CINTA_MAX_LEVEL / CINTA_MAX_PCT, 1)} · ponderada por km"]),
        ])
        # Paginación
        PER_PAGE = 20
        n_pages = max(1, math.ceil(len(tm_) / PER_PAGE))
        sig = f"{periodo}|{len(tm_)}"
        if st.session_state.get("cinta_sig") != sig:          # cambio de periodo → volver a la primera página
            st.session_state["cinta_sig"] = sig
            st.session_state["cinta_page"] = 1
        page = min(max(1, int(st.session_state.get("cinta_page", 1))), n_pages)
        if n_pages > 1:
            pg1, pg2, pg3, _ = st.columns([1, 1.6, 1, 3], vertical_alignment="center")
            with pg1:
                if st.button("◀ Anterior", disabled=page <= 1, width="stretch", key="cinta_prev"):
                    st.session_state["cinta_page"] = page - 1
                    st.rerun()
            with pg2:
                st.markdown(f'<div class="note" style="text-align:center">Página <b style="color:{INK}">{page}</b> de {n_pages} · '
                            f'{len(tm_)} sesiones</div>', unsafe_allow_html=True)
            with pg3:
                if st.button("Siguiente ▶", disabled=page >= n_pages, width="stretch", key="cinta_next"):
                    st.session_state["cinta_page"] = page + 1
                    st.rerun()
        rows_c = tm_.iloc[(page - 1) * PER_PAGE: page * PER_PAGE]
        # Nivel propuesto por el plan: la pendiente media (D+ ÷ km) de la sesión de cinta planificada ese día o, si se hizo
        # otro día, la de esa semana
        try:
            W_pl = summary_plan().get("W") or []
        except Exception:  # noqa: BLE001
            W_pl = []
        pl_day, pl_week = {}, {}
        for w_ in W_pl:
            for d_s, sid_ in w_["ses"]:
                ss_ = sess(sid_)
                if ss_["kind"] == "cinta" and cinta_pend(ss_.get("km"), ss_.get("dp")):
                    pl_day[d_s] = (ss_, cinta_pend(ss_["km"], ss_["dp"]))
                    pl_week.setdefault(w_["frm"], (ss_, cinta_pend(ss_["km"], ss_["dp"])))

        def plan_lvl(d_):
            if d_ in pl_day:
                return pl_day[d_]
            return pl_week.get(d_ - dt.timedelta(days=d_.weekday()))
        CW_ = [1.1, 2.4, 0.7, 0.7, 1.2, 1.3, 0.7, 0.8]
        hc = st.columns(CW_, vertical_alignment="center")
        for col, (t, r) in zip(hc, [("Fecha", ""), ("Sesión", ""), ("Km", "r"), ("Tiempo", "r"), (f"Nivel cinta (0–{fnum(CINTA_MAX_LEVEL)})", ""),
                                    ("Nivel del plan", ""), ("% real", "r"), ("D+ m", "r")]):
            col.markdown(f'<div class="chd {r}">{t}</div>', unsafe_allow_html=True)
        with st.form("cinta_form", border=False):
            inputs, sugg = {}, {}
            for i, (_, rw) in enumerate(rows_c.iterrows()):
                with st.container(key=f"crow{'E' if i % 2 else 'O'}_{i}"):
                    cc = st.columns(CW_, vertical_alignment="center")
                    cc[0].markdown(f'<div class="ctd" style="font-family:IBM Plex Mono,monospace">{rw["ts"].strftime("%d/%m/%y")}</div>', unsafe_allow_html=True)
                    cc[1].markdown(f'<div class="ctd" title="{rw["name"]}">{rw["name"]}</div>', unsafe_allow_html=True)
                    cc[2].markdown(f'<div class="ctd r">{fnum(rw["km"], 2)}</div>', unsafe_allow_html=True)
                    cc[3].markdown(f'<div class="ctd r">{int(rw["secs"] // 3600)}:{int(rw["secs"] % 3600 // 60):02d}</div>', unsafe_allow_html=True)
                    inputs[rw["id"]] = cc[4].number_input(
                        "Nivel cinta", min_value=0.0, max_value=CINTA_MAX_LEVEL, step=0.5, format="%.1f",
                        value=None if pd.isna(rw["incline"]) else min(float(rw["incline"]), CINTA_MAX_LEVEL),
                        placeholder="—", label_visibility="collapsed", key=f"lvl_{rw['id']}")
                    pl_ = plan_lvl(rw["date"])
                    if pl_:
                        sugg[rw["id"]] = pl_[1][1]
                    cc[5].markdown(f'<div class="ctd" title="{_html.escape(pl_[0]["name"]) if pl_ else ""}">'
                                   + (f'{fnum(pl_[1][1], 1)} <span style="color:{MUTED}">({fnum(pl_[1][0], 1)} %)</span>' if pl_ else "—")
                                   + "</div>", unsafe_allow_html=True)
                    cc[6].markdown(f'<div class="ctd r">{"—" if pd.isna(rw["incline"]) else fnum(level_to_pct(rw["incline"]), 1) + " %"}</div>',
                                   unsafe_allow_html=True)
                    dpv = rw["dp"]
                    cc[7].markdown(f'<div class="ctd r" style="color:{GOLD if dpv > 0 else ZERO}">{fnum(dpv) if dpv > 0 else "0"}</div>',
                                   unsafe_allow_html=True)
            use_pl = st.checkbox("Usar el nivel del plan en las sesiones sin nivel", key="cinta_use_plan",
                                 help="Al guardar, las casillas vacías toman el «Nivel del plan»: la pendiente media (D+ ÷ km) de la "
                                      "sesión de cinta planificada ese día (o esa semana). Las que ya tienen nivel no se tocan.")
            cA, cB = st.columns([1, 3], vertical_alignment="center")
            with cA:
                save = st.form_submit_button("Guardar en intervals.icu", type="primary", width="stretch")
            with cB:
                st.caption(("Guarda antes de cambiar de página: los cambios sin guardar se pierden. " if n_pages > 1 else "")
                           + "Escribe el nivel de la cinta y pulsa Guardar; el % real y el D+ se recalculan al guardar. Antes del primer guardado, crea en "
                           f"intervals.icu un campo personalizado de actividad, numérico, con el código `{INCLINE_FIELD}`.")
        orig = rows_c.set_index("id")["incline"]
        changed = []
        for act_id, val in inputs.items():
            o = orig[act_id]
            if use_pl and val is None and pd.isna(o) and act_id in sugg:
                val = float(sugg[act_id])
            if (val is None and pd.isna(o)) or (val is not None and pd.notna(o) and abs(val - o) < 1e-9):
                continue
            changed.append((act_id, np.nan if val is None else val))
        if save and not changed:
            st.info("No hay cambios que guardar.")
        if save and changed:
            ov = dict(st.session_state.get("incline_overrides", {}))
            ok, fails = 0, []
            for act_id, val in changed:
                v = None if pd.isna(val) else float(val)
                if demo:
                    ok += 1
                    ov[act_id] = v
                    continue
                try:
                    r = requests.put(f"{API}/activity/{act_id}", json={INCLINE_FIELD: v}, auth=("API_KEY", key),
                                     headers={"Accept": "application/json", "User-Agent": "LlibretaD+ (Streamlit)"}, timeout=30)
                    if r.status_code >= 400:
                        fails.append(f"{act_id}: error {r.status_code} {r.text[:120]}")
                    else:
                        ok += 1
                        ov[act_id] = v
                except Exception as e:  # noqa: BLE001
                    fails.append(f"{act_id}: {e}")
            st.session_state["incline_overrides"] = ov
            if fails:
                st.error("No se pudieron guardar algunos niveles:\n\n" + "\n\n".join(fails))
            if ok:
                st.cache_data.clear()
                st.session_state["cinta_msg"] = f"Guardados {ok} niveles de cinta en intervals.icu."
                st.rerun()

    # Aplicar un mismo nivel a todas las sesiones de cinta de un año
    tall_ = all_df[all_df["sport"].isin(CINTA)] if len(all_df) else all_df
    yrs_ = sorted({int(y_) for y_ in tall_["ts"].dt.year}, reverse=True) if len(tall_) else []
    if yrs_:
        with st.expander("Aplicar un nivel a todas las sesiones de cinta de un año", key="cinta_bulk_x"):
            b1, b2, b3 = st.columns([1, 1, 2], vertical_alignment="bottom")
            y_b = b1.selectbox("Año", yrs_, index=yrs_.index(2026) if 2026 in yrs_ else 0, key="cinta_bulk_y")
            l_b = b2.number_input("Nivel de cinta", min_value=0.0, max_value=CINTA_MAX_LEVEL, value=5.0, step=0.5, format="%.1f",
                                  key="cinta_bulk_l")
            tb_ = tall_[tall_["ts"].dt.year == y_b]
            b3.markdown(f'<div class="note">{len(tb_)} sesiones de cinta en {y_b} · nivel {fnum(l_b, 1)} = '
                        f'{fnum(level_to_pct(l_b), 2)} % real · D+ resultante ≈ {fnum(tb_["km"].sum() * 10 * level_to_pct(l_b))} m</div>',
                        unsafe_allow_html=True)
            conf = st.checkbox(f"Sí, sustituir el nivel de las {len(tb_)} sesiones de {y_b} (también las que ya tienen uno)",
                               key="cinta_bulk_ok")
            if st.button("Aplicar a todas", type="primary", disabled=not conf, key="cinta_bulk_go"):
                ov = dict(st.session_state.get("incline_overrides", {}))
                ok, fails = 0, []
                prog = st.progress(0.0)
                for j, act_id in enumerate(tb_["id"]):
                    if demo:
                        ok += 1
                        ov[act_id] = float(l_b)
                    else:
                        try:
                            r = requests.put(f"{API}/activity/{act_id}", json={INCLINE_FIELD: float(l_b)}, auth=("API_KEY", key),
                                             headers={"Accept": "application/json", "User-Agent": "LlibretaD+ (Streamlit)"}, timeout=30)
                            if r.status_code >= 400:
                                fails.append(f"{act_id}: error {r.status_code} {r.text[:120]}")
                            else:
                                ok += 1
                                ov[act_id] = float(l_b)
                        except Exception as e:  # noqa: BLE001
                            fails.append(f"{act_id}: {e}")
                    prog.progress((j + 1) / max(1, len(tb_)))
                st.session_state["incline_overrides"] = ov
                if fails:
                    st.error(f"No se pudo guardar el nivel en {len(fails)} sesiones:\n\n" + "\n\n".join(fails[:10]))
                if ok:
                    st.cache_data.clear()
                    for k_ in [k_ for k_ in st.session_state if str(k_).startswith("lvl_")]:   # que las casillas muestren el nivel nuevo
                        del st.session_state[k_]
                    st.session_state["cinta_msg"] = f"Nivel {fnum(l_b, 1)} ({fnum(level_to_pct(l_b), 2)} % real) guardado en {ok} sesiones de cinta de {y_b}."
                    st.rerun()

st.caption("Datos leídos en directo de la API de intervals.icu con tu clave personal. Duplicados (misma hora, deporte y duración) se cuentan una vez.")

if SEC == "mat":
    # ─────────────────────────── Material ───────────────────────────
    st.subheader("Material · zapatillas")
    if st.session_state.get("mat_msg"):
        st.success(st.session_state.pop("mat_msg"))
    if st.session_state.get("mat_warn"):
        st.warning(st.session_state.pop("mat_warn"))

    shoes, gear_err = load_gear()
    if gear_err:
        st.error(f"No se pudo leer el material de intervals.icu: {gear_err}")
    hist = load_hist(shoes)
    shoe_hist = hist[hist["sport"].isin(list(SHOE_SPORTS))] if len(hist) else hist
    SB = shoe_table(shoes, hist)
    shoe_name = dict(zip(SB["id"], SB["name"])) if len(SB) else {}
    shoe_color = dict(zip(SB["id"], SB["color"])) if len(SB) else {}

    def nn(v):
        """None si el valor está vacío (None/NaN/NaT)."""
        return None if v is None or (not isinstance(v, (str, dt.date)) and pd.isna(v)) else v

    def pct_color(p):
        p = nn(p)
        return MUTED if p is None else (RED if p >= 100 else ORANGE if p >= 80 else GREEN)

    def photo_html(url: str, badge: str = "", badge_c: str = "") -> str:
        b_ = f'<span class="st" style="--c:{badge_c};--o:{on(badge_c)}">{badge}</span>' if badge else ""
        if url:  # imagen como fondo: si no carga, queda visible el icono de detrás
            u = _html.escape(url, quote=True).replace("'", "%27").replace("(", "%28").replace(")", "%29")
            return f'<div class="ph no"><span>👟</span><div class="im" style="background-image:url(\'{u}\')"></div>{b_}</div>'
        return f'<div class="ph no">👟{b_}</div>'

    vista = st.segmented_control("Vista material", ["Resumen", "Zapatillas", "Asignar a actividades"], default="Resumen",
                                 key="mat_view", label_visibility="collapsed") or "Resumen"

    # ═══════════════════════════ Resumen y análisis ═══════════════════════════
    if vista == "Resumen":
        if not len(SB):
            st.info("No hay zapatillas en intervals.icu. Crea la primera en «Zapatillas» o ejecuta migrar_material.py.")
        else:
            PERM = ["90 días", "12 meses", f"Temporada {year}", "Todo", "Personalizado"]
            per_m = st.segmented_control("Periodo material", PERM, default="Todo", key="mt_per",
                                         label_visibility="collapsed") or "Todo"
            d_min_m = shoe_hist["date"].min() if len(shoe_hist) else today
            if per_m == "90 días":
                m_from, m_to = today - dt.timedelta(days=89), today
            elif per_m == "12 meses":
                m_from, m_to = today - dt.timedelta(days=364), today
            elif per_m.startswith("Temporada"):
                m_from, m_to = dt.date(year, 1, 1), min(dt.date(year, 12, 31), today)
            elif per_m == "Personalizado":
                dc1, dc2, _ = st.columns([1, 1, 2])
                with dc1:
                    m_from = st.date_input("Desde", value=max(d_min_m, today - dt.timedelta(days=180)), min_value=d_min_m,
                                           max_value=today, format="DD/MM/YYYY", key="mt_from")
                with dc2:
                    m_to = st.date_input("Hasta", value=today, min_value=d_min_m, max_value=today, format="DD/MM/YYYY", key="mt_to")
                if m_from > m_to:
                    m_from, m_to = m_to, m_from
            else:
                m_from, m_to = d_min_m, today
            fc1, fc2, fc3, fc4 = st.columns([1, 2, 1.3, 0.5], vertical_alignment="bottom")
            with fc1:
                est = st.pills("Estado", ["Activas", "Retiradas"], selection_mode="multi", default=["Activas"], key="mt_est") or []
            with fc2:
                tipos_m = st.pills("Tipo de actividad", ["Carrera", "Trail", "Cinta", "Caminata"], selection_mode="multi",
                                   default=["Carrera", "Trail", "Cinta", "Caminata"], key="mt_tipo") or []
            SORT_M = ["Último uso", "Km totales", "Km en el periodo", "% del límite", "Fecha de compra", "Nombre"]
            with fc3:
                ord_m = st.selectbox("Ordenar por", SORT_M, key="mt_sort",
                                     help="Último uso: de la usada más recientemente a la que menos; a igual fecha, más km primero.")
            with fc4:
                asc_m = st.toggle("↑", key="mt_asc", help="Orden ascendente (por defecto, descendente; nombre de la A a la Z)")
            sports_sel = [s_ for s_, t_ in SHOE_SPORTS.items() if t_ in tipos_m]
            SBf = SB[(SB["ret"] & ("Retiradas" in est)) | (~SB["ret"] & ("Activas" in est))]
            per_txt_m = f"{m_from.strftime('%d/%m/%y')} – {m_to.strftime('%d/%m/%y')}"
            act_p = shoe_hist[(shoe_hist["date"] >= m_from) & (shoe_hist["date"] <= m_to) & shoe_hist["sport"].isin(sports_sel)]
            # Orden de la galería, la tabla y los gráficos (por defecto: último uso y km, de más reciente a menos)
            _kmp = act_p.groupby("gear_id")["km"].sum() if len(act_p) else pd.Series(dtype=float)
            SBf = SBf.assign(_kmp=SBf["id"].map(_kmp).fillna(0.0), _pctv=SBf["pct"].fillna(-1.0))
            _by = {"Último uso": (["_last", "km"], False), "Km totales": (["km", "_last"], False),
                   "Km en el periodo": (["_kmp", "km"], False), "% del límite": (["_pctv", "km"], False),
                   "Fecha de compra": (["_compra", "_last"], False), "Nombre": (["_nm"], True)}[ord_m]
            _asc = (not _by[1]) if asc_m else _by[1]
            SBf = SBf.sort_values(_by[0], ascending=_asc, na_position="last", kind="stable")
            act_ps = act_p[act_p["gear_id"].isin(list(SBf["id"]))]

            # Indicadores
            n_act, n_ret = int((~SB["ret"]).sum()), int(SB["ret"].sum())
            alerts = SB[~SB["ret"] & SB["pct"].notna() & (SB["pct"] >= 80)]
            con_zap = act_p["gear_id"].isin(list(shoe_name)).mean() * 100 if len(act_p) else 0
            cards([
                ("Zapatillas activas", GOLD, fnum(n_act), "", [f"{n_ret} retiradas"]),
                ("Km con zapatilla", INK, fnum(act_ps["km"].sum(), 1), "km", [per_txt_m]),
                ("Actividades", GLACIER, fnum(len(act_ps)), "", [f"{fnum(con_zap)} % de las del periodo tienen zapatilla"]),
                ("Avisos de cambio", RED if (alerts["pct"] >= 100).any() else ORANGE if len(alerts) else GREEN, fnum(len(alerts)), "",
                 ["≥ 80 % del límite de km" if len(alerts) else "ninguna cerca del límite"]),
            ])
            for _, r_ in alerts.sort_values("pct", ascending=False).iterrows():
                c_ = pct_color(r_["pct"])
                txt = "ha superado su límite" if r_["pct"] >= 100 else "está cerca de su límite"
                st.markdown(f'<div class="reading" style="--c:{c_}"><b>{_html.escape(r_["name"])}</b> {txt}: '
                            f'{fnum(r_["km"])} de {fnum(r_["lim"])} km ({fnum(r_["pct"])} %).</div>', unsafe_allow_html=True)

            # Galería
            cards_html = ['<div class="shoes">']
            for _, r_ in SBf.iterrows():
                badge, bc = ("Retirada", MUTED) if r_["ret"] else ("", "")
                bar = ""
                if nn(r_["lim"]):
                    pc = r_["pct"]
                    bar = (f'<div class="bar"><span style="width:{min(100, pc):.0f}%;--c:{pct_color(pc)}"></span></div>'
                           f'<div class="ln">{fnum(pc)} % de {fnum(r_["lim"])} km</div>')
                last_txt = r_["last"].strftime("%d/%m/%y") if nn(r_["last"]) else "—"
                cards_html.append(
                    f'<div class="shoe{" ret" if r_["ret"] else ""}">{photo_html(r_["foto"], badge, bc)}'
                    f'<div class="br"><span style="color:{r_["color"]}">●</span> {_html.escape(r_["marca"] or "")}</div>'
                    f'<div class="nm">{_html.escape(r_["modelo"])}</div>'
                    f'<div class="km">{fnum(r_["km"])}<small>km</small></div>'
                    f'<div class="ln">{r_["n"]} act. · {fnum(r_["h"])} h · {fnum(r_["dp"])} m D+</div>'
                    f'<div class="ln">Compra {r_["compra"].year if nn(r_["compra"]) else "—"} · último uso {last_txt}</div>{bar}</div>')
            cards_html.append("</div>")
            if len(SBf):
                st.markdown("".join(cards_html), unsafe_allow_html=True)
            else:
                st.info("No hay zapatillas con ese estado.")

            if not len(act_ps):
                st.info(f"No hay actividades con zapatilla entre {per_txt_m} para los filtros elegidos.")
            else:
                # Tabla resumen del periodo
                st.subheader("Uso en el periodo")
                TIP = ["Carrera", "Trail", "Cinta", "Caminata"]
                g_ = act_ps.assign(tipo=act_ps["sport"].map(SHOE_SPORTS))
                runs_ = g_[g_["sport"].isin(["Run", "TrailRun", "VirtualRun"])]
                tb = pd.DataFrame({
                    "Zapatilla": [shoe_name[i] for i in SBf["id"]],
                    "Km": [g_.loc[g_["gear_id"] == i, "km"].sum() for i in SBf["id"]],
                    "D+": [g_.loc[g_["gear_id"] == i, "dp"].sum() for i in SBf["id"]],
                    "D−": [g_.loc[(g_["gear_id"] == i) & ~g_["sport"].isin(CINTA), "dm"].sum() for i in SBf["id"]],
                    "Horas": [g_.loc[g_["gear_id"] == i, "secs"].sum() / 3600 for i in SBf["id"]],
                    "Act.": [int((g_["gear_id"] == i).sum()) for i in SBf["id"]],
                    **{t_: [g_.loc[(g_["gear_id"] == i) & (g_["tipo"] == t_), "km"].sum() for i in SBf["id"]] for t_ in TIP},
                    "Ritmo": [(runs_.loc[runs_["gear_id"] == i, "secs"].sum() / runs_.loc[runs_["gear_id"] == i, "km"].sum())
                              if runs_.loc[runs_["gear_id"] == i, "km"].sum() > 0 else np.nan for i in SBf["id"]],
                    "% límite": list(SBf["pct"]),
                })
                tb = tb[tb["Act."] > 0].sort_values("Km", ascending=False)
                tot = pd.DataFrame([{"Zapatilla": "Total", "Km": tb["Km"].sum(), "D+": tb["D+"].sum(), "D−": tb["D−"].sum(), "Horas": tb["Horas"].sum(),
                                     "Act.": tb["Act."].sum(), **{t_: tb[t_].sum() for t_ in TIP},
                                     "Ritmo": np.nan, "% límite": np.nan}])
                tb_all = pd.concat([tb, tot], ignore_index=True)
                num_ = lambda d, u="": (lambda v: "" if pd.isna(v) else f"{fnum(v, d)}{u}")  # noqa: E731
                pct_f = lambda v: ("" if pd.isna(v) else f'<span style="color:{pct_color(v)}">{fnum(v)} %</span>')  # noqa: E731
                pace_f2 = lambda p: f"{int(p // 60)}:{int(round(p % 60)) % 60:02d}" if pd.notna(p) and p > 0 else ""  # noqa: E731
                html_table(tb_all, left={"Zapatilla"}, total_last=True, group_start={"Carrera"},
                           groups=[("", 6, ""), ("Km por tipo", 4, "g"), ("", 2, "")],
                           fmt={"Km": num_(1), "D+": num_(0), "D−": num_(0), "Horas": num_(1), "Act.": num_(0), **{t_: num_(1) for t_ in TIP},
                                "Ritmo": pace_f2, "% límite": pct_f},
                           heat={"Km": (float(max(1, tb["Km"].max())), rgb(GOLD))})

                # km acumulados por zapatilla (vida completa, con km previos), recortado al periodo
                st.subheader("Km acumulados por zapatilla")
                f_cum = go.Figure()
                for _, r_ in SBf.iterrows():
                    a_ = shoe_hist[shoe_hist["gear_id"] == r_["id"]].sort_values("ts")
                    if not len(a_):
                        continue
                    cum = a_.groupby("date")["km"].sum().cumsum() + r_["km_prev"]
                    xs = [pd.Timestamp(d) for d in cum.index]
                    f_cum.add_scatter(x=xs, y=cum.values, mode="lines", name=r_["name"], line=dict(color=r_["color"], width=2, shape="hv"),
                                      hovertemplate="%{x|%d/%m/%y} · %{y:,.0f} km<extra>" + _html.escape(r_["name"]) + "</extra>")
                    if nn(r_["lim"]):
                        f_cum.add_scatter(x=[xs[0], pd.Timestamp(today)], y=[r_["lim"], r_["lim"]], mode="lines", showlegend=False,
                                          line=dict(color=r_["color"], width=1, dash="dash"), opacity=.6, hoverinfo="skip")
                f_cum.update_xaxes(range=[pd.Timestamp(m_from) - pd.Timedelta(days=3), pd.Timestamp(m_to) + pd.Timedelta(days=3)])
                f_cum.update_yaxes(ticksuffix=" km")
                st.markdown('<span class="note">Incluye los km previos de cada zapatilla. La línea discontinua es su límite de km.</span>',
                            unsafe_allow_html=True)
                st.plotly_chart(plot_layout(f_cum, 330), width="stretch", theme=None)

                # km por mes y zapatilla
                st.subheader("Km por mes y zapatilla")
                g_["mes"] = g_["ts"].dt.to_period("M").dt.to_timestamp()
                pm = g_.groupby(["mes", "gear_id"])["km"].sum().unstack(fill_value=0)
                f_m = go.Figure()
                for gid in [i for i in SBf["id"] if i in pm.columns]:
                    f_m.add_bar(x=pm.index, y=pm[gid], name=shoe_name[gid], marker_color=shoe_color[gid],
                                hovertemplate="%{x|%b %Y} · %{y:.0f} km<extra>" + _html.escape(shoe_name[gid]) + "</extra>")
                f_m.update_layout(barmode="stack")
                f_m.update_yaxes(ticksuffix=" km")
                st.plotly_chart(plot_layout(f_m, 300), width="stretch", theme=None)

                cA_, cB_ = st.columns(2)
                order_ = list(tb["Zapatilla"])[::-1]
                with cA_:
                    st.subheader("Reparto por tipo de actividad")
                    TCOL = {"Carrera": INK, "Trail": GOLD, "Cinta": GLACIER, "Caminata": ORANGE}
                    f_t = go.Figure()
                    for t_ in TIP:
                        f_t.add_bar(y=order_, x=[float(tb.loc[tb["Zapatilla"] == z, t_].iloc[0]) for z in order_], name=t_, orientation="h",
                                    marker_color=TCOL[t_], hovertemplate="%{y} · " + t_ + ": %{x:.0f} km<extra></extra>")
                    f_t.update_xaxes(ticksuffix=" km")
                    plot_layout(f_t, max(260, 34 * len(order_) + 110))
                    f_t.update_layout(barmode="stack", margin=dict(t=44), legend=dict(y=1.0, yanchor="bottom"))
                    st.plotly_chart(f_t, width="stretch", theme=None)
                with cB_:
                    st.subheader("D+ por zapatilla")
                    id_by_name = {v: k for k, v in shoe_name.items()}
                    f_d = go.Figure()
                    f_d.add_bar(y=order_, x=[float(tb.loc[tb["Zapatilla"] == z, "D+"].iloc[0]) for z in order_], orientation="h",
                                marker_color=[shoe_color[id_by_name[z]] for z in order_],
                                text=[fnum(float(tb.loc[tb["Zapatilla"] == z, "D+"].iloc[0])) for z in order_], textposition="outside",
                                textfont=dict(color=INK, size=11), cliponaxis=False, hovertemplate="%{y} · %{x:,.0f} m<extra></extra>")
                    dmax_ = float(tb["D+"].max()) if len(tb) else 1.0
                    f_d.update_xaxes(ticksuffix=" m", range=[0, max(1.0, dmax_) * 1.22])
                    plot_layout(f_d, max(260, 34 * len(order_) + 110), legend=False)
                    f_d.update_layout(margin=dict(t=44))
                    st.plotly_chart(f_d, width="stretch", theme=None)

    # ═══════════════════════════ Alta y edición ═══════════════════════════
    elif vista == "Zapatillas":
        NEW = "__new__"
        ids_ = [NEW] + list(SB["id"]) if len(SB) else [NEW]
        lab_ = {NEW: "➕ Nueva zapatilla", **{r_["id"]: r_["name"] + (" · retirada" if r_["ret"] else "") for _, r_ in SB.iterrows()}}
        if st.session_state.get("mt_sel_next") in ids_:      # tras guardar, mostrar la zapatilla guardada
            st.session_state["mt_sel"] = st.session_state.pop("mt_sel_next")
        gsel = st.selectbox("Zapatilla", ids_, format_func=lambda i: lab_.get(i, i), key="mt_sel",
                            index=1 if len(ids_) > 1 else 0)
        cur = {k: nn(v) for k, v in SB[SB["id"] == gsel].iloc[0].to_dict().items()} if gsel != NEW else {}
        k_ = f"mf_{gsel}_"
        e1, e2 = st.columns(2)
        with e1:
            f_marca = st.text_input("Marca", value=cur.get("marca", ""), key=k_ + "marca")
            f_modelo = st.text_input("Modelo", value=cur.get("modelo", ""), key=k_ + "modelo")
            f_compra = st.date_input("Fecha de compra", value=cur.get("compra"), min_value=dt.date(2010, 1, 1), max_value=today,
                                     format="DD/MM/YYYY", key=k_ + "compra")
            f_prev = st.number_input("Km previos", min_value=0.0, step=10.0, format="%.1f", value=float(cur.get("km_prev") or 0.0),
                                     help="Km hechos antes de tener las actividades en intervals.icu. Se suman a los km de la zapatilla.",
                                     key=k_ + "prev")
        with e2:
            f_lim = st.number_input("Límite de km (aviso de cambio)", min_value=0.0, step=50.0, format="%.0f",
                                    value=float(cur["lim"]) if cur.get("lim") else None, placeholder="sin aviso", key=k_ + "lim")
            f_ret = st.toggle("Retirada", value=bool(cur.get("ret")), key=k_ + "ret")
            f_retd = (st.date_input("Fecha de retirada", value=cur.get("retirada") or today, min_value=dt.date(2010, 1, 1),
                                    max_value=today, format="DD/MM/YYYY", key=k_ + "retd") if f_ret else None)
            f_libre = st.text_area("Notas", value=cur.get("libre", ""), height=90, key=k_ + "libre")
        ph1, ph2 = st.columns([3, 1], vertical_alignment="bottom")
        with ph1:
            f_foto = st.text_input("URL de la foto", value=cur.get("foto", ""), placeholder="https://…/zapatilla.jpg", key=k_ + "foto")
        with ph2:
            st.link_button("Buscar foto", f"https://www.google.com/search?tbm=isch&q={quote_plus((f_marca + ' ' + f_modelo + ' zapatilla').strip())}",
                           width="stretch")
        pv1, pv2 = st.columns([1, 3])
        with pv1:
            st.markdown(f'<div class="shoe" style="max-width:190px">{photo_html(f_foto.strip())}</div>', unsafe_allow_html=True)
        with pv2:
            if f_foto.strip():
                if not f_foto.strip().startswith("http"):
                    st.warning("La URL debe empezar por http:// o https://")
                elif not image_ok(f_foto.strip()):
                    st.warning("No he podido comprobar que la URL sea una imagen. Puedes guardarla igualmente; si no carga, se mostrará el icono.")
                else:
                    st.caption("✓ La URL devuelve una imagen.")
            if cur:
                st.caption(f"{cur['n']} actividades · {fnum(cur['km'])} km en total" + (f" (incluye {fnum(cur['km_prev'])} km previos)" if cur["km_prev"] else ""))

        if st.button("Revisar cambios", type="primary", key="mt_review"):
            if not f_marca.strip() or not f_modelo.strip():
                st.error("La marca y el modelo son obligatorios.")
            else:
                st.session_state["mat_pending"] = dict(
                    kind="gear", gid=None if gsel == NEW else gsel, name=f"{f_marca.strip()} {f_modelo.strip()}",
                    purchased=f_compra.isoformat() if f_compra else None, retired=f_retd.isoformat() if f_retd else None,
                    notes=build_notes(f_marca, f_modelo, f_foto, float(f_prev or 0), f_libre),
                    lim=float(f_lim) if f_lim else None)
        pend = st.session_state.get("mat_pending")
        if pend and pend.get("kind") == "gear" and (pend["gid"] or NEW) == gsel:
            with st.container(border=True):
                st.markdown(f"**{'Crear' if not pend['gid'] else 'Actualizar'} en intervals.icu:** {_html.escape(pend['name'])}")
                st.markdown(f"- Compra: {pend['purchased'] or '—'} · Retirada: {pend['retired'] or ('no (se quita la retirada)' if cur.get('ret') else 'no')}\n"
                            f"- Límite de km: {fnum(pend['lim']) + ' km' if pend['lim'] else 'sin aviso'}\n"
                            f"- Notas:\n```\n{pend['notes']}\n```")
                b1, b2, _ = st.columns([1.2, 1, 3])
                if b1.button("Confirmar y guardar", type="primary", key="mt_conf"):
                    body = {"type": "Shoes", "name": pend["name"], "notes": pend["notes"],
                            "purchased": f"{pend['purchased']}T00:00:00" if pend["purchased"] else None,
                            "retired": f"{pend['retired']}T00:00:00" if pend["retired"] else None}
                    try:
                        if demo:
                            store = st.session_state["demo_gear"]
                            if pend["gid"]:
                                g0 = next(g for g in store if g["id"] == pend["gid"])
                            else:
                                g0 = {"id": f"gd{len(store) + 1}_{random.randint(100, 999)}", "reminders": []}
                                store.append(g0)
                            g0.update(body)
                            rem0 = next((r for r in g0["reminders"] if (r.get("distance") or 0) > 0), None)
                            if pend["lim"]:
                                if rem0:
                                    rem0["distance"] = pend["lim"] * 1000
                                else:
                                    g0["reminders"].append(dict(id=random.randint(1000, 9999), name="Límite de km", distance=pend["lim"] * 1000))
                            elif rem0:
                                g0["reminders"].remove(rem0)
                            gid_saved = g0["id"]
                        else:
                            if pend["gid"]:
                                g0 = next(g for g in shoes if g["id"] == pend["gid"])
                                g_new = icu_write("PUT", f"/athlete/{athlete}/gear/{pend['gid']}", {**g0, **body}) or g0
                                # intervals.icu ignora los campos a null en un PUT: «retired": null» no reactiva la
                                # zapatilla. Si había que quitar la retirada y sigue puesta, se prueba con cadena vacía.
                                if not pend["retired"] and (g_new or {}).get("retired"):
                                    try:
                                        g_new = icu_write("PUT", f"/athlete/{athlete}/gear/{pend['gid']}", {"retired": ""}) or g_new
                                    except Exception:  # noqa: BLE001
                                        pass
                                    try:
                                        g_new = next((g for g in icu_write("GET", f"/athlete/{athlete}/gear") or []
                                                      if str(g.get("id")) == str(pend["gid"])), g_new)
                                    except Exception:  # noqa: BLE001
                                        pass
                                    if (g_new or {}).get("retired"):
                                        st.session_state["mat_warn"] = (
                                            f"intervals.icu no ha quitado la fecha de retirada de «{pend['name']}» "
                                            f"(sigue retirada desde {str(g_new['retired'])[:10]}). Quítala desde la web de "
                                            "intervals.icu, en la ficha de la zapatilla, y pulsa «Actualizar datos».")
                            else:
                                g0 = {}
                                g_new = icu_write("POST", f"/athlete/{athlete}/gear", body)
                            gid_saved = (g_new or {}).get("id") or pend["gid"]
                            rem0, _l = km_limit(g0)
                            if pend["lim"]:
                                if rem0:
                                    icu_write("PUT", f"/athlete/{athlete}/gear/{gid_saved}/reminder/{rem0['id']}",
                                              {**rem0, "distance": pend["lim"] * 1000})
                                else:
                                    icu_write("POST", f"/athlete/{athlete}/gear/{gid_saved}/reminder",
                                              {"name": "Límite de km", "distance": pend["lim"] * 1000})
                            elif rem0:
                                icu_write("DELETE", f"/athlete/{athlete}/gear/{gid_saved}/reminder/{rem0['id']}")
                            icu_write("GET", f"/athlete/{athlete}/gear/{gid_saved}/calc")
                            st.cache_data.clear()
                        st.session_state.pop("mat_pending", None)
                        st.session_state["mt_sel_next"] = gid_saved
                        st.session_state["mat_msg"] = f"Guardada «{pend['name']}» en intervals.icu." if not demo else f"Guardada «{pend['name']}» (DEMO)."
                        st.rerun()
                    except Exception as e:  # noqa: BLE001
                        st.error(f"No se pudo guardar: {e}")
                if b2.button("Cancelar", key="mt_cancel"):
                    st.session_state.pop("mat_pending", None)
                    st.rerun()

    # ═══════════════════════════ Asignar a actividades ═══════════════════════════
    else:
        if not len(SB):
            st.info("Primero crea alguna zapatilla en «Zapatillas».")
        else:
            a1, a2, a3 = st.columns([2.1, 2, 1], vertical_alignment="bottom")
            with a1:
                per_a = st.segmented_control("Periodo", ["30 días", "90 días", f"Año {year}", "Todo"], default="90 días",
                                             key="mt_as_per") or "90 días"
            with a2:
                tip_a = st.pills("Tipo", ["Carrera", "Trail", "Cinta", "Caminata"], selection_mode="multi",
                                 default=["Carrera", "Trail", "Cinta", "Caminata"], key="mt_as_tipo") or []
            with a3:
                solo_sin = st.toggle("Solo sin zapatilla", value=False, key="mt_as_none")
            la = shoe_hist[shoe_hist["sport"].isin([s_ for s_, t_ in SHOE_SPORTS.items() if t_ in tip_a])]
            if per_a == "30 días":
                la = la[la["date"] >= today - dt.timedelta(days=30)]
            elif per_a == "90 días":
                la = la[la["date"] >= today - dt.timedelta(days=90)]
            elif per_a.startswith("Año"):
                la = la[la["ts"].dt.year == year]
            if solo_sin:
                la = la[~la["gear_id"].isin(list(shoe_name))]
            la = la.sort_values("ts", ascending=False)
            n_sin = int((~la["gear_id"].isin(list(shoe_name))).sum())
            st.markdown(f'<div class="note">{len(la)} actividades · {n_sin} sin zapatilla</div>', unsafe_allow_html=True)
            if not len(la):
                st.info("No hay actividades con esos filtros.")
            else:
                PPA = 20
                npg = max(1, math.ceil(len(la) / PPA))
                sig_a = f"{per_a}|{','.join(tip_a)}|{solo_sin}|{len(la)}"
                if st.session_state.get("mt_as_sig") != sig_a:
                    st.session_state["mt_as_sig"] = sig_a
                    st.session_state["mt_as_page"] = 1
                pg = min(max(1, int(st.session_state.get("mt_as_page", 1))), npg)
                if npg > 1:
                    q1, q2, q3, _ = st.columns([1, 1.6, 1, 3], vertical_alignment="center")
                    with q1:
                        if st.button("◀ Anterior", disabled=pg <= 1, width="stretch", key="mt_as_prev"):
                            st.session_state["mt_as_page"] = pg - 1
                            st.rerun()
                    with q2:
                        st.markdown(f'<div class="note" style="text-align:center">Página <b style="color:{INK}">{pg}</b> de {npg}</div>',
                                    unsafe_allow_html=True)
                    with q3:
                        if st.button("Siguiente ▶", disabled=pg >= npg, width="stretch", key="mt_as_next"):
                            st.session_state["mt_as_page"] = pg + 1
                            st.rerun()
                rows_a = la.iloc[(pg - 1) * PPA: pg * PPA]
                act_ids = list(SB.loc[~SB["ret"], "id"])
                CWA = [1.0, 2.6, 0.9, 0.8, 0.8, 2.3]
                ha = st.columns(CWA, vertical_alignment="center")
                for col, (t, r) in zip(ha, [("Fecha", ""), ("Actividad", ""), ("Tipo", ""), ("Km", "r"), ("D+", "r"), ("Zapatilla", "")]):
                    col.markdown(f'<div class="chd {r}">{t}</div>', unsafe_allow_html=True)
                with st.form("mat_assign_form", border=False):
                    sel_a = {}
                    for i, (_, rw) in enumerate(rows_a.iterrows()):
                        cur_g = rw["gear_id"] if rw["gear_id"] in shoe_name else ""
                        opts = [""] + act_ids + ([cur_g] if cur_g and cur_g not in act_ids else [])
                        with st.container(key=f"crow{'E' if i % 2 else 'O'}_m{i}"):
                            cc = st.columns(CWA, vertical_alignment="center")
                            cc[0].markdown(f'<div class="ctd" style="font-family:IBM Plex Mono,monospace">{rw["ts"].strftime("%d/%m/%y")}</div>',
                                           unsafe_allow_html=True)
                            cc[1].markdown(f'<div class="ctd" title="{_html.escape(rw["name"])}">{_html.escape(rw["name"])}</div>',
                                           unsafe_allow_html=True)
                            cc[2].markdown(f'<div class="ctd">{SHOE_SPORTS.get(rw["sport"], rw["sport"])}</div>', unsafe_allow_html=True)
                            cc[3].markdown(f'<div class="ctd r">{fnum(rw["km"], 1)}</div>', unsafe_allow_html=True)
                            cc[4].markdown(f'<div class="ctd r">{fnum(rw["dp"])}</div>', unsafe_allow_html=True)
                            sel_a[rw["id"]] = (cur_g, cc[5].selectbox(
                                "Zapatilla", opts, index=opts.index(cur_g), label_visibility="collapsed", key=f"mas_{rw['id']}",
                                format_func=lambda i: "— sin zapatilla —" if not i else shoe_name.get(i, i)))
                    sub_a = st.form_submit_button("Revisar cambios", type="primary")
                if sub_a:
                    ch = [(aid, old, new) for aid, (old, new) in sel_a.items() if (old or "") != (new or "")]
                    if not ch:
                        st.info("No hay cambios que guardar.")
                        st.session_state.pop("mat_pending", None)
                    else:
                        st.session_state["mat_pending"] = dict(kind="assign", changes=ch)
                pend = st.session_state.get("mat_pending")
                if pend and pend.get("kind") == "assign":
                    info_ = la.set_index("id")
                    with st.container(border=True):
                        n_ch = len(pend["changes"])
                        st.markdown(f"**Vas a cambiar la zapatilla de {n_ch} actividad{'es' if n_ch != 1 else ''}:**")
                        st.markdown("\n".join(
                            f"- {info_.loc[aid, 'ts'].strftime('%d/%m/%y') if aid in info_.index else aid} · "
                            f"{_html.escape(str(info_.loc[aid, 'name'])) if aid in info_.index else ''}: "
                            f"{shoe_name.get(old, '—') if old else '—'} → **{shoe_name.get(new, '—') if new else 'sin zapatilla'}**"
                            for aid, old, new in pend["changes"]))
                        b1, b2, _ = st.columns([1.2, 1, 3])
                        if b1.button("Confirmar y guardar", type="primary", key="mt_as_conf"):
                            ov = dict(st.session_state.get("gear_overrides", {}))
                            ok, fails, touched = 0, [], set()
                            for aid, old, new in pend["changes"]:
                                try:
                                    if not demo:
                                        icu_write("PUT", f"/activity/{aid}", {"gear": {"id": new} if new else None})
                                    ov[aid] = new or None
                                    touched |= {x for x in (old, new) if x}
                                    ok += 1
                                except Exception as e:  # noqa: BLE001
                                    fails.append(f"{aid}: {e}")
                            if not demo:
                                for gid in touched:
                                    try:
                                        icu_write("GET", f"/athlete/{athlete}/gear/{gid}/calc")
                                    except Exception as e:  # noqa: BLE001
                                        fails.append(f"recalcular {shoe_name.get(gid, gid)}: {e}")
                                st.cache_data.clear()
                            st.session_state["gear_overrides"] = ov
                            st.session_state.pop("mat_pending", None)
                            if fails:
                                st.error("Algunos cambios no se guardaron:\n\n" + "\n\n".join(fails))
                            if ok:
                                st.session_state["mat_msg"] = (f"Zapatilla actualizada en {ok} actividad{'es' if ok != 1 else ''}"
                                                               + (" (DEMO)." if demo else "."))
                                st.rerun()
                        if b2.button("Cancelar", key="mt_as_cancel"):
                            st.session_state.pop("mat_pending", None)
                            st.rerun()

if SEC == "cmp":
    if "hist" not in globals():
        shoes, gear_err = load_gear()
        hist = load_hist(shoes)
    # ─────────────────────────── Comparar dos actividades ───────────────────────────
    # (usa `hist`, el histórico completo cargado en la pestaña Material)
    CMP_SPORTS = {"Trail": ["TrailRun"], "Carrera": ["Run"], "Caminata": ["Hike", "Walk"]}
    hms = lambda s_: "—" if s_ is None or pd.isna(s_) else f"{int(s_ // 3600)}:{int(s_ % 3600 // 60):02d}:{int(s_ % 60):02d}"  # noqa: E731
    mmss = lambda s_: "—" if s_ is None or pd.isna(s_) or s_ <= 0 else f"{int(s_ // 60)}:{int(round(s_ % 60)) % 60:02d}"  # noqa: E731

    def sgn_time(d_):
        if d_ is None or pd.isna(d_):
            return "—"
        return ("−" if d_ < 0 else "+") + mmss(abs(d_)) if abs(d_) >= 1 else "0:00"

    all_cmp = hist[hist["sport"].isin(sum(CMP_SPORTS.values(), []))].sort_values("ts", ascending=False) if len(hist) else hist
    if not len(all_cmp):
        st.info("No hay actividades de carrera, trail o caminata para comparar.")
    else:
        f1_, f2_ = st.columns([2, 1])
        with f1_:
            tip_c = st.pills("Tipo", list(CMP_SPORTS), selection_mode="multi", default=["Trail"], key="cmp_tipo") or list(CMP_SPORTS)
        years_c = sorted(all_cmp["ts"].dt.year.unique().tolist(), reverse=True)
        with f2_:
            if st.session_state.get("cmp_year") not in ["Todos"] + years_c:     # por defecto, el año actual (o el último con datos)
                st.session_state["cmp_year"] = today.year if today.year in years_c else (years_c[0] if years_c else "Todos")
            yr_c = st.selectbox("Año de la carrera actual", ["Todos"] + years_c, key="cmp_year")
        sp_sel = sum((CMP_SPORTS[t_] for t_ in tip_c), [])
        pool = all_cmp[all_cmp["sport"].isin(sp_sel)]
        pool_a = pool if yr_c == "Todos" else pool[pool["ts"].dt.year == yr_c]
        info_c = all_cmp.set_index("id")
        lab_c = lambda i: (f"{info_c.loc[i, 'ts']:%d/%m/%y} · {str(info_c.loc[i, 'name'])[:34]} · "  # noqa: E731
                           f"{fnum(info_c.loc[i, 'km'], 1)} km · {fnum(info_c.loc[i, 'dp'])} m")
        # Igual que lab_c, con el tiempo en movimiento detrás de la distancia (selectores de las dos carreras)
        lab_t = lambda i: (f"{info_c.loc[i, 'ts']:%d/%m/%y} · {str(info_c.loc[i, 'name'])[:34]} · "  # noqa: E731
                           f"{fnum(info_c.loc[i, 'km'], 1)} km · {hms(info_c.loc[i, 'secs'])} · {fnum(info_c.loc[i, 'dp'])} m")
        if not len(pool_a):
            st.info("No hay actividades con esos filtros.")
            st.stop()
        opts_a = list(pool_a["id"])
        if st.session_state.get("cmp_a") not in opts_a:
            st.session_state.pop("cmp_a", None)

        def _swap():
            a_, b_ = st.session_state.get("cmp_a"), st.session_state.get("cmp_b")
            if a_ and b_:
                st.session_state["cmp_a"], st.session_state["cmp_b"] = b_, a_
                st.session_state["cmp_b_for"] = b_           # mantener la carrera a comparar intercambiada
                st.session_state["cmp_year"] = "Todos"

        s1_, s2_ = st.columns([4, 1.3], vertical_alignment="bottom")
        with s1_:
            act_a = st.selectbox("Carrera actual", opts_a, format_func=lab_t, key="cmp_a")
        with s2_:
            st.button("⇅ Intercambiar", on_click=_swap, width="stretch", key="cmp_swap")
        ra = info_c.loc[act_a]

        # Rutas parecidas a la carrera actual (distancia ±5 %, D+ ±7 %), comprobadas con GPS
        sim_pool = all_cmp[(all_cmp["id"] != act_a) & (all_cmp["km"].between(ra["km"] * .95, ra["km"] * 1.05))
                           & (all_cmp["dp"].between(ra["dp"] * .93, ra["dp"] * 1.07))].copy()

        def load_df(aid):
            r_ = info_c.loc[aid]
            return act_df(aid, r_["km"], r_["dp"], r_["secs"])

        with st.spinner("Leyendo los datos por segundo…"):
            df_a, src_a = load_df(act_a)
            if len(sim_pool):
                sim_pool["_k"] = (sim_pool["km"] / ra["km"] - 1).abs() + (sim_pool["dp"] / max(1, ra["dp"]) - 1).abs()
                top_ = sim_pool.nsmallest(6, "_k")
                rec = {}
                for aid in top_["id"]:
                    d_, _src = load_df(aid)
                    sim_ = route_similarity(df_a, d_) if len(df_a) and len(d_) else None
                    rec[aid] = sim_["label"] if sim_ else "sin GPS"
                sim_pool["recorrido"] = sim_pool["id"].map(rec).fillna("sin comprobar")
                sim_pool["_o"] = sim_pool["recorrido"].map({"misma ruta": 0, "parecida": 1, "sin GPS": 2, "sin comprobar": 3, "distinta": 4})
                sim_pool = sim_pool.sort_values(["_o", "ts"], ascending=[True, False])
        if len(sim_pool):
            st.markdown('<div class="note" style="margin:6px 0 2px">Rutas parecidas a la carrera actual (distancia ±5 %, D+ ±7 %; recorrido comprobado con GPS)</div>',
                        unsafe_allow_html=True)
            badge = {"misma ruta": GREEN, "parecida": ORANGE, "distinta": RED, "sin GPS": MUTED, "sin comprobar": MUTED}
            html_table(pd.DataFrame({"Fecha": sim_pool["ts"].dt.strftime("%d/%m/%y").values, "Actividad": sim_pool["name"].values,
                                     "Km": sim_pool["km"].values, "D+": sim_pool["dp"].values, "D−": sim_pool["dm"].values,
                                     "Recorrido": sim_pool["recorrido"].values}),
                       left={"Actividad", "Recorrido"}, max_height=230,
                       fmt={"Km": lambda v: fnum(v, 1), "D+": lambda v: fnum(v), "D−": lambda v: "" if pd.isna(v) else fnum(v),
                            "Actividad": lambda v: (str(v)[:40] + "…") if len(str(v)) > 41 else str(v),
                            "Recorrido": lambda v: f'<span class="chip" style="--c:{badge[v]};--o:{on(badge[v])}">{v}</span>'})
        else:
            st.markdown('<div class="note">No hay otras actividades con distancia ±5 % y D+ ±7 % que la carrera actual.</div>', unsafe_allow_html=True)
        opts_b = list(sim_pool["id"]) + [i for i in pool["id"] if i != act_a and i not in set(sim_pool["id"])]
        if not opts_b:
            st.info("No hay otra actividad con la que comparar.")
            st.stop()
        if (st.session_state.get("cmp_b") not in opts_b or st.session_state.get("cmp_b") == act_a
                or st.session_state.get("cmp_b_for") != act_a):     # al cambiar A, proponer la ruta más parecida
            if not (st.session_state.get("cmp_b_for") == act_a and st.session_state.get("cmp_b") in opts_b):
                st.session_state["cmp_b"] = opts_b[0]
        st.session_state["cmp_b_for"] = act_a
        sim_ids = set(sim_pool["id"])
        act_b = st.selectbox("Carrera a comparar", opts_b, key="cmp_b",
                             format_func=lambda i: ("≈ " if i in sim_ids else "") + lab_t(i))
        rb = info_c.loc[act_b]
        with st.spinner("Leyendo los datos por segundo…"):
            df_b, src_b = load_df(act_b)

        # ── Resumen ──
        st.markdown(f'<div class="note" style="margin-top:8px"><span style="color:{GOLD}">●</span> Carrera actual · {lab_c(act_a)}<br>'
                    f'<span style="color:{GLACIER}">●</span> Carrera a comparar · {lab_c(act_b)}</div>', unsafe_allow_html=True)
        stop_a, stop_b = ra["elapsed"] - ra["secs"], rb["elapsed"] - rb["secs"]

        def dnum(va, vb, d=0, u="", inv=False):
            if pd.isna(va) or pd.isna(vb):
                return "—"
            x = va - vb                                   # actual − comparada
            good = x < 0 if inv else x > 0
            c_ = GREEN if good else RED if abs(x) > 1e-9 else MUTED
            return f'<span style="color:{c_}">{"+" if x > 0 else "−" if x < 0 else ""}{fnum(abs(x), d)}{u}</span>'

        def dtime(va, vb):
            if pd.isna(va) or pd.isna(vb):
                return "—"
            x = va - vb                                   # actual − comparada: negativo = la actual tardó menos
            return f'<span style="color:{GREEN if x < 0 else RED if x > 0 else MUTED}">{sgn_time(x)}</span>'

        pace_a = ra["secs"] / ra["km"] if ra["km"] else np.nan
        pace_b = rb["secs"] / rb["km"] if rb["km"] else np.nan
        summ = pd.DataFrame([
            ("Fecha", f"{ra['ts']:%d/%m/%y}", f"{rb['ts']:%d/%m/%y}", ""),
            ("Reloj", str(ra.get("device") or "—").replace("SUUNTO ", ""), str(rb.get("device") or "—").replace("SUUNTO ", ""), ""),
            ("Distancia", f"{fnum(ra['km'], 2)} km", f"{fnum(rb['km'], 2)} km", dnum(ra["km"], rb["km"], 2, " km")),
            ("D+", f"{fnum(ra['dp'])} m", f"{fnum(rb['dp'])} m", dnum(ra["dp"], rb["dp"], 0, " m")),
            ("D−", f"{fnum(ra['dm'])} m", f"{fnum(rb['dm'])} m", dnum(ra["dm"], rb["dm"], 0, " m")),
            ("Tiempo en movimiento", hms(ra["secs"]), hms(rb["secs"]), dtime(ra["secs"], rb["secs"])),
            ("Tiempo total", hms(ra["elapsed"]), hms(rb["elapsed"]), dtime(ra["elapsed"], rb["elapsed"])),
            ("Tiempo parado", hms(stop_a), hms(stop_b), dtime(stop_a, stop_b)),
            ("Ritmo (min/km)", mmss(pace_a), mmss(pace_b), dtime(pace_a, pace_b)),
            ("FC media", f"{fnum(ra['hr_avg'])} ppm" if pd.notna(ra["hr_avg"]) else "—",
             f"{fnum(rb['hr_avg'])} ppm" if pd.notna(rb["hr_avg"]) else "—", dnum(ra["hr_avg"], rb["hr_avg"], 0, " ppm", inv=True)),
            ("Carga", fnum(ra["load"]), fnum(rb["load"]), dnum(ra["load"], rb["load"], 0, "", inv=True)),
        ], columns=["Métrica", "Actual", "Comparada", "Diferencia"])
        html_table(summ, left={"Métrica"})
        st.markdown('<span class="note">Diferencia = carrera actual − carrera a comparar; en verde, la carrera actual fue mejor.</span>', unsafe_allow_html=True)

        notes_ = []        # «A tener en cuenta»
        if not len(df_a) or not len(df_b):
            falta = " ni de ".join(x for x, d_ in (("la carrera actual", df_a), ("la carrera a comparar", df_b)) if not len(d_))
            st.warning(f"No hay datos por segundo de {falta} (ni en intervals.icu ni en el fichero original): solo se muestra el resumen.")
        else:
            for lab_, d_, r_, src_ in (("la carrera actual", df_a, ra, src_a), ("la carrera a comparar", df_b, rb, src_b)):
                mv = stream_stats(d_)["mov"]
                if r_["secs"] and abs(mv - r_["secs"]) / r_["secs"] > 0.02:
                    notes_.append(f"En {lab_}, el tiempo en movimiento calculado por segundo ({hms(mv)}) difiere más de un 2 % "
                                  f"del de intervals.icu ({hms(r_['secs'])}); los tiempos por tramo pueden desviarse algo.")
                if src_ == "fichero original":
                    notes_.append(f"Los datos por segundo de {lab_} salen del fichero original del reloj (intervals.icu no los devolvió).")

            # ── Bandas de pendiente ──
            SUB_AB = {"A": "Actual", "B": "Comparada"}            # cabeceras «Km|A» → «Actual»
            st.subheader("Por pendiente")
            ba, bb = grade_bands(df_a), grade_bands(df_b)
            vv = lambda r_: r_["vam"] if pd.notna(r_["vam"]) else r_["vdesc"]  # noqa: E731
            bt = pd.DataFrame({
                "Pendiente": ba["band"], "Km|A": ba["km"], "Km|B": bb["km"], "D+|A": ba["dp"], "D+|B": bb["dp"],
                "D−|A": ba["dm"], "D−|B": bb["dm"], "Tiempo|A": ba["mt"], "Tiempo|B": bb["mt"],
                "Ritmo|A": ba["pace"], "Ritmo|B": bb["pace"],
                "VAM / bajada|A": [vv(r_) for _, r_ in ba.iterrows()], "VAM / bajada|B": [vv(r_) for _, r_ in bb.iterrows()],
                "FC|A": ba["hr"], "FC|B": bb["hr"]})
            bt["Δ m/h"] = bt["VAM / bajada|A"] - bt["VAM / bajada|B"]          # actual − comparada
            bt = bt[["Pendiente", "Km|A", "Km|B", "D+|A", "D+|B", "D−|A", "D−|B", "Tiempo|A", "Tiempo|B", "Ritmo|A", "Ritmo|B", "VAM / bajada|A", "VAM / bajada|B", "Δ m/h", "FC|A", "FC|B"]]
            nf = lambda d, u="": (lambda v: "—" if pd.isna(v) else f"{fnum(v, d)}{u}")  # noqa: E731
            dcol = lambda v: "—" if pd.isna(v) else f'<span style="color:{GREEN if v > 0 else RED if v < 0 else MUTED}">{"+" if v > 0 else "−" if v < 0 else ""}{fnum(abs(v))}</span>'  # noqa: E731
            html_table(bt, left={"Pendiente"}, sub=SUB_AB, group_start={"Km|A", "D+|A", "D−|A", "Tiempo|A", "Ritmo|A", "VAM / bajada|A", "FC|A"},
                       groups=[("", 1, ""), ("Km", 2, "g"), ("D+ m", 2, "g"), ("D− m", 2, "g"), ("Tiempo mov.", 2, "g"), ("Ritmo min/km", 2, "g"),
                               ("VAM / bajada m/h", 3, "g"), ("FC media", 2, "g")],
                       fmt={"Km|A": nf(1), "Km|B": nf(1), "D+|A": nf(0), "D+|B": nf(0), "D−|A": nf(0), "D−|B": nf(0), "Tiempo|A": hms, "Tiempo|B": hms, "Ritmo|A": mmss, "Ritmo|B": mmss,
                            "VAM / bajada|A": nf(0), "VAM / bajada|B": nf(0), "Δ m/h": dcol, "FC|A": nf(0), "FC|B": nf(0)})
            st.markdown('<span class="note">En subidas, VAM (metros subidos por hora); en bajadas, metros bajados por hora. '
                        'Δ = actual − comparada; en verde, la carrera actual sube o baja más rápido.</span>', unsafe_allow_html=True)
            g1_, g2_ = st.columns(2)
            with g1_:
                f_v = go.Figure()
                for lab_, b_, c_ in (("Actual", ba, GOLD), ("Comparada", bb, GLACIER)):
                    f_v.add_bar(x=b_["band"], y=[vv(r_) for _, r_ in b_.iterrows()], name=lab_, marker_color=c_,
                                hovertemplate="%{x} · %{y:.0f} m/h<extra>" + lab_ + "</extra>")
                f_v.update_layout(barmode="group")
                f_v.update_yaxes(ticksuffix=" m/h")
                st.markdown('<span class="note">VAM / velocidad de bajada por pendiente</span>', unsafe_allow_html=True)
                st.plotly_chart(plot_layout(f_v, 280), width="stretch", theme=None)
            with g2_:
                f_h = go.Figure()
                for lab_, b_, c_ in (("Actual", ba, GOLD), ("Comparada", bb, GLACIER)):
                    f_h.add_bar(x=b_["band"], y=b_["hr"], name=lab_, marker_color=c_, hovertemplate="%{x} · %{y:.0f} ppm<extra>" + lab_ + "</extra>")
                f_h.update_layout(barmode="group")
                lo_ = np.nanmin([ba["hr"].min(), bb["hr"].min()]) if ba["hr"].notna().any() or bb["hr"].notna().any() else 100
                hi_ = np.nanmax([ba["hr"].max(), bb["hr"].max()]) if ba["hr"].notna().any() or bb["hr"].notna().any() else 180
                f_h.update_yaxes(range=[max(0, (lo_ if pd.notna(lo_) else 100) - 15), (hi_ if pd.notna(hi_) else 180) + 8], ticksuffix=" ppm")
                st.markdown('<span class="note">FC media por pendiente</span>', unsafe_allow_html=True)
                st.plotly_chart(plot_layout(f_h, 280), width="stretch", theme=None)

            # ── Tramo a tramo ──
            sim_ab = route_similarity(df_a, df_b)
            same_guess = (sim_ab["label"] == "misma ruta") if sim_ab else bool(
                abs(rb["km"] / ra["km"] - 1) <= .05 and abs(rb["dp"] / max(1, ra["dp"]) - 1) <= .07)
            st.subheader("Tramo a tramo")
            t1_, t2_ = st.columns([2, 1], vertical_alignment="bottom")
